head.b:skin:
*{
  margin:0;
  padding:0;
  box-sizing:border-box;
}

:root{
  --azul:#1769aa;
  --azulEscuro:#0d4f82;
  --azulClaro:#eef7ff;
  --empresa:#173f63;
  --admin:#111827;
  --fundo:#f7f9fc;
  --branco:#ffffff;
  --texto:#182230;
  --texto2:#344054;
  --cinza:#667085;
  --cinza2:#98a2b3;
  --borda:#e4e7ec;
  --borda2:#edf0f3;
  --verde:#138a4b;
  --verdeClaro:#ecfdf3;
  --amarelo:#956900;
  --amareloClaro:#fff8df;
  --vermelho:#b42318;
  --vermelhoClaro:#fff3f2;
  --roxo:#6941c6;
  --roxoClaro:#f4f0ff;
  --laranja:#c65d00;
  --laranjaClaro:#fff4e8;
  --sombra:0 7px 26px rgba(16,24,40,.06);
  --sombraHover:0 14px 38px rgba(16,24,40,.11);
}

html{
  scroll-behavior:smooth;
}

body{
  margin:0;
  background:var(--fundo);
  color:var(--texto);
  font-family:'Inter',Arial,sans-serif;
  font-size:14px;
}

button,
input,
select,
textarea{
  font-family:'Inter',Arial,sans-serif;
}

button{
  cursor:pointer;
}

.pagina{
  display:none;
}

.pagina.ativa{
  display:block;
}


/* =====================================================
   TOPO
===================================================== */

.topo{
  position:sticky;
  top:0;
  z-index:3000;
  background:rgba(255,255,255,.97);
  border-bottom:1px solid var(--borda);
  backdrop-filter:blur(14px);
}

.topo-inner{
  max-width:1240px;
  min-height:72px;
  margin:auto;
  padding:0 24px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:20px;
}

.marca{
  border:0;
  background:none;
  display:flex;
  align-items:center;
  gap:10px;
  flex:none;
}

.marca-icone{
  width:38px;
  height:38px;
  border-radius:11px;
  display:flex;
  align-items:center;
  justify-content:center;
  background:linear-gradient(135deg,#1769aa,#38a2e8);
  color:#fff;
  font-size:18px;
  font-weight:800;
}

.marca-nome{
  color:var(--texto);
  font-size:21px;
  font-weight:800;
}

.marca-nome span{
  color:var(--azul);
}

.menu-principal{
  display:flex;
  align-items:center;
  gap:3px;
  margin-right:auto;
}

.menu-link{
  border:0;
  background:none;
  color:var(--cinza);
  padding:10px 11px;
  border-radius:8px;
  font-size:13px;
  font-weight:600;
}

.menu-link:hover{
  color:var(--azul);
  background:#f7f9fb;
}

.acoes-topo{
  display:flex;
  align-items:center;
  gap:7px;
}

.btn{
  border:0;
  border-radius:9px;
  padding:11px 16px;
  font-size:13px;
  font-weight:700;
  transition:.2s;
}

.btn:hover{
  transform:translateY(-1px);
}

.btn-azul{
  background:var(--azul);
  color:#fff;
}

.btn-empresa{
  background:var(--empresa);
  color:#fff;
}

.btn-admin{
  background:var(--admin);
  color:#fff;
}

.btn-claro{
  background:#fff;
  color:var(--texto2);
  border:1px solid var(--borda);
}

.btn-borda{
  background:#fff;
  color:var(--azul);
  border:1px solid #bdd8ed;
}

.btn-verde{
  background:var(--verde);
  color:#fff;
}

.btn-perigo{
  background:#fff;
  color:var(--vermelho);
  border:1px solid #efc4bf;
}

.btn-total{
  width:100%;
}

.btn-grande{
  padding:14px 20px;
}

.oculto{
  display:none !important;
}


/* =====================================================
   CONTA NO TOPO
===================================================== */

.conta-topo{
  position:relative;
  display:none;
}

.conta-topo.ativo{
  display:block;
}

.btn-conta{
  display:flex;
  align-items:center;
  gap:8px;
  border:1px solid var(--borda);
  border-radius:10px;
  background:#fff;
  padding:7px 10px;
}

.avatar{
  width:31px;
  height:31px;
  border-radius:50%;
  display:flex;
  align-items:center;
  justify-content:center;
  background:var(--azulClaro);
  color:var(--azul);
  font-size:13px;
  font-weight:800;
}

.avatar.empresa{
  background:#edf2f7;
  color:var(--empresa);
}

.avatar.admin{
  background:#e8eaf0;
  color:var(--admin);
}

.conta-nome{
  max-width:125px;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  font-size:12px;
  font-weight:700;
}

.conta-menu{
  display:none;
  position:absolute;
  right:0;
  top:52px;
  width:240px;
  padding:8px;
  background:#fff;
  border:1px solid var(--borda);
  border-radius:12px;
  box-shadow:var(--sombraHover);
}

.conta-menu.ativo{
  display:block;
}

.conta-menu button{
  width:100%;
  border:0;
  border-radius:8px;
  background:none;
  padding:11px 12px;
  text-align:left;
  color:var(--texto2);
  font-size:13px;
}

.conta-menu button:hover{
  background:#f5f8fb;
}

.conta-menu .sair{
  color:var(--vermelho);
}


/* =====================================================
   HERO
===================================================== */

.hero{
  padding:82px 24px 72px;
  background:
    linear-gradient(90deg,rgba(8,66,110,.90),rgba(23,105,170,.82)),
    url('https://images.unsplash.com/photo-1758518730384-be3d205838e8?auto=format&fit=crop&fm=jpg&q=85&w=2200') center center/cover no-repeat;
  color:#fff;
}

.hero-inner{
  max-width:1000px;
  margin:auto;
  text-align:center;
}

.hero-selo{
  display:inline-block;
  margin-bottom:17px;
  padding:7px 13px;
  border:1px solid rgba(255,255,255,.2);
  border-radius:40px;
  background:rgba(255,255,255,.08);
  font-size:12px;
}

.hero h1{
  max-width:800px;
  margin:0 auto 13px;
  font-size:45px;
  line-height:1.1;
  letter-spacing:-1.5px;
}

.hero p{
  max-width:680px;
  margin:0 auto 30px;
  color:rgba(255,255,255,.88);
  font-size:17px;
  line-height:1.6;
}

.busca-principal{
  max-width:900px;
  margin:auto;
  padding:8px;
  display:grid;
  grid-template-columns:1.5fr 1fr auto;
  gap:4px;
  background:#fff;
  border-radius:14px;
  box-shadow:0 18px 45px rgba(0,0,0,.16);
}

.busca-campo{
  position:relative;
}

.busca-campo + .busca-campo{
  border-left:1px solid var(--borda);
}

.busca-icone{
  position:absolute;
  left:15px;
  top:50%;
  transform:translateY(-50%);
}

.busca-campo input{
  width:100%;
  border:0;
  outline:0;
  padding:16px 13px 16px 42px;
  font-size:14px;
}

.sugestoes{
  margin-top:20px;
  display:flex;
  align-items:center;
  justify-content:center;
  flex-wrap:wrap;
  gap:8px;
}

.sugestoes-label{
  color:rgba(255,255,255,.7);
  font-size:12px;
}

.sugestao{
  border:1px solid rgba(255,255,255,.23);
  border-radius:30px;
  background:rgba(255,255,255,.08);
  color:#fff;
  padding:7px 12px;
  font-size:12px;
}


/* =====================================================
   ESTRUTURA
===================================================== */

.container{
  max-width:1240px;
  margin:auto;
  padding:50px 24px;
}

.container-menor{
  max-width:900px;
  margin:auto;
  padding:42px 24px 80px;
}

.container-dashboard{
  max-width:1240px;
  margin:auto;
  padding:40px 24px 80px;
}

.titulo-secao{
  margin-bottom:25px;
}

.titulo-secao h2{
  margin-bottom:6px;
  font-size:25px;
}

.titulo-secao p{
  color:var(--cinza);
}


/* =====================================================
   VAGAS
===================================================== */

.destaques{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:17px;
}

.card-destaque,
.vaga-card{
  padding:21px;
  background:#fff;
  border:1px solid var(--borda2);
  border-radius:15px;
}

.card-destaque{
  position:relative;
}

.selo-destaque{
  position:absolute;
  right:14px;
  top:14px;
  padding:5px 8px;
  border-radius:7px;
  background:var(--amareloClaro);
  color:var(--amarelo);
  font-size:10px;
  font-weight:800;
}

.vagas-area{
  display:grid;
  grid-template-columns:minmax(0,1fr) 285px;
  gap:28px;
  align-items:start;
}

.lista-vagas{
  display:flex;
  flex-direction:column;
  gap:12px;
}

.vaga-card:hover{
  box-shadow:var(--sombra);
}

.vaga-card-top{
  display:flex;
  align-items:flex-start;
  gap:15px;
}

.logo-empresa{
  width:58px;
  height:58px;
  flex:none;
  object-fit:contain;
  padding:5px;
  background:#fff;
  border:1px solid var(--borda);
  border-radius:12px;
}

.logo-placeholder{
  width:58px;
  height:58px;
  flex:none;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:12px;
  background:var(--azulClaro);
  color:var(--azul);
  font-size:19px;
  font-weight:800;
}

.vaga-principal{
  flex:1;
}

.vaga-empresa{
  margin-bottom:5px;
  color:var(--azul);
  font-size:12px;
  font-weight:700;
}

.vaga-titulo{
  margin-bottom:10px;
  font-size:18px;
}

.tags{
  display:flex;
  flex-wrap:wrap;
  gap:6px;
}

.tag{
  display:inline-flex;
  padding:6px 8px;
  border-radius:6px;
  background:#f4f6f8;
  color:#475467;
  font-size:11px;
}

.tag-pcd{
  background:#eef7ff;
  color:#0f4f82;
}

.salario{
  margin-top:13px;
  color:var(--verde);
  font-size:13px;
  font-weight:700;
}

.vaga-resumo{
  margin-top:14px;
  color:var(--cinza);
  font-size:13px;
  line-height:1.65;
}

.vaga-card-footer{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:15px;
  margin-top:18px;
  padding-top:16px;
  border-top:1px solid var(--borda2);
}

.vaga-data{
  color:var(--cinza2);
  font-size:11px;
}

.card-acoes{
  display:flex;
  gap:8px;
}

.favorito{
  width:39px;
  height:39px;
  border:1px solid var(--borda);
  border-radius:9px;
  background:#fff;
  color:#667085;
  font-size:20px;
}

.favorito.salvo{
  color:#e5484d;
  border-color:#f0b9b9;
  background:#fff7f7;
}




/* =====================================================
   VAGAS EM DESTAQUE - VISUAL EXCLUSIVO
===================================================== */

.card-destaque{
  position:relative;
  overflow:hidden;
  padding:23px;
  background:
    linear-gradient(180deg,#f4faff 0%,#ffffff 48%);
  border:2px solid #0d4f82;
  border-top:4px solid #0d4f82;
  border-radius:17px;
  box-shadow:0 10px 28px rgba(23,105,170,.09);
  transition:.2s;
}

.card-destaque:hover{
  transform:translateY(-3px);
  border-color:#0a3d66;
  box-shadow:0 16px 36px rgba(23,105,170,.14);
}

.card-destaque .vaga-card-top{
  padding-top:5px;
}

.card-destaque .logo-empresa,
.card-destaque .logo-placeholder{
  width:64px;
  height:64px;
  border-color:#cfe3f2;
  box-shadow:0 5px 14px rgba(16,24,40,.06);
}

.card-destaque .vaga-empresa{
  color:#0d5f9d;
  font-weight:800;
}

.card-destaque .vaga-titulo{
  font-size:19px;
  line-height:1.35;
}

.card-destaque .salario{
  margin-top:14px;
  padding-top:12px;
  border-top:1px solid #dcebf6;
  color:var(--verde);
  font-size:14px;
}

.card-destaque .vaga-card-footer{
  margin-top:18px;
  padding-top:15px;
  border-top:1px solid #dcebf6;
}

.card-destaque .btn-azul{
  box-shadow:0 5px 14px rgba(23,105,170,.18);
}

.card-destaque .selo-destaque{
  right:14px;
  top:14px;
  padding:6px 9px;
  background:#0d4f82;
  border:1px solid #0a3d66;
  color:#ffffff;
  letter-spacing:.25px;
}



.card-destaque .selo-destaque{
  display:inline-flex;
  align-items:center;
  gap:6px;
  font-weight:800;
  text-transform:uppercase;
}

.card-destaque .estrela-destaque{
  color:#ffd54a;
  font-size:13px;
  line-height:1;
  display:inline-block;
}


/* Nas vagas comuns a pr&#233;via fica mais limpa e sem logo */
.vaga-card .vaga-card-top{
  display:block;
}

.vaga-card .vaga-principal{
  width:100%;
}

.vaga-card .vaga-empresa{
  display:inline-block;
  margin-bottom:7px;
  padding:4px 7px;
  border-radius:6px;
  background:#f4f7fa;
  color:#475467;
  font-size:10px;
  font-weight:700;
}

.vaga-card .vaga-titulo{
  margin-bottom:11px;
  font-size:18px;
}

@media(max-width:520px){
  .card-destaque{
    padding:20px;
  }

  .card-destaque .logo-empresa,
  .card-destaque .logo-placeholder{
    width:56px;
    height:56px;
  }
}


/* =====================================================
   FILTROS
===================================================== */

.filtros-rapidos{
  display:flex;
  gap:8px;
  overflow-x:auto;
  margin-bottom:20px;
}

.filtro-pill{
  flex:none;
  padding:9px 14px;
  border:1px solid #ced6df;
  border-radius:30px;
  background:#fff;
  color:var(--texto2);
  font-size:12px;
}

.filtros-lateral{
  position:sticky;
  top:92px;
  padding:20px;
  background:#fff;
  border:1px solid var(--borda2);
  border-radius:15px;
}

.filtros-cab{
  display:flex;
  align-items:center;
  justify-content:space-between;
  margin-bottom:18px;
}

.limpar-link{
  border:0;
  background:none;
  color:var(--azul);
  font-size:11px;
  font-weight:700;
}

.grupo{
  margin-bottom:16px;
}

.grupo label{
  display:block;
  margin-bottom:7px;
  color:var(--texto2);
  font-size:12px;
  font-weight:700;
}

.campo{
  width:100%;
  padding:12px;
  border:1px solid #d0d5dd;
  border-radius:9px;
  outline:0;
  background:#fff;
  color:var(--texto);
  font-size:13px;
}

.campo:focus{
  border-color:var(--azul);
  box-shadow:0 0 0 3px rgba(23,105,170,.08);
}

textarea.campo{
  min-height:140px;
  resize:vertical;
}

.vagas-toolbar{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:15px;
  margin-bottom:16px;
}

.resultados{
  color:var(--cinza);
  font-size:13px;
}

.ordenacao{
  display:flex;
  align-items:center;
  gap:7px;
  color:var(--cinza);
  font-size:12px;
}

.ordenacao select{
  padding:9px;
  border:1px solid var(--borda);
  border-radius:8px;
  background:#fff;
}

.sem-vaga,
.vazio{
  padding:42px 25px;
  border:1px solid var(--borda2);
  border-radius:14px;
  background:#fff;
  color:var(--cinza);
  text-align:center;
}

.sem-vaga{
  display:none;
}

.btn-mobile-filtros{
  display:none;
}


/* =====================================================
   PAGE HEADER
===================================================== */

.page-header{
  background:#fff;
  border-bottom:1px solid var(--borda2);
}

.page-header.empresa-header{
  background:#f6f9fc;
  border-top:4px solid var(--empresa);
}

.page-header.admin-header{
  background:#f7f7f8;
  border-top:4px solid var(--admin);
}

.page-header-inner{
  max-width:1180px;
  margin:auto;
  padding:30px 24px;
}

.page-header h1{
  margin-bottom:6px;
  font-size:29px;
}

.page-header p{
  color:var(--cinza);
}

.voltar{
  margin-bottom:15px;
  border:0;
  background:none;
  color:var(--azul);
  font-size:12px;
  font-weight:700;
}


/* =====================================================
   DETALHE DA VAGA
===================================================== */

.detalhe-layout{
  max-width:1180px;
  margin:auto;
  padding:35px 24px 80px;
  display:grid;
  grid-template-columns:minmax(0,1fr) 310px;
  gap:28px;
  align-items:start;
}

.vaga-cabecalho,
.conteudo-vaga-box,
.aplicar-lateral,
.form-card{
  background:#fff;
  border:1px solid var(--borda2);
  border-radius:15px;
}

.vaga-cabecalho{
  padding:27px;
  margin-bottom:17px;
}

.vaga-cabecalho-top{
  display:flex;
  gap:18px;
}

.logo-detalhe{
  width:78px;
  height:78px;
  object-fit:contain;
  padding:6px;
  border:1px solid var(--borda);
  border-radius:14px;
}

.vaga-cab-empresa{
  margin-bottom:10px;
  color:var(--azul);
  font-size:13px;
  font-weight:700;
}

.vaga-cabecalho h1{
  margin-bottom:12px;
  font-size:26px;
}

.info-faixa{
  margin-top:22px;
  padding-top:19px;
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:14px;
  border-top:1px solid var(--borda2);
}

.info-item span{
  display:block;
  margin-bottom:5px;
  color:var(--cinza2);
  font-size:10px;
  text-transform:uppercase;
}

.info-item strong{
  font-size:12px;
}

.conteudo-vaga-box{
  padding:29px;
}

.bloco-detalhe{
  margin-bottom:31px;
}

.bloco-detalhe:last-child{
  margin-bottom:0;
}

.bloco-detalhe h2{
  margin-bottom:12px;
  font-size:17px;
}

.bloco-detalhe p{
  color:var(--cinza);
  font-size:13px;
  line-height:1.8;
  white-space:pre-line;
}

.aplicar-lateral{
  position:sticky;
  top:92px;
  padding:22px;
  box-shadow:var(--sombra);
}

.aplicar-lateral h3{
  margin-bottom:8px;
  font-size:17px;
}

.aplicar-bloco-principal > p{
  margin-bottom:17px;
  color:var(--cinza);
  font-size:12px;
  line-height:1.65;
}

.vaga-publicacao-lateral{
  margin-top:22px;
  padding-top:19px;
  border-top:1px solid var(--borda2);
}

.publicacao-item{
  display:flex;
  align-items:center;
  gap:5px;
  margin-bottom:15px;
  color:var(--cinza);
  font-size:12px;
}

.empresa-lateral{
  margin-top:22px;
  padding-top:21px;
  border-top:1px solid var(--borda2);
}

.empresa-lateral h3{
  margin-bottom:11px;
  font-size:15px;
}

.empresa-lateral p{
  color:var(--cinza);
  font-size:12px;
  line-height:1.75;
  white-space:pre-line;
}

.mobile-candidatar{
  display:none;
}


/* =====================================================
   FORM
===================================================== */

.form-card{
  padding:29px;
}

.login-container{
  max-width:520px;
}

.linha{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:15px;
}

.login-tipo{
  display:inline-block;
  margin-bottom:20px;
  padding:7px 10px;
  border-radius:20px;
  background:var(--azulClaro);
  color:var(--azul);
  font-size:11px;
  font-weight:700;
}

.login-tipo.empresa{
  background:#edf2f7;
  color:var(--empresa);
}

.login-tipo.admin{
  background:#eaecf0;
  color:var(--admin);
}

.login-ajuda{
  margin-top:20px;
  color:var(--cinza);
  text-align:center;
  font-size:12px;
}

.login-ajuda button{
  border:0;
  background:none;
  color:var(--azul);
  font-weight:700;
}


/* =====================================================
   DASHBOARDS
===================================================== */

.dashboard-topo{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:20px;
  margin-bottom:25px;
}

.dashboard-topo h1{
  margin-bottom:5px;
  font-size:28px;
}

.dashboard-topo p{
  color:var(--cinza);
}

.dashboard-nav{
  display:flex;
  gap:8px;
  flex-wrap:wrap;
  margin-bottom:24px;
}

.dashboard-nav button{
  padding:10px 13px;
  border:1px solid var(--borda);
  border-radius:8px;
  background:#fff;
  color:var(--texto2);
  font-size:12px;
  font-weight:700;
}

.metricas{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:14px;
  margin-bottom:25px;
}

.metrica{
  padding:20px;
  background:#fff;
  border:1px solid var(--borda2);
  border-radius:14px;
}

.metrica span{
  display:block;
  margin-bottom:8px;
  color:var(--cinza);
  font-size:11px;
}

.metrica strong{
  font-size:24px;
}

.painel-candidato-grid{
  display:grid;
  grid-template-columns:repeat(2,1fr);
  gap:16px;
}

.painel-card{
  padding:23px;
  background:#fff;
  border:1px solid var(--borda2);
  border-radius:14px;
}

.painel-card h3{
  margin-bottom:7px;
  font-size:16px;
}

.painel-card p{
  min-height:42px;
  margin-bottom:15px;
  color:var(--cinza);
  font-size:12px;
  line-height:1.6;
}

.admin-barra{
  display:grid;
  grid-template-columns:minmax(0,1fr) 190px;
  gap:10px;
  margin-bottom:16px;
}

.admin-lista{
  display:flex;
  flex-direction:column;
  gap:13px;
}

.admin-vaga{
  padding:20px;
  background:#fff;
  border:1px solid var(--borda2);
  border-radius:14px;
}

.admin-vaga-top{
  display:flex;
  justify-content:space-between;
  gap:15px;
  align-items:flex-start;
}

.admin-vaga h3{
  margin-bottom:7px;
  font-size:17px;
}

.admin-vaga-meta{
  color:var(--cinza);
  font-size:11px;
  line-height:1.65;
}

.admin-vaga-info{
  margin:16px 0;
  padding:14px 0;
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:10px;
  border-top:1px solid var(--borda2);
  border-bottom:1px solid var(--borda2);
}

.admin-info span{
  display:block;
  margin-bottom:4px;
  color:var(--cinza2);
  font-size:10px;
}

.admin-info strong{
  font-size:12px;
}

.admin-acoes{
  display:flex;
  gap:7px;
  flex-wrap:wrap;
}

.admin-acoes .btn{
  padding:9px 11px;
  font-size:11px;
}


/* =====================================================
   STATUS
===================================================== */

.status-admin,
.status-processo{
  display:inline-block;
  padding:6px 9px;
  border-radius:20px;
  font-size:10px;
  font-weight:800;
  white-space:nowrap;
}

.status-aprovada,
.status-ativa,
.status-selecionado{
  background:var(--verdeClaro);
  color:var(--verde);
}

.status-pendente,
.status-analise{
  background:var(--amareloClaro);
  color:var(--amarelo);
}

.status-rejeitada,
.status-encerrada,
.status-reprovado{
  background:var(--vermelhoClaro);
  color:var(--vermelho);
}

.status-expirada{
  background:#f2f4f7;
  color:#667085;
}

.status-entrevista{
  background:var(--roxoClaro);
  color:var(--roxo);
}

.status-pre{
  background:var(--laranjaClaro);
  color:var(--laranja);
}


/* =====================================================
   CURR&#205;CULO
===================================================== */

.curriculo-box{
  padding:26px;
  background:#fff;
  border:1px solid var(--borda2);
  border-radius:15px;
}

.curriculo-status{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:18px;
  margin-bottom:22px;
  padding:18px;
  border-radius:12px;
  background:#f7fafc;
}

.curriculo-status h3{
  margin-bottom:5px;
  font-size:15px;
}

.curriculo-status p{
  color:var(--cinza);
  font-size:12px;
}

.curriculo-ok,
.curriculo-nao{
  display:inline-block;
  padding:6px 9px;
  border-radius:20px;
  font-size:10px;
  font-weight:800;
}

.curriculo-ok{
  background:var(--verdeClaro);
  color:var(--verde);
}

.curriculo-nao{
  background:#f2f4f7;
  color:#667085;
}

.upload-curriculo{
  padding:25px;
  border:2px dashed #ccd5df;
  border-radius:12px;
  background:#fafbfc;
  text-align:center;
}


/* =====================================================
   CANDIDATURAS
===================================================== */

.candidatura-item,
.candidato-admin-card{
  margin-bottom:12px;
  padding:19px;
  background:#fff;
  border:1px solid var(--borda2);
  border-radius:14px;
}

.candidatura-top,
.candidato-admin-top{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:15px;
}

.candidatura-item h3,
.candidato-admin-card h3{
  margin-bottom:5px;
  font-size:16px;
}

.candidatura-item p,
.candidato-admin-card p{
  color:var(--cinza);
  font-size:11px;
  line-height:1.7;
}

.candidato-acoes{
  display:grid;
  grid-template-columns:minmax(0,1fr) auto;
  gap:10px;
  margin-top:15px;
}

.candidato-acoes select{
  padding:11px;
  border:1px solid var(--borda);
  border-radius:9px;
  background:#fff;
}


/* =====================================================
   PLANOS / LOGO
===================================================== */

.logo-upload-box{
  padding:23px;
  border:2px dashed #d6dce5;
  border-radius:12px;
  background:#fafbfc;
  text-align:center;
}

.logo-upload-preview{
  display:none;
  width:90px;
  height:90px;
  object-fit:contain;
  margin:0 auto 15px;
  padding:5px;
  border:1px solid var(--borda);
  border-radius:12px;
}

.planos{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:12px;
}

.plano{
  padding:17px 12px;
  border:2px solid var(--borda);
  border-radius:12px;
  background:#fff;
  text-align:center;
  cursor:pointer;
}

.plano.ativo{
  border-color:var(--azul);
  background:#f7fbff;
}

.plano input{
  display:none;
}

.plano span{
  display:block;
}

.plano-titulo{
  font-weight:800;
  font-size:12px;
}

.plano-preco{
  margin-top:6px;
  color:var(--azul);
  font-size:21px;
  font-weight:800;
}

.plano-dias{
  margin-top:5px;
  color:var(--cinza);
  font-size:10px;
}

.resumo-plano{
  margin:18px 0;
  padding:14px;
  background:#f9fafb;
  border:1px solid var(--borda);
  border-radius:10px;
  font-size:12px;
  line-height:1.7;
}




/* =====================================================
   EMPRESAS QUE EST&#195;O CONTRATANDO
===================================================== */

.empresas-contratando{
  padding:48px 24px 52px;
  background:#ffffff;
  border-top:1px solid var(--borda2);
  border-bottom:1px solid var(--borda2);
  overflow:hidden;
}

.empresas-contratando-inner{
  max-width:1240px;
  margin:auto;
}

.empresas-contratando-cab{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:20px;
  margin-bottom:23px;
}

.empresas-contratando-cab h2{
  margin-bottom:6px;
  font-size:24px;
  color:var(--texto);
}

.empresas-contratando-cab p{
  color:var(--cinza);
  font-size:13px;
}

.empresas-carrossel-wrap{
  position:relative;
  overflow:hidden;
  padding:5px 0;
}

.empresas-carrossel-wrap:before,
.empresas-carrossel-wrap:after{
  content:"";
  position:absolute;
  top:0;
  bottom:0;
  width:70px;
  z-index:5;
  pointer-events:none;
}

.empresas-carrossel-wrap:before{
  left:0;
  background:linear-gradient(90deg,#fff,rgba(255,255,255,0));
}

.empresas-carrossel-wrap:after{
  right:0;
  background:linear-gradient(270deg,#fff,rgba(255,255,255,0));
}

.empresas-carrossel{
  display:flex;
  width:max-content;
  min-width:100%;
  justify-content:center;
  gap:14px;
  animation:empresasRolando 28s linear infinite;
}

.empresas-carrossel:hover{
  animation-play-state:paused;
}

.empresa-logo-card{
  width:170px;
  height:96px;
  flex:none;
  display:flex;
  align-items:center;
  justify-content:center;
  padding:17px;
  border:1px solid var(--borda);
  border-radius:14px;
  background:#fff;
  box-shadow:0 4px 16px rgba(16,24,40,.04);
  cursor:pointer;
  transition:.2s;
}

.empresa-logo-card:hover{
  transform:translateY(-2px);
  border-color:#bdd8ed;
  box-shadow:var(--sombra);
}

.empresa-logo-card img{
  width:100%;
  height:100%;
  object-fit:contain;
}

.empresa-logo-placeholder{
  width:54px;
  height:54px;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:13px;
  background:var(--azulClaro);
  color:var(--azul);
  font-size:19px;
  font-weight:800;
}

.empresa-logo-nome{
  max-width:105px;
  margin-left:10px;
  color:var(--texto2);
  font-size:11px;
  font-weight:700;
  line-height:1.35;
}

.empresas-vazio{
  padding:25px;
  border:1px dashed var(--borda);
  border-radius:12px;
  color:var(--cinza);
  text-align:center;
  font-size:12px;
}

@keyframes empresasRolando{
  from{transform:translateX(0);}
  to{transform:translateX(-50%);}
}

@media(max-width:720px){
  .empresas-contratando{
    padding:38px 15px 42px;
  }

  .empresas-contratando-cab{
    align-items:flex-start;
    flex-direction:column;
  }

  .empresas-contratando-cab h2{
    font-size:21px;
  }

  .empresa-logo-card{
    width:145px;
    height:86px;
    padding:14px;
  }

  .empresas-carrossel-wrap:before,
  .empresas-carrossel-wrap:after{
    width:30px;
  }
}

@media (prefers-reduced-motion: reduce){
  .empresas-carrossel{
    animation:none;
  }
}




/* =====================================================
   HOME EM BLOCOS - VISUAL MAIS FECHADO
===================================================== */

.home-estatisticas{
  max-width:1240px;
  margin:-30px auto 10px;
  padding:0 24px;
  position:relative;
  z-index:10;
}

.home-estatisticas-grid{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:14px;
}

.home-estatistica{
  min-height:100px;
  display:flex;
  align-items:center;
  gap:14px;
  padding:20px;
  background:#fff;
  border:1px solid #dfe6ee;
  border-radius:15px;
  box-shadow:0 8px 28px rgba(16,24,40,.06);
}

.home-estatistica-icone{
  width:46px;
  height:46px;
  flex:none;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:12px;
  background:var(--azulClaro);
  color:var(--azul);
  font-size:20px;
  font-weight:800;
}

.home-estatistica strong{
  display:block;
  margin-bottom:4px;
  color:var(--texto);
  font-size:22px;
  line-height:1;
}

.home-estatistica span{
  color:var(--cinza);
  font-size:11px;
}

.home-bloco{
  max-width:1240px;
  margin:0 auto;
  padding:38px 24px;
}

.home-bloco-cab{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:18px;
  margin-bottom:20px;
}

.home-bloco-cab h2{
  margin-bottom:5px;
  font-size:24px;
}

.home-bloco-cab p{
  color:var(--cinza);
  font-size:13px;
}

.home-vagas-caixa{
  max-width:1240px;
  margin:20px auto 48px;
  padding:28px;
  background:#fff;
  border:1px solid #dbe3ec;
  border-radius:20px;
  box-shadow:0 8px 30px rgba(16,24,40,.04);
}

.home-vagas-caixa .titulo-secao{
  padding-bottom:20px;
  border-bottom:1px solid var(--borda2);
}

.home-vagas-caixa .vagas-area{
  margin-top:4px;
}

.home-vagas-caixa .filtros-rapidos{
  padding-bottom:18px;
  border-bottom:1px solid var(--borda2);
}

.vaga-card,
.card-destaque{
  border:1px solid #dce3eb;
  border-radius:16px;
  box-shadow:0 4px 14px rgba(16,24,40,.035);
}

.vaga-card{
  position:relative;
  overflow:hidden;
}

.vaga-card:before{
  content:"";
  position:absolute;
  left:0;
  top:0;
  bottom:0;
  width:3px;
  background:#d5e9f8;
}

.vaga-card:hover,
.card-destaque:hover{
  border-color:#b9d5e9;
  box-shadow:0 12px 28px rgba(16,24,40,.08);
}

.home-areas{
  max-width:1240px;
  margin:0 auto 44px;
  padding:0 24px;
}

.home-areas-box{
  padding:28px;
  background:#fff;
  border:1px solid #dbe3ec;
  border-radius:20px;
}

.home-areas-grid{
  display:grid;
  grid-template-columns:repeat(6,1fr);
  gap:12px;
}

.home-area-card{
  min-height:112px;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:9px;
  padding:15px 10px;
  border:1px solid #e0e6ed;
  border-radius:14px;
  background:#fff;
  color:var(--texto2);
  text-align:center;
  transition:.2s;
}

.home-area-card:hover{
  transform:translateY(-2px);
  border-color:#bdd8ed;
  background:#f8fbfe;
}

.home-area-icone{
  width:40px;
  height:40px;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:10px;
  background:var(--azulClaro);
  color:var(--azul);
  font-size:18px;
  font-weight:800;
}

.home-area-card strong{
  font-size:12px;
}

/* Carrossel de empresas somente na home e centralizado */

.empresas-contratando{
  padding:48px 24px 52px;
  background:#eef7ff;
  border-top:1px solid #dcebf7;
  border-bottom:1px solid #dcebf7;
  overflow:hidden;
}

.empresas-contratando-inner{
  max-width:1180px;
  margin:auto;
  text-align:center;
}

.empresas-contratando-cab{
  display:block;
  margin-bottom:24px;
  text-align:center;
}

.empresas-contratando-cab h2{
  margin-bottom:7px;
  font-size:25px;
  color:var(--texto);
}

.empresas-contratando-cab p{
  color:var(--cinza);
  font-size:13px;
}

.empresas-carrossel-wrap{
  max-width:1060px;
  margin:0 auto;
  position:relative;
  overflow:hidden;
  padding:6px 0;
}

.empresas-carrossel-wrap:before{
  background:linear-gradient(90deg,#eef7ff,rgba(238,247,255,0));
}

.empresas-carrossel-wrap:after{
  background:linear-gradient(270deg,#eef7ff,rgba(238,247,255,0));
}

.empresa-logo-card{
  width:155px;
  height:88px;
  border:1px solid #d8e3ec;
  border-radius:13px;
  background:#fff;
}

.cta-empresa{
  border-top:0;
}

@media(max-width:1050px){
  .home-estatisticas-grid{
    grid-template-columns:repeat(2,1fr);
  }

  .home-areas-grid{
    grid-template-columns:repeat(3,1fr);
  }
}

@media(max-width:720px){
  .home-estatisticas{
    margin:18px auto 0;
    padding:0 15px;
  }

  .home-estatisticas-grid{
    grid-template-columns:1fr 1fr;
    gap:10px;
  }

  .home-estatistica{
    min-height:92px;
    padding:14px;
    gap:10px;
  }

  .home-estatistica-icone{
    width:38px;
    height:38px;
    font-size:16px;
  }

  .home-estatistica strong{
    font-size:18px;
  }

  .home-estatistica span{
    font-size:10px;
  }

  .home-vagas-caixa{
    margin:15px 15px 35px;
    padding:18px 14px;
    border-radius:16px;
  }

  .home-areas{
    padding:0 15px;
    margin-bottom:35px;
  }

  .home-areas-box{
    padding:20px 14px;
    border-radius:16px;
  }

  .home-areas-grid{
    grid-template-columns:repeat(2,1fr);
  }

  .home-bloco-cab{
    align-items:flex-start;
    flex-direction:column;
  }

  .empresas-contratando{
    padding:38px 15px 42px;
  }
}

@media(max-width:420px){
  .home-estatisticas-grid{
    grid-template-columns:1fr;
  }

  .home-areas-grid{
    grid-template-columns:1fr 1fr;
  }
}








/* =====================================================
   MELHORIAS VISUAIS GERAIS
===================================================== */

.pagina{
  animation:paginaEntrada .22s ease;
}

@keyframes paginaEntrada{
  from{opacity:.35;transform:translateY(5px);}
  to{opacity:1;transform:none;}
}

.breadcrumbs{
  display:flex;
  align-items:center;
  gap:7px;
  margin-bottom:14px;
  color:var(--cinza);
  font-size:11px;
}

.breadcrumbs button{
  padding:0;
  border:0;
  background:none;
  color:var(--azul);
  font:inherit;
  font-weight:700;
}

.institucional-hero{
  padding:62px 24px;
  background:linear-gradient(135deg,#0d4f82,#1769aa);
  color:#fff;
  text-align:center;
}

.institucional-hero .inner{
  max-width:820px;
  margin:auto;
}

.institucional-hero span{
  display:inline-block;
  margin-bottom:13px;
  padding:7px 11px;
  border:1px solid rgba(255,255,255,.22);
  border-radius:30px;
  background:rgba(255,255,255,.08);
  font-size:10px;
  font-weight:800;
  text-transform:uppercase;
  letter-spacing:.5px;
}

.institucional-hero h1{
  margin-bottom:10px;
  font-size:36px;
  line-height:1.18;
}

.institucional-hero p{
  max-width:650px;
  margin:auto;
  color:rgba(255,255,255,.87);
  font-size:14px;
  line-height:1.75;
}

.secao-visual{
  max-width:1180px;
  margin:auto;
  padding:54px 24px;
}

.secao-visual-cab{
  max-width:700px;
  margin:0 auto 28px;
  text-align:center;
}

.secao-visual-cab h2{
  margin-bottom:8px;
  font-size:27px;
}

.secao-visual-cab p{
  color:var(--cinza);
  font-size:13px;
  line-height:1.7;
}

.beneficios-grid{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:15px;
}

.beneficio-card{
  padding:22px;
  border:1px solid #dce5ed;
  border-radius:16px;
  background:#fff;
  box-shadow:0 7px 22px rgba(16,24,40,.04);
}

.beneficio-icone{
  width:43px;
  height:43px;
  margin-bottom:15px;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:12px;
  background:#eaf5fc;
  color:var(--azul);
}

.beneficio-icone svg{
  width:22px;
  height:22px;
  fill:none;
  stroke:currentColor;
  stroke-width:1.9;
  stroke-linecap:round;
  stroke-linejoin:round;
}

.beneficio-card h3{
  margin-bottom:7px;
  font-size:15px;
}

.beneficio-card p{
  color:var(--cinza);
  font-size:11px;
  line-height:1.65;
}

.passos-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:18px;
}

.passo-card{
  position:relative;
  padding:25px;
  border:1px solid #dfe6ed;
  border-radius:17px;
  background:#fff;
}

.passo-numero{
  width:34px;
  height:34px;
  margin-bottom:15px;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:50%;
  background:var(--azul);
  color:#fff;
  font-size:12px;
  font-weight:800;
}

.passo-card h3{
  margin-bottom:7px;
  font-size:16px;
}

.passo-card p{
  color:var(--cinza);
  font-size:12px;
  line-height:1.65;
}

.faq-lista{
  max-width:850px;
  margin:auto;
  display:grid;
  gap:10px;
}

.faq-item{
  overflow:hidden;
  border:1px solid #dfe6ed;
  border-radius:13px;
  background:#fff;
}

.faq-pergunta{
  width:100%;
  padding:17px 19px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:15px;
  border:0;
  background:#fff;
  color:var(--texto);
  text-align:left;
  font-size:13px;
  font-weight:800;
}

.faq-pergunta span:last-child{
  color:var(--azul);
  font-size:17px;
}

.faq-resposta{
  display:none;
  padding:0 19px 18px;
  color:var(--cinza);
  font-size:12px;
  line-height:1.7;
}

.faq-item.aberto .faq-resposta{
  display:block;
}

.empresa-venda-box{
  display:grid;
  grid-template-columns:1.15fr .85fr;
  gap:26px;
  align-items:center;
  padding:32px;
  border:1px solid #cfe2f0;
  border-radius:22px;
  background:linear-gradient(135deg,#f7fbff,#eef7fd);
}

.empresa-venda-box h2{
  margin-bottom:10px;
  font-size:27px;
}

.empresa-venda-box p{
  color:var(--cinza);
  font-size:13px;
  line-height:1.7;
}

.empresa-venda-lista{
  display:grid;
  gap:9px;
  margin-top:18px;
}

.empresa-venda-lista div{
  display:flex;
  align-items:center;
  gap:9px;
  color:var(--texto2);
  font-size:12px;
  font-weight:650;
}

.empresa-venda-lista i{
  width:22px;
  height:22px;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:50%;
  background:#dff2e7;
  color:#157347;
  font-style:normal;
  font-size:10px;
  font-weight:900;
}

.empresa-venda-acao{
  padding:25px;
  border:1px solid #d8e5ef;
  border-radius:17px;
  background:#fff;
}

.empresa-venda-acao h3{
  margin-bottom:8px;
  font-size:17px;
}

.empresa-venda-acao p{
  margin-bottom:18px;
  font-size:11px;
}

/* =====================================================
   PAINEL EMPRESA - VISUAL SAAS
===================================================== */

.container-dashboard.painel-empresa-layout{
  max-width:1280px;
  display:grid;
  grid-template-columns:225px minmax(0,1fr);
  gap:22px;
  align-items:start;
}

.painel-empresa-sidebar{
  position:sticky;
  top:82px;
  padding:17px;
  border:1px solid #dfe6ed;
  border-radius:17px;
  background:#fff;
  box-shadow:0 7px 22px rgba(16,24,40,.035);
}

.painel-sidebar-empresa{
  padding:5px 4px 16px;
  margin-bottom:12px;
  border-bottom:1px solid var(--borda2);
}

.painel-sidebar-empresa strong{
  display:block;
  overflow:hidden;
  color:var(--texto);
  font-size:13px;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.painel-sidebar-empresa span{
  display:inline-flex;
  margin-top:7px;
  padding:5px 8px;
  border-radius:20px;
  background:#eaf5fc;
  color:var(--azul);
  font-size:9px;
  font-weight:800;
  text-transform:uppercase;
  letter-spacing:.35px;
}

.painel-side-nav{
  display:grid;
  gap:5px;
}

.painel-side-nav button{
  width:100%;
  padding:11px 11px;
  border:0;
  border-radius:9px;
  background:transparent;
  color:var(--texto2);
  text-align:left;
  font-size:11px;
  font-weight:700;
}

.painel-side-nav button:hover,
.painel-side-nav button.ativo{
  background:#edf6fc;
  color:var(--azul);
}

.painel-side-nav button.publicar{
  margin-top:6px;
  background:var(--azul);
  color:#fff;
}

.painel-side-nav button.sair{
  margin-top:11px;
  border-top:1px solid var(--borda2);
  border-radius:0;
  color:#b42318;
}

.painel-plano-mini{
  margin-top:15px;
  padding:13px;
  border:1px solid #dce8f1;
  border-radius:11px;
  background:#f8fbfe;
}

.painel-plano-mini-top{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
}

.painel-plano-mini strong{
  font-size:11px;
}

.painel-plano-mini span{
  color:var(--azul);
  font-size:9px;
  font-weight:800;
}

.painel-plano-mini p{
  margin:7px 0;
  color:var(--cinza);
  font-size:9px;
}

.painel-plano-barra{
  height:6px;
  overflow:hidden;
  border-radius:20px;
  background:#e3eaf0;
}

.painel-plano-barra div{
  width:0;
  height:100%;
  border-radius:20px;
  background:var(--azul);
}

.painel-plano-mini button{
  margin-top:9px;
  padding:0;
  border:0;
  background:none;
  color:var(--azul);
  font-size:9px;
  font-weight:800;
}

.painel-empresa-main{
  min-width:0;
}

#pagina-painel-empresa .dashboard-nav{
  display:none;
}

#pagina-painel-empresa .metrica{
  position:relative;
  overflow:hidden;
  transition:.18s ease;
}

#pagina-painel-empresa .metrica:hover{
  transform:translateY(-2px);
  box-shadow:0 9px 24px rgba(16,24,40,.06);
}

.painel-recursos{
  margin:0 0 24px;
  padding:20px;
  border:1px solid #dfe6ed;
  border-radius:15px;
  background:#fff;
}

.painel-recursos h3{
  margin-bottom:5px;
  font-size:15px;
}

.painel-recursos>p{
  margin-bottom:14px;
  color:var(--cinza);
  font-size:11px;
}

.painel-recursos-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:10px;
}

.painel-recurso{
  padding:13px;
  border:1px solid var(--borda2);
  border-radius:10px;
  background:#fafcfd;
}

.painel-recurso strong{
  display:block;
  margin-bottom:4px;
  font-size:11px;
}

.painel-recurso span{
  color:var(--cinza);
  font-size:9px;
  line-height:1.5;
}

.estado-vazio-bonito{
  padding:42px 22px;
  border:1px dashed #cbd8e3;
  border-radius:15px;
  background:#fafcfe;
  text-align:center;
}

.estado-vazio-bonito svg{
  width:38px;
  height:38px;
  margin-bottom:12px;
  fill:none;
  stroke:#7894aa;
  stroke-width:1.6;
  stroke-linecap:round;
  stroke-linejoin:round;
}

.estado-vazio-bonito h3{
  margin-bottom:6px;
  font-size:15px;
}

.estado-vazio-bonito p{
  max-width:470px;
  margin:0 auto 16px;
  color:var(--cinza);
  font-size:11px;
  line-height:1.6;
}

.mobile-publicar-empresa{
  display:none;
}

/* =====================================================
   TOAST
===================================================== */

.toast-site{
  position:fixed;
  right:20px;
  bottom:20px;
  z-index:9999;
  max-width:330px;
  padding:13px 16px;
  border-radius:11px;
  background:#102f49;
  color:#fff;
  box-shadow:0 12px 35px rgba(0,0,0,.18);
  font-size:11px;
  line-height:1.5;
  opacity:0;
  pointer-events:none;
  transform:translateY(10px);
  transition:.22s;
}

.toast-site.visivel{
  opacity:1;
  transform:none;
}

/* =====================================================
   HOME - BENEFICIOS
===================================================== */

.home-beneficios{
  max-width:1240px;
  margin:0 auto 44px;
  padding:0 24px;
}

.home-beneficios-box{
  padding:28px;
  border:1px solid #dce5ed;
  border-radius:20px;
  background:#fff;
}

.home-beneficios-box .beneficios-grid{
  margin-top:20px;
}

@media(max-width:980px){
  .beneficios-grid{
    grid-template-columns:repeat(2,1fr);
  }

  .container-dashboard.painel-empresa-layout{
    grid-template-columns:1fr;
  }

  .painel-empresa-sidebar{
    position:static;
  }

  .painel-side-nav{
    grid-template-columns:repeat(3,1fr);
  }

  .painel-side-nav button{
    text-align:center;
  }

  .painel-side-nav button.sair{
    display:none;
  }

  .painel-plano-mini{
    display:none;
  }

  .empresa-venda-box{
    grid-template-columns:1fr;
  }
}

@media(max-width:650px){
  .institucional-hero{
    padding:45px 16px;
  }

  .institucional-hero h1{
    font-size:29px;
  }

  .secao-visual{
    padding:38px 15px;
  }

  .beneficios-grid,
  .passos-grid,
  .painel-recursos-grid{
    grid-template-columns:1fr;
  }

  .painel-side-nav{
    grid-template-columns:1fr 1fr;
  }

  .painel-side-nav button.publicar{
    grid-column:1/-1;
  }

  .home-beneficios{
    padding:0 15px;
  }

  .home-beneficios-box{
    padding:20px 15px;
  }

  .mobile-publicar-empresa{
    display:block;
    position:fixed;
    right:16px;
    bottom:18px;
    z-index:3300;
  }

  .mobile-publicar-empresa button{
    width:52px;
    height:52px;
    border:0;
    border-radius:50%;
    background:var(--azul);
    color:#fff;
    box-shadow:0 10px 28px rgba(23,105,170,.28);
    font-size:24px;
    font-weight:700;
  }
}






/* =====================================================
   AJUSTE DE ESCALA VISUAL - FONTE MAIOR E SITE MAIS LARGO
===================================================== */

body{
  font-size:16px;
}

/* aumenta a largura &#250;til nas principais &#225;reas */
.container,
.container-dashboard,
.home-vagas-caixa,
.empresas-contratando .inner{
  max-width:1380px;
}

/* p&#225;ginas de formul&#225;rio deixam de parecer estreitas */
.formulario-container,
.publicar-container,
.login-container{
  max-width:1120px;
}

/* textos que estavam excessivamente pequenos */
label{
  font-size:13px;
}

.campo,
select.campo,
textarea.campo{
  font-size:14px;
}

.contato-candidatura-box{
  padding:25px;
}

.contato-candidatura-topo h3{
  font-size:18px;
}

.contato-candidatura-topo p{
  font-size:12px;
}

.contato-plano-selo{
  padding:7px 11px;
  font-size:10px;
}

.contato-opcao label{
  min-height:92px;
  padding:16px;
}

.contato-opcao label strong{
  font-size:14px;
}

.contato-opcao label span{
  font-size:11px;
}

.contato-opcao-premium{
  font-size:9px !important;
}

.contato-ajuda,
.contato-upgrade-aviso{
  font-size:11px;
}

.publicacao-plano-atual h3,
.plano-publicacao-box h3{
  font-size:17px;
}

.publicacao-plano-atual p,
.plano-publicacao-box p{
  font-size:12px;
}

/* dashboard */
.dashboard-topo h1{
  font-size:27px;
}

.dashboard-topo p{
  font-size:13px;
}

.metrica strong{
  font-size:24px;
}

.metrica span{
  font-size:11px;
}

.painel-side-nav button{
  font-size:12px;
}

.painel-sidebar-empresa strong{
  font-size:14px;
}

.painel-sidebar-empresa span{
  font-size:10px;
}

/* cards de vagas */
.vaga-card h3,
.vaga-titulo{
  font-size:17px;
}

.vaga-card p,
.vaga-card span,
.vaga-meta{
  font-size:11px;
}

/* home */
.hero .inner,
.hero-conteudo{
  max-width:1100px;
}

.hero h1{
  font-size:42px;
}

.hero p{
  font-size:15px;
}

.titulo-secao h2,
.home-bloco-cab h2{
  font-size:26px;
}

.titulo-secao p,
.home-bloco-cab p{
  font-size:13px;
}

/* planos */
.plano-card h3{
  font-size:20px;
}

.plano-card p,
.plano-card li{
  font-size:12px;
  line-height:1.65;
}

/* bot&#245;es */
.btn{
  min-height:43px;
  font-size:12px;
}

/* formul&#225;rios em desktop ganham mais presen&#231;a */
@media(min-width:1000px){
  #pagina-publicar .container-formulario,
  #pagina-publicar .formulario-container,
  #pagina-publicar .publicar-container{
    max-width:1120px;
  }

  #pagina-publicar .form-box,
  #pagina-publicar .caixa-formulario{
    padding-left:34px;
    padding-right:34px;
  }

  .container-dashboard.painel-empresa-layout{
    max-width:1380px;
    grid-template-columns:245px minmax(0,1fr);
  }
}

@media(max-width:650px){
  body{
    font-size:15px;
  }

  .hero h1{
    font-size:31px;
  }

  .contato-candidatura-box{
    padding:19px 15px;
  }

  .contato-opcao label{
    min-height:auto;
  }
}




/* =====================================================
   LAYOUT REALMENTE AMPLO + TIPOGRAFIA MAIOR
===================================================== */

:root{
  --largura-site:1440px;
}

/* usa praticamente toda a largura &#250;til do desktop */
.container,
.container-dashboard,
.container-menor,
.page-header-inner,
.detalhe-layout,
.home-vagas-caixa,
.empresas-contratando .inner{
  width:calc(100% - 48px);
  max-width:var(--largura-site);
}

/* o formul&#225;rio de publica&#231;&#227;o n&#227;o fica mais preso em 900px */
.container-menor{
  padding:44px 0 90px;
}

/* cabe&#231;alho acompanha a nova largura */
.page-header-inner{
  padding-left:0;
  padding-right:0;
}

/* formul&#225;rio com presen&#231;a maior */
#pagina-publicar .form-card{
  padding:38px 40px;
  border-radius:18px;
}

#pagina-publicar .linha{
  gap:22px;
}

#pagina-publicar .grupo{
  margin-bottom:22px;
}

#pagina-publicar .grupo label{
  margin-bottom:9px;
  font-size:15px;
}

#pagina-publicar .campo,
#pagina-publicar select.campo,
#pagina-publicar textarea.campo{
  padding:15px 16px;
  border-radius:10px;
  font-size:16px;
  line-height:1.45;
}

#pagina-publicar textarea.campo{
  min-height:170px;
}

/* cabe&#231;alho da p&#225;gina */
#pagina-publicar .page-header h1{
  font-size:34px;
}

#pagina-publicar .page-header p{
  font-size:15px;
}

#pagina-publicar .voltar{
  font-size:14px;
}

/* bloco de forma de candidatura */
#pagina-publicar .contato-candidatura-box{
  margin:30px 0;
  padding:30px;
  border-radius:18px;
}

#pagina-publicar .contato-candidatura-topo{
  margin-bottom:20px;
}

#pagina-publicar .contato-candidatura-topo h3{
  font-size:21px;
}

#pagina-publicar .contato-candidatura-topo p{
  margin-top:5px;
  font-size:14px;
}

#pagina-publicar .contato-plano-selo{
  padding:8px 13px;
  font-size:11px;
}

#pagina-publicar .contato-opcoes{
  gap:14px;
  margin-bottom:22px;
}

#pagina-publicar .contato-opcao label{
  min-height:112px;
  padding:19px;
  border-radius:13px;
}

#pagina-publicar .contato-opcao label strong{
  font-size:16px;
}

#pagina-publicar .contato-opcao label span{
  margin-top:5px;
  font-size:13px;
  line-height:1.45;
}

#pagina-publicar .contato-opcao-premium{
  margin-top:9px;
  padding:5px 8px;
  font-size:10px !important;
}

#pagina-publicar .contato-ajuda{
  margin-top:8px;
  font-size:12px;
}

#pagina-publicar .contato-upgrade-aviso{
  margin-top:16px;
  padding:14px 16px;
  font-size:12px;
}

/* bloco do plano atual */
#pagina-publicar .publicacao-plano-atual,
#pagina-publicar .plano-publicacao-box{
  padding:25px 28px;
  border-radius:16px;
}

#pagina-publicar .publicacao-plano-atual h3,
#pagina-publicar .plano-publicacao-box h3{
  font-size:20px;
}

#pagina-publicar .publicacao-plano-atual p,
#pagina-publicar .plano-publicacao-box p{
  margin-top:6px;
  font-size:14px;
}

/* bot&#227;o final */
#pagina-publicar .btn{
  min-height:52px;
  padding:14px 20px;
  font-size:14px;
}

/* amplia tamb&#233;m outras &#225;reas do portal */
body{
  font-size:17px;
}

.titulo-secao h2,
.home-bloco-cab h2{
  font-size:29px;
}

.titulo-secao p,
.home-bloco-cab p{
  font-size:14px;
}

.vaga-card{
  padding:25px;
}

.vaga-card h3,
.vaga-titulo{
  font-size:19px;
}

.vaga-card p,
.vaga-card span,
.vaga-meta{
  font-size:13px;
}

.dashboard-topo h1{
  font-size:30px;
}

.dashboard-topo p{
  font-size:14px;
}

.painel-side-nav button{
  font-size:13px;
}

.plano-card p,
.plano-card li{
  font-size:14px;
}

@media(min-width:1500px){
  :root{
    --largura-site:1520px;
  }
}

@media(max-width:900px){
  .container,
  .container-dashboard,
  .container-menor,
  .page-header-inner,
  .detalhe-layout,
  .home-vagas-caixa,
  .empresas-contratando .inner{
    width:calc(100% - 28px);
  }

  #pagina-publicar .form-card{
    padding:26px 22px;
  }

  #pagina-publicar .linha{
    grid-template-columns:1fr;
  }
}

@media(max-width:650px){
  body{
    font-size:16px;
  }

  #pagina-publicar .page-header h1{
    font-size:28px;
  }

  #pagina-publicar .contato-candidatura-topo h3{
    font-size:18px;
  }

  #pagina-publicar .contato-opcao label strong{
    font-size:15px;
  }

  #pagina-publicar .contato-opcao label span{
    font-size:12px;
  }
}




















/* =====================================================
   CARROSSEL DE VAGAS RECOMENDADAS
===================================================== */

.recomendacoes-vaga{
  overflow:hidden;
}

.recomendacoes-carousel-wrap{
  position:relative;
}

.recomendacoes-vaga-grid{
  display:flex;
  gap:14px;
  overflow-x:auto;
  scroll-behavior:smooth;
  scroll-snap-type:x mandatory;
  scrollbar-width:none;
  padding-bottom:4px;
}

.recomendacoes-vaga-grid::-webkit-scrollbar{
  display:none;
}

.recomendacao-card{
  flex:0 0 calc((100% - 28px)/3);
  min-width:0;
  scroll-snap-align:start;
  padding:18px;
  border:1px solid #dbe3ec;
  border-radius:14px;
  background:#fff;
}

.recomendacao-card:hover{
  border-color:#b7cfe3;
  box-shadow:0 8px 24px rgba(16,24,40,.06);
}

.recomendacao-empresa{
  margin-bottom:7px;
  color:#526b7e;
  font-size:10px;
  font-weight:700;
}

.recomendacao-titulo{
  margin:0 0 11px;
  color:var(--texto);
  font-size:16px;
  line-height:1.35;
}

.recomendacao-meta{
  display:flex;
  flex-wrap:wrap;
  gap:7px;
  margin-bottom:12px;
}

.recomendacao-meta span{
  padding:6px 8px;
  border-radius:8px;
  background:#f3f6f9;
  color:#546779;
  font-size:10px;
}

.recomendacao-salario{
  margin-top:2px;
  color:#16894d;
  font-size:12px;
  font-weight:800;
}

.recomendacao-salario strong{
  color:#405264;
  margin-right:4px;
}

.recomendacao-abrir{
  width:100%;
  margin-top:14px;
}

.recomendacao-seta{
  position:absolute;
  top:50%;
  z-index:3;
  width:38px;
  height:38px;
  display:flex;
  align-items:center;
  justify-content:center;
  border:1px solid #d6e1ea;
  border-radius:50%;
  background:#fff;
  box-shadow:0 5px 18px rgba(16,24,40,.11);
  color:var(--azul);
  font-size:18px;
  font-weight:800;
  cursor:pointer;
  transform:translateY(-50%);
}

.recomendacao-seta.anterior{
  left:-10px;
}

.recomendacao-seta.proxima{
  right:-10px;
}

@media(max-width:900px){
  .recomendacao-card{
    flex:0 0 calc((100% - 14px)/2);
  }
}

@media(max-width:600px){
  .recomendacao-card{
    flex:0 0 88%;
  }

  .recomendacao-seta{
    display:none;
  }
}


/* =====================================================
   RODAP&#201; DA VAGA E VAGAS RECOMENDADAS
===================================================== */

.vaga-rodape-info{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:18px;
  margin-top:18px;
  padding:17px 20px;
  border-top:1px solid #e2e8ee;
  border-bottom:1px solid #e2e8ee;
  background:#fbfcfd;
}

.vaga-rodape-info-item{
  display:flex;
  align-items:center;
  gap:6px;
  color:var(--texto2);
  font-size:11px;
}

.vaga-rodape-info-item strong{
  color:var(--texto);
  font-size:11px;
}

.recomendacoes-vaga{
  width:calc(100% - 48px);
  max-width:var(--largura-site);
  margin:34px auto 70px;
  padding:28px;
  border:1px solid #dbe3ec;
  border-radius:20px;
  background:#fff;
  box-shadow:0 8px 30px rgba(16,24,40,.04);
}

.recomendacoes-vaga-cab{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:20px;
  margin-bottom:20px;
}

.recomendacoes-vaga-cab h2{
  margin:0 0 5px;
  font-size:23px;
}

.recomendacoes-vaga-cab p{
  margin:0;
  color:var(--cinza);
  font-size:12px;
  line-height:1.6;
}

.recomendacoes-vaga-grid{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:15px;
}

.recomendacoes-vaga-grid .vaga-card{
  margin:0;
  height:100%;
}

.recomendacoes-vaga-vazio{
  padding:24px;
  border:1px dashed #d9e1e8;
  border-radius:13px;
  color:var(--cinza);
  font-size:12px;
  text-align:center;
  background:#fafcfd;
}

@media(max-width:800px){
  .recomendacoes-vaga{
    width:calc(100% - 30px);
    padding:20px 15px;
  }

  .recomendacoes-vaga-grid{
    grid-template-columns:1fr;
  }

  .recomendacoes-vaga-cab{
    align-items:flex-start;
    flex-direction:column;
  }
}

@media(max-width:520px){
  .vaga-rodape-info{
    align-items:flex-start;
    flex-direction:column;
    gap:8px;
    padding:15px;
  }
}


/* =====================================================
   POPUP PROFISSIONAL / MODAL DO SITE
===================================================== */

.modal-site-overlay{
  position:fixed;
  inset:0;
  z-index:99999;
  display:none;
  align-items:center;
  justify-content:center;
  padding:20px;
  background:rgba(15,23,42,.58);
  backdrop-filter:blur(3px);
}

.modal-site-overlay.ativo{
  display:flex;
}

.modal-site{
  width:min(100%,460px);
  overflow:hidden;
  border:1px solid #dbe4ec;
  border-radius:22px;
  background:#fff;
  box-shadow:0 24px 70px rgba(15,23,42,.28);
  animation:modalSiteEntrar .22s ease-out;
}

@keyframes modalSiteEntrar{
  from{
    opacity:0;
    transform:translateY(14px) scale(.98);
  }
  to{
    opacity:1;
    transform:translateY(0) scale(1);
  }
}

.modal-site-conteudo{
  padding:28px 28px 22px;
}

.modal-site-icone{
  width:52px;
  height:52px;
  margin-bottom:17px;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:50%;
  background:#eaf7ef;
  color:#176b3a;
  font-size:24px;
  font-weight:900;
}

.modal-site-titulo{
  margin:0 0 8px;
  font-size:21px;
  line-height:1.3;
  color:var(--texto);
}

.modal-site-texto{
  margin:0;
  color:var(--texto2);
  font-size:13px;
  line-height:1.7;
}

.modal-site-acoes{
  display:flex;
  justify-content:flex-end;
  gap:10px;
  padding:17px 22px;
  border-top:1px solid #edf1f4;
  background:#fafcfd;
}

.modal-site-btn{
  min-width:92px;
  padding:11px 18px;
  border:0;
  border-radius:10px;
  background:var(--azul);
  color:#fff;
  font-family:inherit;
  font-size:12px;
  font-weight:800;
  cursor:pointer;
  transition:.18s ease;
}

.modal-site-btn:hover{
  filter:brightness(.95);
  transform:translateY(-1px);
}

@media(max-width:520px){
  .modal-site{
    border-radius:18px;
  }

  .modal-site-conteudo{
    padding:24px 20px 20px;
  }

  .modal-site-acoes{
    padding:14px 18px;
  }

  .modal-site-btn{
    width:100%;
  }
}


/* =====================================================
   DESTAQUE DA VERIFICA&#199;&#195;O
===================================================== */

.painel-side-nav button.verificacao-destaque{
  position:relative;
  border:1px solid #b9d8c5;
  background:#edf9f1;
  color:#176b3a;
}

.painel-side-nav button.verificacao-destaque:after{
  content:"Recomendado";
  position:absolute;
  right:8px;
  top:7px;
  padding:3px 6px;
  border-radius:20px;
  background:#dff3e6;
  color:#176b3a;
  font-size:8px;
  font-weight:800;
  text-transform:uppercase;
}

.painel-side-nav button.verificacao-analise{
  border:1px solid #ecd79f;
  background:#fff8e7;
  color:#8a6100;
}

.painel-side-nav button.verificacao-analise:after{
  content:"Em an&#225;lise";
  position:absolute;
  right:8px;
  top:7px;
  padding:3px 6px;
  border-radius:20px;
  background:#fff0c5;
  color:#8a6100;
  font-size:8px;
  font-weight:800;
  text-transform:uppercase;
}

.painel-side-nav button.verificacao-ok{
  border:1px solid #abd4b9;
  background:#eaf7ef;
  color:#176b3a;
}

.verificacao-hero{
  margin:32px auto 24px;
  padding:32px;
  border:1px solid #cfe0ec;
  border-radius:20px;
  background:linear-gradient(135deg,#f8fcff,#eef7fd);
}

.verificacao-hero-grid{
  display:grid;
  grid-template-columns:1.15fr .85fr;
  gap:24px;
  align-items:center;
}

.verificacao-hero-selo{
  display:inline-flex;
  margin-bottom:12px;
  padding:7px 10px;
  border-radius:30px;
  background:#e4f2fb;
  color:var(--azul);
  font-size:10px;
  font-weight:800;
  text-transform:uppercase;
}

.verificacao-hero h2{
  margin-bottom:10px;
  font-size:28px;
  line-height:1.25;
}

.verificacao-hero p{
  color:var(--cinza);
  font-size:13px;
  line-height:1.75;
}

.verificacao-vantagens{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:10px;
  margin-top:18px;
}

.verificacao-vantagem{
  display:flex;
  align-items:flex-start;
  gap:9px;
  padding:11px 12px;
  border:1px solid #dbe6ee;
  border-radius:11px;
  background:#fff;
  color:var(--texto2);
  font-size:11px;
  line-height:1.5;
}

.verificacao-vantagem i{
  width:21px;
  height:21px;
  flex:none;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:50%;
  background:#e2f5e9;
  color:#176b3a;
  font-style:normal;
  font-size:10px;
  font-weight:900;
}

.verificacao-hero-lateral{
  padding:23px;
  border:1px solid #d5e4ee;
  border-radius:15px;
  background:#fff;
}

.verificacao-hero-lateral h3{
  margin-bottom:7px;
  font-size:17px;
}

.verificacao-hero-lateral p{
  margin-bottom:16px;
  font-size:11px;
}

.verificacao-passos{
  max-width:1180px;
  margin:0 auto 24px;
  padding:0 24px;
}

.verificacao-passos-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:14px;
}

.verificacao-passo{
  padding:20px;
  border:1px solid #dfe6ec;
  border-radius:14px;
  background:#fff;
}

.verificacao-passo-num{
  width:32px;
  height:32px;
  margin-bottom:12px;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:50%;
  background:var(--azul);
  color:#fff;
  font-size:11px;
  font-weight:800;
}

.verificacao-passo h3{
  margin-bottom:6px;
  font-size:15px;
}

.verificacao-passo p{
  color:var(--cinza);
  font-size:11px;
  line-height:1.6;
}

.verificacao-significado{
  max-width:1180px;
  margin:0 auto 24px;
  padding:0 24px;
}

.verificacao-significado-box{
  padding:18px 20px;
  border-left:4px solid var(--azul);
  border-radius:10px;
  background:#f7fbfe;
}

.verificacao-significado-box h3{
  margin-bottom:6px;
  font-size:15px;
}

.verificacao-significado-box p{
  color:var(--cinza);
  font-size:11px;
  line-height:1.7;
}

@media(max-width:800px){
  .verificacao-hero-grid{
    grid-template-columns:1fr;
  }

  .verificacao-vantagens,
  .verificacao-passos-grid{
    grid-template-columns:1fr;
  }
}


/* =====================================================
   EMPRESAS VERIFICADAS
===================================================== */

.verificacao-card{
  margin:22px 0 26px;
  padding:24px;
  border:1px solid #d6e4ef;
  border-radius:17px;
  background:linear-gradient(135deg,#f8fcff,#eef7fd);
}

.verificacao-card-topo{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:18px;
}

.verificacao-card h2{
  margin:0 0 6px;
  font-size:20px;
}

.verificacao-card p{
  margin:0;
  color:var(--cinza);
  font-size:12px;
  line-height:1.65;
}

.verificacao-beneficios{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  margin-top:16px;
}

.verificacao-beneficios span{
  padding:6px 9px;
  border:1px solid #d4e3ef;
  border-radius:20px;
  background:#fff;
  color:#31536d;
  font-size:10px;
  font-weight:700;
}

.selo-verificacao{
  display:inline-flex;
  align-items:center;
  gap:6px;
  padding:6px 10px;
  border-radius:30px;
  background:#e0f4e7;
  color:#176b3a;
  font-size:10px;
  font-weight:800;
  white-space:nowrap;
}

.selo-verificacao.pendente{
  background:#fff3d8;
  color:#8a6100;
}

.selo-verificacao.rejeitada{
  background:#fee8e7;
  color:#b42318;
}

.empresa-verificada-link{
  padding:0;
  border:0;
  background:none;
  color:var(--azul);
  font:inherit;
  font-weight:800;
  text-decoration:none;
  cursor:pointer;
}

.empresa-verificada-link:hover{
  text-decoration:underline;
}

.empresa-verificada-mini{
  display:inline-flex;
  align-items:center;
  gap:5px;
  margin-left:6px;
  padding:3px 7px;
  border-radius:20px;
  background:#e0f4e7;
  color:#176b3a;
  font-size:9px;
  font-weight:800;
  vertical-align:middle;
}

.verificacao-form{
  max-width:1180px;
  margin:32px auto 70px;
  padding:0 24px;
}

.verificacao-form-box{
  padding:30px;
  border:1px solid #dce5ed;
  border-radius:18px;
  background:#fff;
}

.verificacao-grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:18px;
}

.verificacao-form .grupo{
  margin-bottom:18px;
}

.verificacao-form label{
  display:block;
  margin-bottom:8px;
  font-size:13px;
  font-weight:800;
}

.verificacao-form .campo{
  font-size:14px;
}

.verificacao-info{
  margin-bottom:22px;
  padding:14px 16px;
  border:1px solid #d7e5ef;
  border-radius:11px;
  background:#f7fbfe;
  color:#496579;
  font-size:11px;
  line-height:1.65;
}

.verificacao-info strong{
  color:var(--azul);
}

.verificacao-status-box{
  margin-bottom:20px;
  padding:17px;
  border:1px solid #dbe5ed;
  border-radius:12px;
  background:#fafcfd;
}

.verificacao-status-box h3{
  margin-bottom:6px;
  font-size:15px;
}

.verificacao-status-box p{
  color:var(--cinza);
  font-size:11px;
  line-height:1.6;
}

.empresa-publica{
  max-width:1180px;
  margin:35px auto 70px;
  padding:0 24px;
}

.empresa-publica-cab{
  padding:30px;
  border:1px solid #d9e4ec;
  border-radius:19px;
  background:#fff;
}

.empresa-publica-topo{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:20px;
}

.empresa-publica-nome h1{
  margin:0 0 7px;
  font-size:30px;
}

.empresa-publica-sub{
  color:var(--cinza);
  font-size:13px;
}

.empresa-publica-info{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:12px;
  margin-top:22px;
}

.empresa-publica-info div{
  padding:15px;
  border:1px solid #e1e7ed;
  border-radius:11px;
  background:#fafcfd;
}

.empresa-publica-info span{
  display:block;
  margin-bottom:5px;
  color:var(--cinza);
  font-size:10px;
  font-weight:700;
  text-transform:uppercase;
}

.empresa-publica-info strong{
  font-size:13px;
  color:var(--texto);
}

.empresa-publica-sobre,
.empresa-publica-vagas{
  margin-top:18px;
  padding:26px;
  border:1px solid #dfe6ec;
  border-radius:16px;
  background:#fff;
}

.empresa-publica-sobre h2,
.empresa-publica-vagas h2{
  margin-bottom:10px;
  font-size:21px;
}

.empresa-publica-sobre p{
  color:var(--texto2);
  font-size:13px;
  line-height:1.75;
  white-space:pre-line;
}

.admin-verificacoes{
  margin:26px 0;
  padding:24px;
  border:1px solid #dbe4eb;
  border-radius:16px;
  background:#fff;
}

.admin-verificacoes h2{
  margin-bottom:5px;
  font-size:20px;
}

.admin-verificacoes>p{
  margin-bottom:18px;
  color:var(--cinza);
  font-size:12px;
}

.admin-verificacao-card{
  padding:18px;
  border:1px solid #e0e6ec;
  border-radius:12px;
  background:#fbfcfd;
}

.admin-verificacao-card + .admin-verificacao-card{
  margin-top:12px;
}

.admin-verificacao-topo{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:15px;
}

.admin-verificacao-card h3{
  margin-bottom:5px;
  font-size:16px;
}

.admin-verificacao-card p{
  color:var(--cinza);
  font-size:11px;
  line-height:1.65;
}

.admin-verificacao-dados{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:9px;
  margin-top:14px;
}

.admin-verificacao-dados div{
  padding:10px;
  border:1px solid #e4e9ee;
  border-radius:9px;
  background:#fff;
}

.admin-verificacao-dados span{
  display:block;
  margin-bottom:3px;
  color:var(--cinza);
  font-size:9px;
  text-transform:uppercase;
}

.admin-verificacao-dados strong{
  font-size:11px;
  word-break:break-word;
}

.admin-verificacao-acoes{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  margin-top:14px;
}

@media(max-width:850px){
  .verificacao-grid,
  .empresa-publica-info,
  .admin-verificacao-dados{
    grid-template-columns:1fr 1fr;
  }
}

@media(max-width:600px){
  .verificacao-card-topo,
  .empresa-publica-topo,
  .admin-verificacao-topo{
    flex-direction:column;
  }

  .verificacao-form{
    padding:0 15px;
  }

  .verificacao-form-box{
    padding:21px 16px;
  }

  .verificacao-grid,
  .empresa-publica-info,
  .admin-verificacao-dados{
    grid-template-columns:1fr;
  }

  .empresa-publica{
    padding:0 15px;
  }

  .empresa-publica-nome h1{
    font-size:25px;
  }
}


/* =====================================================
   ESCOLARIDADE DAS VAGAS
===================================================== */

.vaga-escolaridade-tag{
  display:inline-flex;
  align-items:center;
  gap:6px;
  padding:6px 9px;
  border:1px solid #d8e4ee;
  border-radius:20px;
  background:#f6fafe;
  color:#36546b;
  font-size:10px;
  font-weight:700;
}

.vaga-escolaridade-tag:before{
  content:"";
  width:7px;
  height:7px;
  border-radius:50%;
  background:var(--azul);
}

.detalhe-escolaridade{
  display:flex;
  align-items:center;
  gap:10px;
  margin-top:9px;
  padding:12px 14px;
  border:1px solid #dce6ee;
  border-radius:10px;
  background:#f8fbfe;
}

.detalhe-escolaridade strong{
  font-size:12px;
  color:var(--texto);
}

.detalhe-escolaridade span{
  font-size:12px;
  color:var(--texto2);
}

@media(max-width:650px){
  .vaga-escolaridade-tag{
    font-size:9px;
  }

  .detalhe-escolaridade{
    align-items:flex-start;
    flex-direction:column;
  }
}


/* =====================================================
   LISTA DE VAGAS APROVADAS NO PAINEL DA EMPRESA
===================================================== */

.vagas-aprovadas-painel{
  margin:22px 0 26px;
  padding:24px;
  border:1px solid #d9e3eb;
  border-radius:17px;
  background:#fff;
  box-shadow:0 6px 22px rgba(16,24,40,.035);
}

.vagas-aprovadas-painel-cab{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:15px;
  margin-bottom:18px;
}

.vagas-aprovadas-painel-cab h2{
  margin:0 0 4px;
  font-size:21px;
}

.vagas-aprovadas-painel-cab p{
  margin:0;
  color:var(--cinza);
  font-size:12px;
}

.vagas-aprovadas-lista{
  display:grid;
  gap:13px;
}

.vaga-aprovada-item{
  padding:18px;
  border:1px solid #dce4eb;
  border-radius:13px;
  background:#fbfdff;
}

.vaga-aprovada-item-topo{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:15px;
}

.vaga-aprovada-item h3{
  margin:0 0 5px;
  font-size:17px;
}

.vaga-aprovada-item-meta{
  color:var(--cinza);
  font-size:12px;
  line-height:1.6;
}

.vaga-aprovada-selo{
  flex:none;
  padding:6px 9px;
  border-radius:30px;
  background:#e3f5e9;
  color:#166534;
  font-size:9px;
  font-weight:800;
  text-transform:uppercase;
}

.vaga-aprovada-acoes{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  margin-top:15px;
}

.vaga-aprovada-acoes .btn{
  min-height:39px;
  padding:9px 13px;
  font-size:11px;
}

.vaga-aprovada-vazio{
  padding:26px 18px;
  border:1px dashed #cbd8e3;
  border-radius:12px;
  background:#fafcfd;
  text-align:center;
  color:var(--cinza);
  font-size:12px;
}

@media(max-width:650px){
  .vagas-aprovadas-painel{
    padding:18px 14px;
  }

  .vagas-aprovadas-painel-cab,
  .vaga-aprovada-item-topo{
    flex-direction:column;
  }

  .vaga-aprovada-acoes .btn{
    flex:1 1 46%;
  }
}


/* =====================================================
   PAINEL DA EMPRESA - ACESSO TOTAL A VAGA
===================================================== */

#painelListaVagasEmpresa{
  width:100%;
  min-height:120px;
  margin-top:4px;
}

.empresa-vaga-card{
  overflow:hidden;
  border:1px solid #d8e2ea;
  border-radius:16px;
  background:#fff;
  box-shadow:0 5px 18px rgba(16,24,40,.035);
}

.empresa-vaga-card + .empresa-vaga-card{
  margin-top:15px;
}

.empresa-vaga-resumo{
  padding:22px 23px;
}

.empresa-vaga-topo{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:20px;
}

.empresa-vaga-topo h3{
  margin:0 0 6px;
  color:var(--texto);
  font-size:20px;
  line-height:1.35;
}

.empresa-vaga-empresa{
  margin-bottom:5px;
  color:var(--texto2);
  font-size:13px;
  font-weight:700;
}

.empresa-vaga-meta{
  color:var(--cinza);
  font-size:13px;
  line-height:1.6;
}

.empresa-vaga-status{
  flex:none;
  padding:7px 10px;
  border-radius:30px;
  font-size:10px;
  font-weight:800;
  text-transform:uppercase;
  letter-spacing:.3px;
}

.empresa-vaga-status.aprovada{
  background:#e2f5e9;
  color:#166534;
}

.empresa-vaga-status.pendente{
  background:#fff4d8;
  color:#8a6100;
}

.empresa-vaga-status.rejeitada{
  background:#fee8e7;
  color:#b42318;
}

.empresa-vaga-status.encerrada{
  background:#eceff2;
  color:#4b5563;
}

.empresa-vaga-status.alteracao{
  background:#fff4d8;
  color:#8a6100;
}

.empresa-vaga-indicadores{
  display:grid;
  grid-template-columns:repeat(5,1fr);
  gap:10px;
  margin-top:18px;
}

.empresa-vaga-indicador{
  padding:12px 13px;
  border:1px solid #e5eaef;
  border-radius:10px;
  background:#fafcfd;
}

.empresa-vaga-indicador span{
  display:block;
  margin-bottom:4px;
  color:var(--cinza);
  font-size:10px;
}

.empresa-vaga-indicador strong{
  color:var(--texto);
  font-size:13px;
}

.empresa-vaga-acoes{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  margin-top:18px;
}

.empresa-vaga-acoes .btn{
  min-height:40px;
  padding:9px 14px;
  font-size:11px;
}

.btn-gerenciar-vaga{
  border:1px solid #bfd5e6;
  background:#edf6fc;
  color:var(--azul);
}

.empresa-vaga-detalhes{
  display:none;
  padding:0 23px 23px;
  border-top:1px solid #edf0f3;
  background:#fbfcfd;
}

.empresa-vaga-detalhes.aberto{
  display:block;
}

.empresa-vaga-detalhes-inner{
  padding-top:20px;
}

.empresa-vaga-detalhes-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:12px;
  margin-bottom:18px;
}

.empresa-vaga-detalhe-item{
  padding:13px;
  border:1px solid #e2e8ee;
  border-radius:10px;
  background:#fff;
}

.empresa-vaga-detalhe-item span{
  display:block;
  margin-bottom:5px;
  color:var(--cinza);
  font-size:10px;
  font-weight:600;
}

.empresa-vaga-detalhe-item strong{
  color:var(--texto2);
  font-size:12px;
  line-height:1.55;
  word-break:break-word;
}

.empresa-vaga-texto{
  margin-top:12px;
  padding:16px;
  border:1px solid #e2e8ee;
  border-radius:11px;
  background:#fff;
}

.empresa-vaga-texto h4{
  margin-bottom:8px;
  font-size:13px;
}

.empresa-vaga-texto p{
  margin:0;
  color:var(--texto2);
  font-size:12px;
  line-height:1.7;
  white-space:pre-line;
}

.empresa-vaga-regra-edicao{
  margin-top:15px;
  padding:12px 14px;
  border-radius:9px;
  background:#f3f8fc;
  color:#486579;
  font-size:11px;
  line-height:1.55;
}

.empresa-vaga-regra-edicao strong{
  color:var(--azul);
}

.painel-vagas-vazio{
  padding:50px 25px;
  border:1px dashed #cbd7e1;
  border-radius:15px;
  background:#fff;
  text-align:center;
}

.painel-vagas-vazio h3{
  margin-bottom:7px;
  font-size:18px;
}

.painel-vagas-vazio p{
  margin:0 auto 17px;
  max-width:520px;
  color:var(--cinza);
  font-size:13px;
  line-height:1.65;
}

@media(max-width:900px){
  .empresa-vaga-indicadores{
    grid-template-columns:repeat(2,1fr);
  }

  .empresa-vaga-detalhes-grid{
    grid-template-columns:1fr 1fr;
  }
}

@media(max-width:600px){
  .empresa-vaga-resumo{
    padding:18px 15px;
  }

  .empresa-vaga-topo{
    flex-direction:column;
  }

  .empresa-vaga-topo h3{
    font-size:18px;
  }

  .empresa-vaga-status{
    align-self:flex-start;
  }

  .empresa-vaga-indicadores,
  .empresa-vaga-detalhes-grid{
    grid-template-columns:1fr;
  }

  .empresa-vaga-detalhes{
    padding:0 15px 18px;
  }

  .empresa-vaga-acoes .btn{
    flex:1 1 46%;
  }
}


/* =====================================================
   EDICAO, STATUS E ENCERRAMENTO DE VAGAS
===================================================== */

.status-admin.status-encerrada{
  background:#eef0f2;
  color:#4b5563;
}

.status-admin.status-alteracao{
  background:#fff5d9;
  color:#8a6100;
}

.btn-editar-vaga{
  background:#eef6fc;
  color:var(--azul);
  border:1px solid #c9deed;
}

.btn-encerrar-vaga{
  background:#fff;
  color:#b42318;
  border:1px solid #efc8c3;
}

.btn-edicao-usada{
  background:#f3f4f6;
  color:#8a929b;
  border:1px solid #e1e4e8;
  cursor:not-allowed;
}

.edicao-info-vaga{
  width:100%;
  margin-top:8px;
  padding:9px 11px;
  border-radius:8px;
  background:#f7fafc;
  color:var(--cinza);
  font-size:11px;
  line-height:1.5;
}

.edicao-info-vaga strong{
  color:var(--texto2);
}

#pagina-publicar .aviso-edicao-vaga{
  display:none;
  margin-bottom:22px;
  padding:14px 16px;
  border:1px solid #cfe0ed;
  border-radius:11px;
  background:#f4f9fd;
  color:#36546b;
  font-size:13px;
  line-height:1.55;
}

#pagina-publicar .aviso-edicao-vaga.ativo{
  display:block;
}

#pagina-publicar .aviso-edicao-vaga strong{
  color:var(--azul);
}


/* =====================================================
   CONTATO PARA CANDIDATURA
===================================================== */

.contato-candidatura-box{
  margin:24px 0;
  padding:20px;
  border:1px solid #d8e5ef;
  border-radius:15px;
  background:#f8fbfe;
}

.contato-candidatura-topo{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:15px;
  margin-bottom:15px;
}

.contato-candidatura-topo h3{
  margin-bottom:4px;
  font-size:15px;
}

.contato-candidatura-topo p{
  color:var(--cinza);
  font-size:10px;
  line-height:1.55;
}

.contato-plano-selo{
  flex:none;
  padding:6px 9px;
  border-radius:30px;
  background:#e8f2fa;
  color:var(--azul);
  font-size:9px;
  font-weight:800;
  text-transform:uppercase;
}

.contato-opcoes{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:9px;
  margin-bottom:15px;
}

.contato-opcao{
  position:relative;
}

.contato-opcao input{
  position:absolute;
  opacity:0;
  pointer-events:none;
}

.contato-opcao label{
  min-height:78px;
  padding:13px;
  display:flex;
  flex-direction:column;
  justify-content:center;
  border:1px solid #dbe4ec;
  border-radius:11px;
  background:#fff;
  cursor:pointer;
  transition:.18s;
}

.contato-opcao label strong{
  margin-bottom:3px;
  font-size:11px;
}

.contato-opcao label span{
  color:var(--cinza);
  font-size:9px;
  line-height:1.4;
}

.contato-opcao input:checked + label{
  border-color:var(--azul);
  box-shadow:0 0 0 2px rgba(23,105,170,.09);
  background:#f3f9fd;
}

.contato-opcao.bloqueada label{
  cursor:not-allowed;
  opacity:.58;
  background:#f4f5f6;
}

.contato-opcao-premium{
  display:inline-flex;
  width:max-content;
  margin-top:6px;
  padding:3px 6px;
  border-radius:20px;
  background:#fff0c9;
  color:#7a5900 !important;
  font-size:8px !important;
  font-weight:800;
  text-transform:uppercase;
}

.contato-ajuda{
  margin-top:6px;
  color:var(--cinza);
  font-size:9px;
  line-height:1.5;
}

.contato-upgrade-aviso{
  display:none;
  margin-top:12px;
  padding:11px 12px;
  border:1px solid #f1d79e;
  border-radius:9px;
  background:#fff9e9;
  color:#765500;
  font-size:9px;
  line-height:1.55;
}

.contato-upgrade-aviso.ativo{
  display:block;
}

.contato-upgrade-aviso button{
  margin-left:5px;
  padding:0;
  border:0;
  background:none;
  color:var(--azul);
  font:inherit;
  font-weight:800;
  text-decoration:underline;
}

@media(max-width:650px){
  .contato-opcoes{
    grid-template-columns:1fr;
  }

  .contato-candidatura-topo{
    flex-direction:column;
  }
}


/* =====================================================
   CONVITE DE UPGRADE - PLANO ESSENCIAL
===================================================== */

.upgrade-plano-box{
  margin:22px 0 26px;
  padding:22px;
  border:1px solid #cfe2f0;
  border-radius:17px;
  background:linear-gradient(135deg,#f8fcff 0%,#eef7fd 100%);
  box-shadow:0 8px 24px rgba(23,105,170,.05);
}

.upgrade-plano-inner{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:24px;
}

.upgrade-plano-info{
  display:flex;
  align-items:flex-start;
  gap:15px;
}

.upgrade-plano-icone{
  width:48px;
  height:48px;
  flex:0 0 48px;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:14px;
  background:#dff0fb;
  color:var(--azul);
}

.upgrade-plano-icone svg{
  width:25px;
  height:25px;
  display:block;
  fill:none;
  stroke:currentColor;
  stroke-width:1.9;
  stroke-linecap:round;
  stroke-linejoin:round;
}

.upgrade-plano-texto h3{
  margin:0 0 6px;
  color:var(--texto);
  font-size:17px;
}

.upgrade-plano-texto p{
  max-width:720px;
  margin:0;
  color:var(--cinza);
  font-size:12px;
  line-height:1.65;
}

.upgrade-plano-beneficios{
  display:flex;
  flex-wrap:wrap;
  gap:7px;
  margin-top:12px;
}

.upgrade-plano-beneficios span{
  padding:6px 9px;
  border:1px solid #d8e6f0;
  border-radius:30px;
  background:#fff;
  color:#31546e;
  font-size:10px;
  font-weight:700;
}

.upgrade-plano-acao{
  flex:0 0 auto;
}

.upgrade-plano-acao .btn{
  white-space:nowrap;
}

@media(max-width:760px){

  .upgrade-plano-inner{
    align-items:stretch;
    flex-direction:column;
  }

  .upgrade-plano-acao,
  .upgrade-plano-acao .btn{
    width:100%;
  }

}


/* =====================================================
   PLANOS PARA EMPRESAS
===================================================== */

.planos-hero{
  padding:58px 24px 42px;
  background:linear-gradient(135deg,#0d4f82,#1769aa);
  color:#fff;
  text-align:center;
}

.planos-hero-inner{
  max-width:820px;
  margin:auto;
}

.planos-hero-selo{
  display:inline-block;
  margin-bottom:14px;
  padding:7px 12px;
  border:1px solid rgba(255,255,255,.22);
  border-radius:30px;
  background:rgba(255,255,255,.08);
  font-size:11px;
  font-weight:700;
}

.planos-hero h1{
  margin-bottom:10px;
  font-size:36px;
  line-height:1.15;
}

.planos-hero p{
  max-width:650px;
  margin:auto;
  color:rgba(255,255,255,.86);
  font-size:15px;
  line-height:1.7;
}

.planos-pagina{
  max-width:1180px;
  margin:auto;
  padding:44px 24px 75px;
}

.planos-grid-novo{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:18px;
  align-items:stretch;
}

.plano-card-novo{
  position:relative;
  padding:27px 24px;
  background:#fff;
  border:1px solid #dfe5ec;
  border-radius:18px;
  box-shadow:0 8px 26px rgba(16,24,40,.05);
}

.plano-card-novo.profissional{
  border:2px solid var(--azul);
  transform:translateY(-8px);
  box-shadow:0 18px 40px rgba(23,105,170,.12);
}

.plano-card-novo.premium{
  border:1px solid #c9d2dc;
  background:linear-gradient(180deg,#fbfcfe,#fff);
}

.plano-badge{
  position:absolute;
  top:-13px;
  left:50%;
  transform:translateX(-50%);
  padding:7px 12px;
  border-radius:30px;
  background:var(--azul);
  color:#fff;
  font-size:10px;
  font-weight:800;
  white-space:nowrap;
}

.plano-icone{
  width:46px;
  height:46px;
  margin-bottom:16px;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:13px;
  background:var(--azulClaro);
  color:var(--azul);
  box-shadow:inset 0 0 0 1px rgba(23,105,170,.04);
}

.plano-icone svg{
  width:23px;
  height:23px;
  display:block;
  fill:none;
  stroke:currentColor;
  stroke-width:1.9;
  stroke-linecap:round;
  stroke-linejoin:round;
}

.plano-card-novo.profissional .plano-icone{
  background:#e8f4fc;
  color:#0d67a8;
}

.plano-card-novo.premium .plano-icone{
  background:#eaf0f6;
  color:#173f61;
}

.plano-card-novo h2{
  margin-bottom:5px;
  font-size:20px;
}

.plano-sub{
  min-height:39px;
  color:var(--cinza);
  font-size:12px;
  line-height:1.55;
}

.plano-valor{
  margin:21px 0 5px;
  color:var(--texto);
  font-size:34px;
  font-weight:800;
  letter-spacing:-1px;
}

.plano-valor small{
  color:var(--cinza);
  font-size:12px;
  font-weight:600;
  letter-spacing:0;
}

.plano-limite{
  margin-bottom:20px;
  color:var(--azul);
  font-size:12px;
  font-weight:800;
}

.plano-beneficios{
  margin:0 0 24px;
  padding:19px 0 0;
  border-top:1px solid var(--borda2);
  list-style:none;
}

.plano-beneficios li{
  position:relative;
  margin-bottom:12px;
  padding-left:23px;
  color:var(--texto2);
  font-size:12px;
  line-height:1.5;
}

.plano-beneficios li:before{
  content:"";
  position:absolute;
  left:0;
  top:0;
  color:var(--verde);
  font-weight:900;
}

.plano-beneficios li.nao:before{
  content:"";
  color:var(--cinza2);
}

.plano-beneficios li.nao{
  color:var(--cinza2);
}

.plano-beneficios li:before{
  content:"";
  width:7px;
  height:4px;
  border-left:2px solid var(--verde);
  border-bottom:2px solid var(--verde);
  transform:rotate(-45deg);
  top:4px;
}

.plano-beneficios li.nao:before{
  content:"";
  width:8px;
  height:1px;
  border:0;
  background:var(--cinza2);
  transform:none;
  top:8px;
}


.plano-card-novo .btn{
  width:100%;
}

.planos-observacao{
  margin-top:26px;
  padding:18px 20px;
  border:1px solid #dce6ef;
  border-radius:14px;
  background:#f8fbfe;
  color:var(--cinza);
  font-size:12px;
  line-height:1.7;
  text-align:center;
}

.plano-atual-box{
  margin-bottom:24px;
  padding:18px 20px;
  border:1px solid #dce6ef;
  border-radius:14px;
  background:#f8fbfe;
}

.plano-atual-box strong{
  color:var(--texto);
}

.plano-atual-box p{
  margin-top:5px;
  color:var(--cinza);
  font-size:12px;
}

.publicacao-plano-atual{
  margin-bottom:22px;
  padding:18px;
  border:1px solid #dbe5ee;
  border-radius:12px;
  background:#f8fbfe;
}

.publicacao-plano-atual-top{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:15px;
}

.publicacao-plano-atual h3{
  margin-bottom:5px;
  font-size:14px;
}

.publicacao-plano-atual p{
  color:var(--cinza);
  font-size:11px;
  line-height:1.6;
}

.publicacao-consumo{
  margin-top:12px;
  height:7px;
  overflow:hidden;
  border-radius:20px;
  background:#e8edf2;
}

.publicacao-consumo-barra{
  height:100%;
  width:0;
  border-radius:20px;
  background:var(--azul);
}

@media(max-width:900px){
  .planos-grid-novo{
    grid-template-columns:1fr;
  }

  .plano-card-novo.profissional{
    transform:none;
  }
}

@media(max-width:520px){
  .planos-hero{
    padding:45px 16px 35px;
  }

  .planos-hero h1{
    font-size:29px;
  }

  .planos-pagina{
    padding:32px 15px 60px;
  }
}


/* =====================================================
   CTA / FOOTER
===================================================== */

.cta-empresa{
  padding:65px 24px;
  background:#eef6fc;
  text-align:center;
}

.cta-empresa h2{
  margin-bottom:10px;
  font-size:28px;
}

.cta-empresa p{
  max-width:650px;
  margin:0 auto 20px;
  color:var(--cinza);
}

.rodape{
  padding:55px 24px 22px;
  background:#101828;
  color:#fff;
}

.rodape-grid{
  max-width:1240px;
  margin:auto;
  display:grid;
  grid-template-columns:2fr repeat(4,1fr);
  gap:40px;
}

.rodape h3{
  margin-bottom:14px;
  font-size:12px;
}

.rodape p,
.rodape button{
  color:#98a2b3;
  font-size:11px;
}

.rodape button{
  display:block;
  margin-bottom:10px;
  border:0;
  background:none;
}

.rodape-admin{
  max-width:1240px;
  margin:28px auto 0;
  padding-top:18px;
  border-top:1px solid #273346;
  text-align:center;
}

.rodape-admin button{
  display:inline-block;
  margin:0;
  color:#667085;
  font-size:10px;
}

.copy{
  margin-top:15px;
  color:#667085;
  font-size:10px;
  text-align:center;
}

#blogger-area{
  display:none;
}


/* =====================================================
   RESPONSIVO
===================================================== */

@media(max-width:1050px){

  .menu-principal{
    display:none;
  }

  .metricas{
    grid-template-columns:repeat(2,1fr);
  }

  .rodape-grid{
    grid-template-columns:2fr repeat(2,1fr);
  }

}

@media(max-width:900px){

  .destaques{
    grid-template-columns:1fr;
  }

  .vagas-area,
  .detalhe-layout{
    grid-template-columns:1fr;
  }

  .filtros-lateral{
    display:none;
    position:static;
  }

  .filtros-lateral.aberto{
    display:block;
  }

  .btn-mobile-filtros{
    display:block;
    width:100%;
    margin-bottom:15px;
    padding:12px;
    border:1px solid var(--borda);
    border-radius:10px;
    background:#fff;
  }

  .aplicar-lateral{
    position:static;
  }

}

@media(max-width:720px){

  .busca-principal{
    grid-template-columns:1fr;
  }

  .busca-campo + .busca-campo{
    border-left:0;
    border-top:1px solid var(--borda);
  }

  .linha,
  .planos,
  .admin-barra,
  .candidato-acoes,
  .painel-candidato-grid{
    grid-template-columns:1fr;
  }

  .dashboard-topo,
