/* =====================================================
   AJUSTE FINAL - 4 VAGAS RECOMENDADAS EM UMA &#218;NICA LINHA
===================================================== */

.recomendacoes-carousel-wrap{
  position:relative;
  width:100%;
  overflow:visible;
}

#listaRecomendacoesVaga.recomendacoes-vaga-grid{
  display:flex !important;
  flex-direction:row !important;
  flex-wrap:nowrap !important;
  grid-template-columns:none !important;
  gap:14px !important;
  width:100%;
  overflow-x:auto !important;
  overflow-y:hidden !important;
  scroll-behavior:smooth;
  scroll-snap-type:x mandatory;
  scrollbar-width:none;
  padding:2px 1px 6px;
}

#listaRecomendacoesVaga.recomendacoes-vaga-grid::-webkit-scrollbar{
  display:none;
}

#listaRecomendacoesVaga .recomendacao-card{
  flex:0 0 calc((100% - 42px) / 4) !important;
  width:calc((100% - 42px) / 4) !important;
  min-width:calc((100% - 42px) / 4) !important;
  max-width:calc((100% - 42px) / 4) !important;
  box-sizing:border-box;
  scroll-snap-align:start;
  margin:0 !important;
}

.recomendacao-seta{
  top:50%;
}

.recomendacao-seta.anterior{
  left:-18px;
}

.recomendacao-seta.proxima{
  right:-18px;
}

@media(max-width:1100px){
  #listaRecomendacoesVaga .recomendacao-card{
    flex-basis:calc((100% - 28px) / 3) !important;
    width:calc((100% - 28px) / 3) !important;
    min-width:calc((100% - 28px) / 3) !important;
    max-width:calc((100% - 28px) / 3) !important;
  }
}

@media(max-width:800px){
  #listaRecomendacoesVaga .recomendacao-card{
    flex-basis:calc((100% - 14px) / 2) !important;
    width:calc((100% - 14px) / 2) !important;
    min-width:calc((100% - 14px) / 2) !important;
    max-width:calc((100% - 14px) / 2) !important;
  }
}

@media(max-width:560px){
  #listaRecomendacoesVaga .recomendacao-card{
    flex-basis:88% !important;
    width:88% !important;
    min-width:88% !important;
    max-width:88% !important;
  }

  .recomendacao-seta{
    display:none !important;
  }
}



