/* =====================================================
   APROVA&#199;&#195;O AUTOM&#193;TICA DE VAGAS
===================================================== */

.aprovacao-auto-card{
  margin:20px 0 24px;
  padding:20px;
  border:1px solid #cfe1ec;
  border-radius:15px;
  background:linear-gradient(135deg,#f8fcff,#eef7fd);
}

.aprovacao-auto-card h3{
  margin:0 0 6px;
  font-size:17px;
}

.aprovacao-auto-card p{
  margin:0;
  color:var(--cinza);
  font-size:12px;
  line-height:1.65;
}

.aprovacao-auto-status{
  display:inline-flex;
  align-items:center;
  gap:6px;
  margin-top:12px;
  padding:6px 10px;
  border-radius:20px;
  background:#e7f6ec;
  color:#176b3a;
  font-size:10px;
  font-weight:800;
}

.aprovacao-auto-status.inativa{
  background:#f1f3f5;
  color:#667085;
}

.aprovacao-auto-status.suspensa{
  background:#feeceb;
  color:#b42318;
}

.aprovacao-auto-regras{
  margin-top:13px;
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:8px;
}

.aprovacao-auto-regras div{
  padding:9px 10px;
  border:1px solid #dde7ee;
  border-radius:9px;
  background:#fff;
  color:#40576a;
  font-size:10px;
  line-height:1.45;
}

.admin-auto-card{
  margin-top:18px;
  padding:17px;
  border:1px solid #dfe6ec;
  border-radius:12px;
  background:#fbfcfd;
}

.admin-auto-card h3{
  margin:0 0 6px;
  font-size:15px;
}

.admin-auto-card p{
  color:var(--cinza);
  font-size:11px;
  line-height:1.55;
}

.admin-auto-switch{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  margin-top:12px;
}

@media(max-width:700px){
  .aprovacao-auto-regras{
    grid-template-columns:1fr;
  }
}



/* =====================================================
   ADMIN - DESTAQUE GRATUITO DE VAGAS
===================================================== */

.admin-destaque-gratis{
  display:inline-flex;
  align-items:center;
  gap:6px;
  padding:6px 9px;
  border-radius:20px;
  background:#fff4d8;
  color:#8a6100;
  font-size:10px;
  font-weight:800;
}

.admin-destaque-info{
  margin-top:10px;
  padding:10px 12px;
  border:1px solid #eadcad;
  border-radius:9px;
  background:#fffaf0;
  color:#765c1d;
  font-size:10px;
  line-height:1.5;
}

.btn-destaque-gratis{
  border:1px solid #e1bd58 !important;
  background:#fff8df !important;
  color:#8a6100 !important;
}

.btn-destaque-gratis:hover{
  background:#fff1ba !important;
}

.btn-remover-destaque{
  border:1px solid #d7dee5 !important;
  background:#fff !important;
  color:#667085 !important;
}



/* =====================================================
   5 RECURSOS EST&#193;VEIS
   Experi&#234;ncia &#8226; Jornada &#8226; Benef&#237;cios &#8226; Pr&#233;via &#8226; Den&#250;ncia
===================================================== */

.vaga-dados-extras{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:12px;
  margin:15px 0 4px;
}

.vaga-dado-extra{
  padding:13px 15px;
  border:1px solid #e0e7ed;
  border-radius:11px;
  background:#fafcfd;
}

.vaga-dado-extra span{
  display:block;
  margin-bottom:4px;
  color:#667085;
  font-size:10px;
  font-weight:700;
  text-transform:uppercase;
}

.vaga-dado-extra strong{
  color:var(--texto);
  font-size:13px;
}

.beneficios-tags{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  margin-top:13px;
}

.beneficios-tags span{
  padding:7px 10px;
  border:1px solid #d7e4ed;
  border-radius:20px;
  background:#f5fafe;
  color:#31536d;
  font-size:11px;
  font-weight:700;
}

.beneficios-check-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:9px;
  margin-top:10px;
}

.beneficio-check{
  display:flex;
  align-items:center;
  gap:8px;
  padding:10px 11px;
  border:1px solid #dfe6ec;
  border-radius:9px;
  background:#fff;
  font-size:11px;
  cursor:pointer;
}

.beneficio-check input{
  width:16px;
  height:16px;
}

.publicar-beneficios-box{
  margin:18px 0;
  padding:18px;
  border:1px solid #dde6ed;
  border-radius:13px;
  background:#fafcfd;
}

.publicar-beneficios-box h3{
  margin:0 0 5px;
  font-size:16px;
}

.publicar-beneficios-box p{
  margin:0 0 10px;
  color:#667085;
  font-size:11px;
  line-height:1.55;
}

.acoes-publicar-estaveis{
  display:flex;
  flex-wrap:wrap;
  gap:10px;
  margin-top:16px;
}

.btn-preview-vaga{
  border:1px solid #cbd8e2;
  background:#fff;
  color:var(--azul);
}

.preview-vaga-modal{
  width:min(100%,720px);
  max-height:82vh;
  overflow:auto;
}

.preview-vaga-conteudo h2{
  margin:0 0 6px;
  font-size:27px;
  line-height:1.25;
}

.preview-vaga-empresa{
  color:#667085;
  font-size:12px;
  font-weight:700;
}

.preview-vaga-meta{
  display:flex;
  flex-wrap:wrap;
  gap:7px;
  margin:14px 0;
}

.preview-vaga-meta span{
  padding:6px 8px;
  border-radius:8px;
  background:#f2f6f9;
  color:#536a7b;
  font-size:10px;
}

.preview-vaga-salario{
  margin:10px 0 18px;
  font-size:14px;
  font-weight:800;
  color:#16894d;
}

.preview-vaga-bloco{
  margin-top:17px;
}

.preview-vaga-bloco h3{
  margin-bottom:6px;
  font-size:15px;
}

.preview-vaga-bloco p{
  margin:0;
  color:#405466;
  font-size:12px;
  line-height:1.7;
  white-space:pre-line;
}

.denunciar-vaga{
  width:100%;
  margin-top:11px;
  padding:7px 0;
  border:0;
  background:none;
  color:#b42318;
  font-family:inherit;
  font-size:11px;
  font-weight:700;
  cursor:pointer;
  text-decoration:underline;
}

.admin-denuncias-box{
  margin:24px 0;
  padding:22px;
  border:1px solid #dfe6ec;
  border-radius:15px;
  background:#fff;
}

.admin-denuncias-box h2{
  margin:0 0 5px;
  font-size:19px;
}

.admin-denuncias-box>p{
  margin:0 0 15px;
  color:#667085;
  font-size:11px;
}

.admin-denuncia-item{
  padding:14px;
  border:1px solid #e1e7ec;
  border-radius:10px;
  background:#fbfcfd;
}

.admin-denuncia-item + .admin-denuncia-item{
  margin-top:9px;
}

.admin-denuncia-item p{
  margin:5px 0 0;
  color:#667085;
  font-size:10px;
  line-height:1.55;
}

@media(max-width:760px){
  .beneficios-check-grid{
    grid-template-columns:1fr 1fr;
  }
}

@media(max-width:560px){
  .vaga-dados-extras,
  .beneficios-check-grid{
    grid-template-columns:1fr;
  }

  .acoes-publicar-estaveis{
    flex-direction:column;
  }

  .acoes-publicar-estaveis .btn{
    width:100%;
  }
}



/* RODAP&#201; DA VAGA: DATAS + DEN&#218;NCIA */
.datas-vaga-rodape-novo{
  display:grid;
  grid-template-columns:1fr 1fr auto;
  align-items:center;
  gap:24px;
}

.datas-vaga-rodape-novo > div:nth-child(2){
