/* =====================================================
   CENTRALIZA&#199;&#195;O DA COLUNA LATERAL DA VAGA
===================================================== */

.aplicar-lateral{
  text-align:center !important;
}

.aplicar-lateral h2,
.aplicar-lateral h3,
.aplicar-lateral p,
