/* =====================================================
   PERFIL P&#218;BLICO DA EMPRESA VERIFICADA - REFOR&#199;O VISUAL
===================================================== */

.empresa-publica-cab{
  padding:34px !important;
}

.empresa-publica-topo{
  align-items:center !important;
}

.empresa-publica-identidade{
  display:flex;
  align-items:center;
  gap:18px;
}

.empresa-publica-logo{
  width:92px;
  height:92px;
  flex:none;
  border:1px solid #dfe6ec;
  border-radius:18px;
  background:#fff;
  object-fit:cover;
  box-shadow:0 8px 24px rgba(16,24,40,.06);
}

.empresa-publica-nome h1{
  font-size:32px !important;
  line-height:1.2;
}

.empresa-publica-contador{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  margin-left:7px;
  padding:4px 8px;
  border-radius:20px;
  background:#eaf4fb;
  color:var(--azul);
  font-size:11px;
  font-weight:800;
}

.empresa-publica-vagas-lista{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:14px;
}

.empresa-publica-vagas-lista .vaga-card{
  margin:0 !important;
}

.empresa-lateral-verificada{
  margin-top:14px;
  padding-top:14px;
  border-top:1px solid #e5e9ed;
}

.empresa-lateral-verificada .nome{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:7px;
  margin-bottom:7px;
  font-size:15px;
  font-weight:800;
  color:var(--texto);
}

.empresa-lateral-verificada .selo{
  display:inline-flex;
  padding:3px 7px;
  border-radius:20px;
  background:#e6f5eb;
  color:#176b3a;
  font-size:9px;
  font-weight:800;
}

.empresa-lateral-verificada .vagas-abertas{
  margin:8px 0 12px;
  color:#667085;
  font-size:11px;
}

.empresa-lateral-verificada .btn{
  width:100%;
}

@media(max-width:760px){
  .empresa-publica-identidade{
    flex-direction:column;
    align-items:flex-start;
  }

  .empresa-publica-logo{
    width:78px;
    height:78px;
  }

  .empresa-publica-vagas-lista{
    grid-template-columns:1fr;
  }
}



/* =====================================================
   STATUS VISUAL DA VAGA
===================================================== */

.status-visual-vaga{
  display:flex;
  flex-wrap:wrap;
  align-items:center;
  gap:8px;
  margin:14px 0 4px;
}

.status-vaga-chip{
  display:inline-flex;
  align-items:center;
  gap:6px;
  padding:7px 10px;
  border-radius:20px;
  font-size:11px;
  font-weight:800;
  line-height:1;
  border:1px solid transparent;
}

.status-vaga-chip.recente{
  background:#eaf5ff;
  border-color:#cfe5f7;
  color:#0b67a8;
}

.status-vaga-chip.normal{
  background:#f4f7f9;
  border-color:#dfe6ec;
  color:#52687a;
}

.status-vaga-chip.atencao{
  background:#fff6df;
  border-color:#f1dfab;
  color:#8a6100;
}

.status-vaga-chip.ultimo-dia{
  background:#feeceb;
  border-color:#f3c9c5;
  color:#b42318;
}

.status-vaga-chip.encerrada{
  background:#f1f3f5;
  border-color:#d9dee3;
  color:#667085;
}

@media(max-width:600px){
  .status-visual-vaga{
    gap:7px;
  }

  .status-vaga-chip{
    font-size:10px;
  }
}



/* =====================================================
   ADMIN - TODAS AS VAGAS + DESTAQUE EXCLUSIVO
===================================================== */

.admin-destaque-exclusivo-aviso{
  margin:0 0 18px;
  padding:14px 16px;
  border:1px solid #cfe1ec;
  border-radius:11px;
  background:#f5fbff;
  color:#405c70;
  font-size:11px;
  line-height:1.6;
}

.admin-destaque-exclusivo-aviso strong{
  color:#0b67a8;
}

.admin-vaga-origem{
  display:inline-flex;
  margin-top:7px;
  padding:4px 7px;
  border-radius:20px;
  background:#f2f5f7;
  color:#667085;
  font-size:9px;
  font-weight:800;
}

.admin-vaga-origem.sistema{
  background:#eef4ff;
  color:#3157a4;
}

.admin-vaga-origem.empresa{
  background:#eef8f1;
  color:#176b3a;
}

.admin-botao-destaque{
  border:1px solid #e4c25c !important;
  background:#fff8df !important;
  color:#8a6100 !important;
}

.admin-botao-destaque:hover{
  background:#fff1be !important;
}

.admin-botao-remover-destaque{
  border:1px solid #d7dee5 !important;
  background:#fff !important;
  color:#667085 !important;
}

.admin-status-destaque{
  display:inline-flex;
  align-items:center;
  gap:5px;
  margin-top:8px;
  padding:5px 8px;
  border-radius:20px;
  background:#fff4d8;
  color:#8a6100;
  font-size:9px;
  font-weight:800;
}



/* =====================================================
   VAGAS EM AN&#193;LISE - PAINEL DA EMPRESA
===================================================== */
.painel-vagas-pendentes{
  margin-bottom:20px;
  border-color:#f0d9a5 !important;
  background:#fffdf7 !important;
}

.vaga-pendente-empresa{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:18px;
  padding:16px 18px;
  border:1px solid #eadfbe;
  border-radius:12px;
  background:#fff;
}

.vaga-pendente-empresa + .vaga-pendente-empresa{
  margin-top:10px;
}

.vaga-pendente-empresa h3{
  margin:0 0 5px;
  font-size:16px;
}

.vaga-pendente-empresa p{
  margin:0;
  color:#667085;
  font-size:11px;
}

.status-em-analise{
  display:inline-flex;
  padding:6px 9px;
  border-radius:20px;
  background:#fff3d6;
  color:#8a6100;
  font-size:10px;
  font-weight:800;
  white-space:nowrap;
}

@media(max-width:700px){
  .vaga-pendente-empresa{
    align-items:flex-start;
    flex-direction:column;
  }
}



/* =====================================================
   FILA PENDENTE VIS&#205;VEL - ADMIN
===================================================== */
.admin-fila-pendentes-box{
  margin:22px 0;
  padding:22px;
  border:1px solid #efd7a0;
  border-radius:15px;
  background:#fffaf0;
}

.admin-fila-pendentes-cab{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:20px;
  margin-bottom:14px;
}

.admin-fila-pendentes-cab h2{
  margin:0 0 4px;
  font-size:20px;
}

.admin-fila-pendentes-cab p{
  margin:0;
  color:#667085;
  font-size:11px;
}

.admin-fila-pendentes-numero{
  display:flex;
  align-items:center;
  justify-content:center;
  min-width:46px;
  height:46px;
  border-radius:50%;
  background:#fff0c7;
  color:#8a6100;
  font-size:19px;
  font-weight:800;
}

.admin-pendente-card{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:18px;
  padding:15px 16px;
  border:1px solid #eadfbe;
  border-radius:11px;
  background:#fff;
}

.admin-pendente-card + .admin-pendente-card{
  margin-top:9px;
}

.admin-pendente-card h3{
  margin:0 0 5px;
  font-size:15px;
}

.admin-pendente-card p{
  margin:0;
  color:#667085;
  font-size:10px;
}

.admin-pendente-acoes{
  display:flex;
  flex-wrap:wrap;
  gap:7px;
}

@media(max-width:720px){
  .admin-pendente-card{
    align-items:flex-start;
    flex-direction:column;
  }
}



/* FILA DE APROVA&#199;&#195;O - POSI&#199;&#195;O CORRETA NO ADMIN */
#pagina-painel-admin .admin-fila-pendentes-box{
  display:block !important;
  margin:24px 0 !important;
}

#pagina-painel-admin #adminListaPendentes{
  display:block !important;
}

#pagina-painel-admin .admin-pendente-card{
  display:flex !important;
  align-items:center !important;
  justify-content:space-between !important;
}


/* ===== EmpregaMais: Contrata&#231;&#227;o Urgente ===== */
.opcao-urgente-em {
  margin: 18px 0;
  padding: 16px;
  border: 1px solid #e5e7eb;
  border-radius: 14px;
  background: #fffaf0;
}
.opcao-urgente-em label {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  cursor: pointer;
  font-weight: 700;
}
.opcao-urgente-em small {
  display: block;
  margin: 7px 0 0 28px;
  color: #5f6368;
  line-height: 1.45;
}
.tag-contratacao-urgente {
  display: inline-flex;
  align-items: center;
  padding: 5px 9px;
  margin: 4px 6px 4px 0;
  border-radius: 999px;
  background: #fff3cd;
  border: 1px solid #e2b93b;
  color: #684f00;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .03em;
  text-transform: uppercase;
}


/* Recrutador: a&#231;&#245;es das vagas em an&#225;lise */
.vaga-pendente-acoes{
  display:flex;
  gap:10px;
  flex-wrap:wrap;
  align-items:center;
  margin-top:12px;
}
.vaga-pendente-acoes .btn{
  min-width:96px;
}
@media (max-width:640px){
  .vaga-pendente-acoes{
    width:100%;
  }
  .vaga-pendente-acoes .btn{
    flex:1;
  }
}


/* ===== Pr&#233;-visualiza&#231;&#227;o Contrata&#231;&#227;o Urgente ===== */
.preview-urgente-em{
  position:fixed;
  inset:0;
  z-index:99999;
  display:none;
  align-items:center;
  justify-content:center;
  padding:20px;
  background:rgba(15,23,42,.58);
}
.preview-urgente-em.ativo{display:flex}
.preview-urgente-caixa{
  width:min(680px,100%);
  max-height:90vh;
  overflow:auto;
  background:#fff;
  border-radius:20px;
  padding:26px;
  box-shadow:0 24px 70px rgba(0,0,0,.22);
}
.preview-urgente-topo{
  display:flex;
  justify-content:space-between;
  gap:16px;
  align-items:flex-start;
  margin-bottom:18px;
}
.preview-urgente-aviso{
  font-size:12px;
  font-weight:800;
  text-transform:uppercase;
  letter-spacing:.05em;
  color:#8a6200;
}
.preview-urgente-fechar{
  border:0;
  background:transparent;
  font-size:26px;
  cursor:pointer;
}
.preview-urgente-card{
  border:1px solid #ead49a;
  border-radius:16px;
  padding:22px;
  background:#fffdf7;
}
.preview-urgente-tag{
  display:inline-flex;
  align-items:center;
  border-radius:999px;
  padding:7px 11px;
  margin-bottom:13px;
  background:#fff0bd;
  color:#755400;
  font-size:11px;
  font-weight:900;
  text-transform:uppercase;
  letter-spacing:.04em;
}
.preview-urgente-card h2{
  margin:0 0 7px;
  font-size:23px;
}
.preview-urgente-meta{
  color:#64748b;
  font-size:14px;
  margin-bottom:18px;
}
.preview-urgente-secao{
  margin-top:17px;
}
.preview-urgente-secao strong{
  display:block;
  margin-bottom:6px;
}
.preview-urgente-acoes{
  display:flex;
  gap:10px;
  justify-content:flex-end;
  margin-top:20px;
  flex-wrap:wrap;
}
.preview-urgente-acoes button{
  min-height:44px;
  padding:0 18px;
  border-radius:10px;
  cursor:pointer;
  font-weight:800;
}
.preview-urgente-voltar{
  border:1px solid #cbd5e1;
  background:#fff;
}
.preview-urgente-confirmar{
  border:0;
  background:#0b67c2;
  color:#fff;
}
.preview-urgente-preco{
  margin-top:15px;
  padding:12px 14px;
  border-radius:12px;
  background:#f8fafc;
  font-size:13px;
  color:#475569;
}
@media(max-width:640px){
  .preview-urgente-caixa{padding:18px}
  .preview-urgente-acoes button{width:100%}
}


/* ===== Popup personalizado: excluir vaga ===== */
.popup-excluir-vaga-em{
  position:fixed;
  inset:0;
  z-index:100000;
  display:none;
  align-items:center;
  justify-content:center;
  padding:20px;
  background:rgba(15,23,42,.55);
}
.popup-excluir-vaga-em.ativo{display:flex}
.popup-excluir-vaga-caixa{
  width:min(470px,100%);
  background:#fff;
  border-radius:18px;
  padding:26px;
  box-shadow:0 25px 70px rgba(0,0,0,.25);
  text-align:center;
}
.popup-excluir-vaga-icone{
  width:54px;
  height:54px;
  margin:0 auto 14px;
  border-radius:50%;
  display:flex;
  align-items:center;
  justify-content:center;
  background:#fff1f0;
  color:#b42318;
  font-size:25px;
  font-weight:900;
}
.popup-excluir-vaga-caixa h3{
  margin:0 0 10px;
  font-size:21px;
}
.popup-excluir-vaga-caixa p{
  margin:0;
  color:#64748b;
  line-height:1.55;
  font-size:14px;
}
.popup-excluir-vaga-acoes{
  display:flex;
  justify-content:center;
  gap:10px;
  margin-top:22px;
}
.popup-excluir-vaga-acoes button{
  min-width:130px;
  min-height:44px;
  border-radius:10px;
  font-weight:800;
  cursor:pointer;
}
.popup-excluir-cancelar{
  border:1px solid #cbd5e1;
  background:#fff;
  color:#334155;
}
.popup-excluir-confirmar{
  border:0;
  background:#b42318;
  color:#fff;
}
@media(max-width:520px){
  .popup-excluir-vaga-acoes{flex-direction:column-reverse}
  .popup-excluir-vaga-acoes button{width:100%}
}


/* ===== Estado + Cidade - Brasil ===== */
.linha-campos-localizacao{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:14px;
  width:100%;
}
.linha-campos-localizacao > div{
  min-width:0;
}
.linha-campos-localizacao label{
  display:block;
  margin-bottom:7px;
}
@media(max-width:640px){
  .linha-campos-localizacao{
    grid-template-columns:1fr;
  }
}


/* =========================================================
   EMPREGAMAIS - CARDS DE VAGAS MAIS COMPACTOS
   Mant&#233;m a identidade visual e reduz espa&#231;os verticais.
========================================================= */

/* Cards/listagens de vagas */
.job-card,
.vaga-card,
.card-vaga,
.job-item,
.vaga-item{
  padding:18px 24px !important;
  margin-bottom:14px !important;
  min-height:0 !important;
}

/* Empresa */
.job-card .company,
.job-card .empresa,
.vaga-card .company,
.vaga-card .empresa,
.card-vaga .empresa{
  margin-top:0 !important;
  margin-bottom:6px !important;
}

/* Cargo */
.job-card h2,
.job-card h3,
.vaga-card h2,
.vaga-card h3,
.card-vaga h2,
.card-vaga h3{
  margin-top:5px !important;
  margin-bottom:9px !important;
  line-height:1.22 !important;
}

/* Tags */
.job-card .labels,
.job-card .tags,
.job-card .meta,
.vaga-card .labels,
.vaga-card .tags,
.vaga-card .meta,
.card-vaga .labels,
.card-vaga .tags,
.card-vaga .meta{
  margin-top:5px !important;
  margin-bottom:9px !important;
  gap:6px !important;
}

/* Sal&#225;rio */
.job-card .salary,
.job-card .salario,
.vaga-card .salary,
.vaga-card .salario,
.card-vaga .salary,
.card-vaga .salario{
  margin-top:7px !important;
  margin-bottom:8px !important;
}

/* Descri&#231;&#227;o/resumo */
.job-card .job-snippet,
.job-card .descricao,
.job-card .description,
.vaga-card .job-snippet,
.vaga-card .descricao,
.vaga-card .description,
.card-vaga .job-snippet,
.card-vaga .descricao{
  margin-top:7px !important;
  margin-bottom:12px !important;
  line-height:1.55 !important;
  display:-webkit-box !important;
  -webkit-box-orient:vertical !important;
  -webkit-line-clamp:2 !important;
  overflow:hidden !important;
}

/* Rodap&#233; do card */
.job-card .job-footer,
.job-card .footer,
.job-card .vaga-footer,
.vaga-card .job-footer,
.vaga-card .footer,
.vaga-card .vaga-footer,
.card-vaga .job-footer,
.card-vaga .footer,
.card-vaga .vaga-footer{
  margin-top:12px !important;
  padding-top:12px !important;
  min-height:0 !important;
}

/* Bot&#245;es mais proporcionais */
.job-card .btn,
.job-card button,
.vaga-card .btn,
.vaga-card button,
.card-vaga .btn,
.card-vaga button{
  min-height:40px !important;
}

/* Mobile */
@media(max-width:640px){
  .job-card,
  .vaga-card,
  .card-vaga,
  .job-item,
  .vaga-item{
    padding:16px !important;
    margin-bottom:12px !important;
  }

  .job-card .job-footer,
  .job-card .footer,
  .job-card .vaga-footer,
  .vaga-card .job-footer,
  .vaga-card .footer,
  .vaga-card .vaga-footer,
  .card-vaga .job-footer,
  .card-vaga .footer,
  .card-vaga .vaga-footer{
    margin-top:10px !important;
    padding-top:10px !important;
  }
}


/* =========================================================
   AJUSTE FINAL - CAIXA DA VAGA REALMENTE MAIS CURTA
========================================================= */

.lista-vagas{
  gap:9px !important;
}

.vaga-card{
  padding:13px 18px !important;
  border-radius:13px !important;
  min-height:0 !important;
}

.vaga-card-top{
  gap:10px !important;
}

.vaga-card .logo-empresa,
.vaga-card .logo-placeholder{
  width:44px !important;
  height:44px !important;
  border-radius:9px !important;
}

.vaga-card .vaga-empresa{
  margin:0 0 3px !important;
  line-height:1.2 !important;
}

.vaga-card .vaga-titulo{
  margin:0 0 6px !important;
  font-size:17px !important;
  line-height:1.22 !important;
}

.vaga-card .tags{
  gap:5px !important;
  margin:0 !important;
}

.vaga-card .tag{
  padding:4px 7px !important;
  line-height:1.2 !important;
}

.vaga-card .salario{
  margin-top:8px !important;
  font-size:13px !important;
  line-height:1.25 !important;
}

.vaga-card .vaga-resumo{
  margin-top:7px !important;
  font-size:12.5px !important;
  line-height:1.45 !important;
  display:-webkit-box !important;
  -webkit-box-orient:vertical !important;
  -webkit-line-clamp:1 !important;
  overflow:hidden !important;
  text-overflow:ellipsis !important;
}

.vaga-card-footer{
  margin-top:9px !important;
  padding-top:9px !important;
  gap:10px !important;
}

.vaga-card .vaga-data{
  font-size:10.5px !important;
}

.vaga-card .card-acoes{
  gap:6px !important;
}

.vaga-card .favorito{
  width:35px !important;
  height:35px !important;
  min-height:35px !important;
}

.vaga-card .btn{
  min-height:35px !important;
  height:35px !important;
  padding:0 14px !important;
  font-size:12px !important;
}

@media(max-width:640px){
  .vaga-card{
    padding:12px 13px !important;
  }

  .vaga-card .vaga-titulo{
    font-size:16px !important;
  }

  .vaga-card .vaga-resumo{
    -webkit-line-clamp:2 !important;
  }

  .vaga-card-footer{
    margin-top:8px !important;
    padding-top:8px !important;
  }
}


/* =========================================================
   CARDS MAIS ESTREITOS + BORDA AZUL FORTE
========================================================= */

/* A lista continua centralizada, mas os cards n&#227;o ocupam
   toda a largura dispon&#237;vel da p&#225;gina. */
.lista-vagas{
  width:100% !important;
}

/* Caixa da vaga */
.vaga-card{
  width:calc(100% - 90px) !important;
  max-width:1080px !important;
  margin-left:auto !important;
  margin-right:auto !important;

  /* azul forte e elegante nas linhas da borda */
  border:1.5px solid #0866c6 !important;
  border-left:4px solid #0866c6 !important;

  box-sizing:border-box !important;
}

/* Linha divis&#243;ria inferior do card */
.vaga-card-footer{
  border-top:1px solid rgba(8,102,198,.32) !important;
}

/* Mant&#233;m o azul tamb&#233;m quando passa o mouse */
.vaga-card:hover{
  border-color:#0759ad !important;
  border-left-color:#0759ad !important;
}

/* Tablet */
@media(max-width:900px){
  .vaga-card{
    width:calc(100% - 36px) !important;
  }
}

/* Celular: aproveita a tela sem ficar apertado */
@media(max-width:640px){
  .vaga-card{
    width:calc(100% - 20px) !important;
    border:1.5px solid #0866c6 !important;
    border-left:4px solid #0866c6 !important;
  }
}


/* =========================================================
   POPUP DENUNCIAR VAGA - VISUAL PROFISSIONAL
========================================================= */
#modalDenunciaEmpregaMais{
  position:fixed;
  inset:0;
  z-index:999999;
  display:none;
  align-items:center;
  justify-content:center;
  padding:20px;
  background:rgba(15,23,42,.58);
  backdrop-filter:blur(2px);
}
#modalDenunciaEmpregaMais.ativo{display:flex}
.denuncia-box-em{
  position:relative;
  width:min(500px,100%);
  max-height:calc(100vh - 32px);
  overflow-y:auto;
  box-sizing:border-box;
  background:#fff;
  border:1px solid #e2e8f0;
  border-radius:15px;
  box-shadow:0 24px 70px rgba(15,23,42,.24);
  padding:24px;
}
.denuncia-fechar-em{
  position:absolute;
  top:15px;
  right:16px;
  width:34px;
  height:34px;
  border:0;
  background:transparent;
  color:#64748b;
  font-size:25px;
  line-height:1;
  cursor:pointer;
}
.denuncia-box-em h2{
  margin:0 42px 18px 0;
  font-size:26px;
  line-height:1.25;
  color:#111827;
}
.denuncia-box-em select,
.denuncia-box-em textarea{
  width:100%;
  box-sizing:border-box;
  border:1px solid #cbd5e1;
  border-radius:9px;
  background:#fff;
  color:#1f2937;
  font:inherit;
  outline:none;
}
.denuncia-box-em select{
  height:48px;
  padding:0 14px;
}
.denuncia-box-em textarea{
  min-height:126px;
  resize:vertical;
  padding:13px 14px;
  line-height:1.5;
}
.denuncia-box-em select:focus,
.denuncia-box-em textarea:focus{
  border-color:#0866c6;
  box-shadow:0 0 0 3px rgba(8,102,198,.10);
}
.denuncia-ajuda-em{
  margin:20px 0 10px;
  color:#64748b;
  font-size:14px;
  line-height:1.55;
}
.denuncia-contador-em{
  margin-top:4px;
  text-align:right;
  color:#64748b;
  font-size:10px;
}
.denuncia-arquivo-em{
  display:inline-flex;
  align-items:center;
  gap:7px;
  margin-top:16px;
  color:#0874d8;
  font-size:15px;
  cursor:pointer;
}
.denuncia-arquivo-em input{display:none}
.denuncia-arquivo-info-em{
  margin:7px 0 0;
  color:#64748b;
  font-size:13px;
  line-height:1.45;
}
.denuncia-nome-arquivo-em{
  margin-top:6px;
  color:#334155;
  font-size:12px;
}
.denuncia-acoes-em{
  display:flex;
  justify-content:flex-end;
  align-items:center;
  gap:14px;
  margin-top:28px;
}
.denuncia-cancelar-em{
  border:0;
  background:transparent;
  color:#0874d8;
  font-weight:600;
  padding:11px 12px;
  cursor:pointer;
}
.denuncia-enviar-em{
  border:0;
  border-radius:24px;
  background:#e00000;
  color:#fff;
  font-weight:800;
  padding:12px 23px;
  cursor:pointer;
}
.denuncia-enviar-em:hover{background:#c90000}
@media(max-width:640px){
  #modalDenunciaEmpregaMais{
    padding:10px;
    align-items:center;
  }
  .denuncia-box-em{
    padding:20px 16px;
    border-radius:13px;
    max-height:calc(100vh - 20px);
  }
  .denuncia-box-em h2{
    font-size:23px;
  }
  .denuncia-acoes-em{
    gap:8px;
  }
}


/* =========================================================
   AJUSTE DE LARGURA - CARDS MAIS CURTOS
========================================================= */
.vaga-card{
  width:calc(100% - 30px) !important;
  max-width:780px !important;
  margin-left:auto !important;
  margin-right:auto !important;
}

@media(max-width:820px){
  .vaga-card{
    width:calc(100% - 24px) !important;
    max-width:none !important;
  }
}

@media(max-width:640px){
  .vaga-card{
    width:calc(100% - 16px) !important;
  }
}


/* =========================================================
   VAGAS EM DESTAQUE - CARROSSEL COM 4 VAGAS
========================================================= */
.destaques-carrossel-em{
  position:relative;
  width:100%;
  max-width:1180px;
  margin:0 auto;
  padding:0 42px;
  box-sizing:border-box;
}

.destaques-carrossel-em .destaques{
  display:flex !important;
  grid-template-columns:none !important;
  gap:14px !important;
  width:100% !important;
  overflow-x:auto !important;
  overflow-y:hidden !important;
  scroll-behavior:smooth;
  scroll-snap-type:x mandatory;
  scrollbar-width:none;
  padding:4px 2px 10px !important;
}
.destaques-carrossel-em .destaques::-webkit-scrollbar{
  display:none;
}

/* Exatamente quatro cards vis&#237;veis no desktop */
.destaques-carrossel-em .card-destaque{
  flex:0 0 calc((100% - 42px) / 4) !important;
  width:auto !important;
  max-width:none !important;
  min-width:0 !important;
  margin:0 !important;
  scroll-snap-align:start;
  box-sizing:border-box !important;
}

/* Cards de destaque mais compactos para caberem bem em 4 colunas */
.destaques-carrossel-em .card-destaque{
  padding:15px !important;
}
.destaques-carrossel-em .card-destaque .vaga-titulo{
  font-size:16px !important;
  line-height:1.25 !important;
}
.destaques-carrossel-em .card-destaque .vaga-resumo{
  display:-webkit-box !important;
  -webkit-box-orient:vertical !important;
  -webkit-line-clamp:2 !important;
  overflow:hidden !important;
}

/* Setas */
.destaques-seta-em{
  position:absolute;
  top:50%;
  transform:translateY(-50%);
  z-index:8;
  width:38px;
  height:38px;
  display:flex;
  align-items:center;
  justify-content:center;
  border:1px solid #0866c6;
  border-radius:50%;
  background:#fff;
  color:#0866c6;
  font-size:29px;
  line-height:1;
  cursor:pointer;
  box-shadow:0 5px 18px rgba(15,23,42,.12);
}
.destaques-seta-em:hover{
  background:#0866c6;
  color:#fff;
}
.destaques-seta-em.esquerda{
  left:0;
}
.destaques-seta-em.direita{
  right:0;
}
.destaques-seta-em:disabled{
  opacity:.28;
  cursor:default;
}

/* Tablet: 2 vagas */
@media(max-width:900px){
  .destaques-carrossel-em{
    padding:0 38px;
  }
  .destaques-carrossel-em .card-destaque{
    flex-basis:calc((100% - 14px) / 2) !important;
  }
}

/* Celular: 1 vaga por vez */
@media(max-width:640px){
  .destaques-carrossel-em{
    padding:0 32px;
  }
  .destaques-carrossel-em .card-destaque{
    flex-basis:100% !important;
  }
  .destaques-seta-em{
    width:32px;
    height:32px;
    font-size:25px;
  }
}


/* =========================================================
   VAGAS EM DESTAQUE - 3 VAGAS POR VEZ NA P&#193;GINA INICIAL
========================================================= */
@media(min-width:901px){
  .destaques-carrossel-em .card-destaque{
    flex:0 0 calc((100% - 28px) / 3) !important;
  }
}


/* =========================================================
