/* =========================================================
   CABE&#199;ALHO "VAGAS EM DESTAQUE" CENTRALIZADO
========================================================= */

/* Centraliza somente o cabe&#231;alho da se&#231;&#227;o de destaques */
#secaoDestaques .section-head,
#secaoDestaques .secao-cabecalho,
#secaoDestaques .titulo-secao,
.destaques-section .section-head,
.destaques-section .secao-cabecalho{
  text-align:center !important;
  justify-content:center !important;
  align-items:center !important;
  flex-direction:column !important;
  margin-left:auto !important;
  margin-right:auto !important;
}

/* T&#237;tulo */
#secaoDestaques h2,
.destaques-section h2{
  text-align:center !important;
  margin-left:auto !important;
  margin-right:auto !important;
}

/* Subt&#237;tulo */
#secaoDestaques .section-head p,
#secaoDestaques .secao-cabecalho p,
#secaoDestaques .titulo-secao p,
.destaques-section .section-head p,
.destaques-section .secao-cabecalho p{
  text-align:center !important;
  margin-left:auto !important;
  margin-right:auto !important;
}

/* Linha azul curta e centralizada */
#secaoDestaques h2:after,
.destaques-section h2:after{
  content:"" !important;
  display:block !important;
  width:46px !important;
  height:3px !important;
  margin:10px auto 0 !important;
  border-radius:999px !important;
  background:#0866c6 !important;
}


/* =========================================================
   CENTRALIZA&#199;&#195;O DEFINITIVA DO CABE&#199;ALHO DE DESTAQUES
========================================================= */
.cabecalho-destaques-centralizado-em{
  width:100% !important;
  display:flex !important;
  flex-direction:column !important;
  align-items:center !important;
  justify-content:center !important;
  text-align:center !important;
  margin-left:auto !important;
  margin-right:auto !important;
}
.cabecalho-destaques-centralizado-em h1,
.cabecalho-destaques-centralizado-em h2,
.cabecalho-destaques-centralizado-em h3,
.cabecalho-destaques-centralizado-em p{
  width:100% !important;
  text-align:center !important;
  margin-left:auto !important;
  margin-right:auto !important;
}
.cabecalho-destaques-centralizado-em:after{
  content:"" !important;
  display:block !important;
  width:48px !important;
  height:3px !important;
  margin:11px auto 0 !important;
  border-radius:999px !important;
  background:#0866c6 !important;
}


/* =========================================================
   VAGAS EM DESTAQUE - VISUAL PREMIUM / MAIS CHAMATIVO
   Aplica somente aos cards do carrossel de destaques.
========================================================= */

/* Cabe&#231;alho: pequeno selo acima do t&#237;tulo */
.titulo-secao-destaques-premium-em{
  position:relative !important;
  padding-top:34px !important;
}
.titulo-secao-destaques-premium-em:before{
  content:"&#9733;  DESTAQUES" !important;
  position:absolute !important;
  top:0 !important;
  left:50% !important;
  transform:translateX(-50%) !important;
  display:inline-flex !important;
  align-items:center !important;
  justify-content:center !important;
  padding:6px 11px !important;
  border:1px solid #ead28a !important;
  border-radius:999px !important;
  background:#fff9e8 !important;
  color:#9a6b00 !important;
  font-size:10px !important;
  font-weight:800 !important;
  letter-spacing:.08em !important;
  white-space:nowrap !important;
}

/* Card */
#listaDestaques .card-destaque{
  position:relative !important;
  overflow:hidden !important;
  background:#fff !important;
  border:2px solid #0866c6 !important;
  border-radius:15px !important;
  padding:20px 18px 17px !important;
  box-shadow:0 8px 25px rgba(8,102,198,.09) !important;
  transition:transform .22s ease,box-shadow .22s ease,border-color .22s ease !important;
}

/* Faixa azul superior */
#listaDestaques .card-destaque:before{
  content:"" !important;
  position:absolute !important;
  top:0 !important;
  left:0 !important;
  right:0 !important;
  height:5px !important;
  background:#0866c6 !important;
}

/* Hover */
#listaDestaques .card-destaque:hover{
  transform:translateY(-4px) !important;
  border-color:#0759ad !important;
  box-shadow:0 15px 34px rgba(8,102,198,.17) !important;
}

/* Selo existente DESTAQUE: transforma em dourado */
#listaDestaques .badge-destaque,
#listaDestaques .tag-destaque,
#listaDestaques .destaque-badge,
#listaDestaques [class*="destaque"]:not(.card-destaque){
  background:#fff7dd !important;
  border-color:#ead28a !important;
  color:#956700 !important;
}

/* Logo maior e mais refinada */
#listaDestaques .logo-empresa,
#listaDestaques .logo-placeholder,
#listaDestaques .logo-detalhe{
  width:58px !important;
  height:58px !important;
  flex:0 0 58px !important;
  padding:5px !important;
  box-sizing:border-box !important;
  object-fit:contain !important;
  background:#fff !important;
  border:1px solid #dce6f0 !important;
  border-radius:12px !important;
  box-shadow:0 5px 14px rgba(15,23,42,.07) !important;
}

/* Empresa */
#listaDestaques .vaga-empresa,
#listaDestaques .empresa{
  color:#64748b !important;
  font-size:11px !important;
  font-weight:650 !important;
}

/* Cargo */
#listaDestaques .vaga-titulo,
#listaDestaques .job-title{
  margin-top:11px !important;
  margin-bottom:10px !important;
  color:#0f172a !important;
  font-size:17px !important;
  line-height:1.28 !important;
  font-weight:800 !important;
  letter-spacing:-.01em !important;
}

/* Chips */
#listaDestaques .tags{
  gap:5px !important;
  margin:8px 0 !important;
}
#listaDestaques .tag{
  padding:5px 8px !important;
  border:1px solid #d9e9f8 !important;
  border-radius:999px !important;
  background:#f2f8fe !important;
  color:#456176 !important;
  font-size:10px !important;
  font-weight:650 !important;
}

/* Sal&#225;rio */
#listaDestaques .salario,
#listaDestaques .salary{
  margin-top:10px !important;
  color:#16803b !important;
  font-size:13px !important;
  font-weight:800 !important;
}

/* Resumo mais discreto */
#listaDestaques .vaga-resumo,
#listaDestaques .job-snippet,
#listaDestaques .descricao{
  color:#64748b !important;
  font-size:11px !important;
  line-height:1.5 !important;
  -webkit-line-clamp:2 !important;
}

/* Rodap&#233; */
#listaDestaques .vaga-card-footer,
#listaDestaques .card-footer{
  margin-top:13px !important;
  padding-top:12px !important;
  border-top:1px solid #e4edf5 !important;
}

/* Bot&#227;o principal do destaque */
#listaDestaques .btn-primary,
#listaDestaques .btn-ver-vaga,
#listaDestaques .btn:not(.favorito){
  border-radius:9px !important;
  background:#0866c6 !important;
  border-color:#0866c6 !important;
  color:#fff !important;
  font-weight:750 !important;
  box-shadow:0 5px 12px rgba(8,102,198,.15) !important;
}
#listaDestaques .btn-primary:hover,
#listaDestaques .btn-ver-vaga:hover,
#listaDestaques .btn:not(.favorito):hover{
  background:#0759ad !important;
  border-color:#0759ad !important;
}

/* Setas combinando com os novos cards */
.destaques-seta-em{
  border:2px solid #0866c6 !important;
  background:#fff !important;
  color:#0866c6 !important;
  box-shadow:0 7px 20px rgba(8,102,198,.13) !important;
}
.destaques-seta-em:hover{
  background:#0866c6 !important;
  color:#fff !important;
}

/* Mobile: mant&#233;m impacto sem exagerar */
@media(max-width:640px){
  #listaDestaques .card-destaque{
    padding:18px 15px 15px !important;
  }
  #listaDestaques .logo-empresa,
  #listaDestaques .logo-placeholder,
  #listaDestaques .logo-detalhe{
    width:52px !important;
    height:52px !important;
    flex-basis:52px !important;
  }
}


