   N&#227;o altera cards, vagas ou funcionalidades.
========================================================= */

/* Centraliza os cabe&#231;alhos das se&#231;&#245;es da p&#225;gina inicial */
#pagina-home .titulo-secao,
.home .titulo-secao,
body:not([class*="pagina-"]) .titulo-secao{
