/* =========================================================
   EMPREGAMAIS &#8212; NOVOS PLANOS 2026
========================================================= */
.planos-novos-em{
  max-width:1180px;
  margin:0 auto;
  padding:36px 20px 48px;
}
.planos-novos-cab-em{text-align:center;margin-bottom:26px;}
.planos-novos-cab-em h2{margin:0;color:#152238;font-size:29px;letter-spacing:-.03em;}
.planos-novos-cab-em p{margin:8px auto 0;max-width:650px;color:#708096;font-size:12px;}
.planos-grid-novos-em{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:14px;
  align-items:stretch;
}
.plano-card-novo-em{
  position:relative;
  display:flex;
  flex-direction:column;
  padding:22px 18px;
  background:#fff;
  border:1px solid #dfe7ef;
  border-radius:15px;
  box-shadow:0 7px 24px rgba(15,23,42,.05);
}
.plano-card-novo-em.plano-recomendado-em{border:2px solid #0866c6;}
.plano-selo-novo-em{
  position:absolute;top:-12px;left:50%;transform:translateX(-50%);
  padding:5px 10px;border-radius:999px;background:#0866c6;color:#fff;
  font-size:9px;font-weight:850;white-space:nowrap;letter-spacing:.04em;
}
.plano-nome-novo-em{font-size:17px;font-weight:850;color:#152238;}
.plano-periodo-novo-em{margin-top:4px;color:#7b899b;font-size:10px;}
.plano-preco-novo-em{margin:17px 0 3px;color:#0866c6;font-size:28px;font-weight:900;}
.plano-preco-novo-em small{font-size:11px;color:#7b899b;font-weight:600;}
.plano-vagas-novo-em{margin-bottom:15px;color:#26364b;font-size:11px;font-weight:750;}
.plano-recursos-novo-em{display:flex;flex-direction:column;gap:9px;margin:0 0 20px;padding:16px 0 0;border-top:1px solid #edf1f5;}
.plano-recurso-novo-em{display:flex;gap:7px;align-items:flex-start;color:#425268;font-size:10.5px;line-height:1.4;}
.plano-recurso-novo-em b{color:#0872ce;}
.plano-recurso-novo-em.nao-em{color:#9ba6b4;}
.plano-btn-novo-em{
  width:100%;margin-top:auto;padding:11px 12px;border:1px solid #0866c6;border-radius:8px;
  background:#fff;color:#0866c6;font-family:inherit;font-size:11px;font-weight:850;cursor:pointer;
}
.plano-recomendado-em .plano-btn-novo-em{background:#0866c6;color:#fff;}
.planos-nota-nova-em{margin:18px auto 0;text-align:center;color:#7a899c;font-size:10px;}
@media(max-width:950px){.planos-grid-novos-em{grid-template-columns:repeat(2,1fr);}}
@media(max-width:580px){
 .planos-novos-em{padding:28px 13px 38px;}
 .planos-grid-novos-em{grid-template-columns:1fr;}
 .planos-novos-cab-em h2{font-size:24px;}
}


/* =========================================================
   CADASTRO DA EMPRESA &#8212; CORRIGIDO SOBRE A ESTRUTURA REAL
========================================================= */
#pagina-cadastro-empresa{
  min-height:calc(100vh - 70px) !important;
  padding:34px 18px 56px !important;
  background:
    radial-gradient(circle at 8% 12%,rgba(8,102,198,.07),transparent 25%),
    #f4f7fb !important;
}
#pagina-cadastro-empresa .cadastro-empresa-shell-em{
  width:min(100%,1060px);
  margin:0 auto;
  display:grid;
  grid-template-columns:390px minmax(0,1fr);
  overflow:hidden;
  border:1px solid #dce5ef;
  border-radius:22px;
  background:#fff;
  box-shadow:0 22px 58px rgba(23,43,69,.10);
}
#pagina-cadastro-empresa .cadastro-empresa-info-em{
  position:relative;
  overflow:hidden;
  padding:42px 34px;
  background:linear-gradient(145deg,#0756a7 0%,#0869c8 58%,#147bd8 100%);
  color:#fff;
}
#pagina-cadastro-empresa .cadastro-empresa-info-em:before{
  content:"";
  position:absolute;
  width:260px;height:260px;right:-150px;top:-110px;
  border-radius:50%;background:rgba(255,255,255,.08);
}
#pagina-cadastro-empresa .cadastro-empresa-info-em:after{
  content:"";
  position:absolute;
  width:180px;height:180px;left:-95px;bottom:-90px;
  border-radius:50%;background:rgba(255,255,255,.06);
}
#pagina-cadastro-empresa .cadastro-empresa-info-conteudo-em{position:relative;z-index:1;}
#pagina-cadastro-empresa .cadastro-empresa-brand-em{
  display:flex;align-items:center;gap:9px;margin-bottom:35px;
  font-size:12px;font-weight:850;
}
#pagina-cadastro-empresa .cadastro-empresa-brand-em i{
  width:32px;height:32px;display:flex;align-items:center;justify-content:center;
  border-radius:9px;background:#fff;color:#0866c6;font-style:normal;font-weight:900;
}
#pagina-cadastro-empresa .cadastro-empresa-info-em h2{
  margin:0 0 11px;color:#fff;font-size:28px;line-height:1.13;letter-spacing:-.035em;
}
#pagina-cadastro-empresa .cadastro-empresa-info-em .lead-em{
  margin:0 0 28px;color:rgba(255,255,255,.78);font-size:11px;line-height:1.65;
}
#pagina-cadastro-empresa .cadastro-beneficio-em{
