}
#pagina-cadastro-empresa .cadastro-beneficio-em b{
  flex:none;width:29px;height:29px;display:flex;align-items:center;justify-content:center;
  border:1px solid rgba(255,255,255,.2);border-radius:8px;
  background:rgba(255,255,255,.11);font-size:10px;
}
#pagina-cadastro-empresa .cadastro-beneficio-em strong{
