/* =========================================================
   EMPREGAMAIS - RECOMENDACOES CORRIGIDAS
   4 cards normais, largura correta, tipografia leve
========================================================= */

/* Tipografia: sem negrito excessivo */
.vagas-recomendadas,
.vagas-relacionadas,
.recomendacoes-vaga,
#vagasRecomendadas,
#vagasRelacionadas,
.vagas-recomendadas *,
.vagas-relacionadas *,
.recomendacoes-vaga *,
#vagasRecomendadas *,
#vagasRelacionadas *{
  font-family:Arial,Helvetica,sans-serif!important;
}

.vagas-recomendadas,
.vagas-relacionadas,
.recomendacoes-vaga,
#vagasRecomendadas,
#vagasRelacionadas{
  box-sizing:border-box!important;
  width:100%!important;
  max-width:100%!important;
  overflow:hidden!important;
}

/* Mant&#233;m o trilho original ocupando 100% */
.vagas-recomendadas .lista-vagas,
.vagas-relacionadas .lista-vagas,
.recomendacoes-vaga .lista-vagas,
#vagasRecomendadas .lista-vagas,
#vagasRelacionadas .lista-vagas{
  box-sizing:border-box!important;
  display:grid!important;
  grid-template-columns:repeat(4,minmax(0,1fr))!important;
  gap:14px!important;
  width:100%!important;
  max-width:100%!important;
  min-width:0!important;
  margin:18px 0 0!important;
  padding:0!important;
  overflow:visible!important;
  transform:none!important;
}

/* Cards sem largura fixa */
.vagas-recomendadas .vaga-card,
.vagas-relacionadas .vaga-card,
.recomendacoes-vaga .vaga-card,
#vagasRecomendadas .vaga-card,
#vagasRelacionadas .vaga-card{
  box-sizing:border-box!important;
  width:100%!important;
  min-width:0!important;
  max-width:100%!important;
  height:auto!important;
  min-height:245px!important;
  margin:0!important;
  padding:17px!important;
  flex:none!important;
  border:1px solid #dbe3ec!important;
  border-radius:13px!important;
  background:#fff!important;
  box-shadow:none!important;
  overflow:hidden!important;
  display:flex!important;
  flex-direction:column!important;
}

/* Empresa discreta */
.vagas-recomendadas .vaga-empresa,
.vagas-relacionadas .vaga-empresa,
.recomendacoes-vaga .vaga-empresa,
#vagasRecomendadas .vaga-empresa,
#vagasRelacionadas .vaga-empresa{
  font-size:12px!important;
  line-height:1.35!important;
  font-weight:400!important;
  color:#52677a!important;
  margin:0 0 7px!important;
}

/* T&#237;tulo sem apar&#234;ncia pesada */
.vagas-recomendadas .vaga-titulo,
.vagas-relacionadas .vaga-titulo,
.recomendacoes-vaga .vaga-titulo,
#vagasRecomendadas .vaga-titulo,
#vagasRelacionadas .vaga-titulo{
  font-size:16px!important;
  line-height:1.3!important;
  font-weight:400!important;
  color:#111827!important;
  margin:0 0 10px!important;
  min-height:42px!important;
  overflow-wrap:break-word!important;
  word-break:normal!important;
}

/* Etiquetas */
.vagas-recomendadas .vaga-tags,
.vagas-relacionadas .vaga-tags,
.recomendacoes-vaga .vaga-tags,
#vagasRecomendadas .vaga-tags,
