}

/* Sal&#225;rio alinhado e sem peso exagerado */
.vagas-recomendadas .vaga-salario,
.vagas-relacionadas .vaga-salario,
.recomendacoes-vaga .vaga-salario,
#vagasRecomendadas .vaga-salario,
