/* Bot&#227;o */
.vagas-recomendadas .vaga-card-footer,
.vagas-relacionadas .vaga-card-footer,
.recomendacoes-vaga .vaga-card-footer,
#vagasRecomendadas .vaga-card-footer,
#vagasRelacionadas .vaga-card-footer{
