.btn-info-plano-rota-em{width:100%!important;margin-top:9px!important;background:#fff!important;color:#1769aa!important;border:1px solid #1769aa!important}
.btn-info-plano-rota-em:hover{background:#f1f7fb!important}
.det-plano-selo-em{display:inline-block;margin-bottom:9px;padding:5px 9px;border:1px solid rgba(255,255,255,.28);border-radius:30px;font-size:10px;font-weight:600}
.det-plano-main-em{max-width:1040px;margin:auto;padding:32px 24px 65px}
.det-plano-resumo-em{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:15px}
.det-plano-resumo-em>div{padding:17px;background:#fff;border:1px solid #dfe6ed;border-radius:12px}
.det-plano-resumo-em small{display:block;margin-bottom:5px;color:#718096;font-size:10px}
.det-plano-resumo-em strong{font-size:15px;font-weight:600}
.det-plano-box-em{margin-bottom:14px;padding:23px;background:#fff;border:1px solid #dfe6ed;border-radius:14px}
.det-plano-box-em h2{margin:0 0 14px!important;font-size:20px!important;font-weight:600!important}
.det-plano-box-em p{margin:0!important;color:#536273;font-size:13px!important;line-height:1.65!important;font-weight:400!important}
.det-plano-beneficio-em{padding:15px 0;border-bottom:1px solid #edf1f5}
.det-plano-beneficio-em:last-child{border-bottom:0}
.det-plano-beneficio-em h3{margin:0 0 5px!important;font-size:15px!important;font-weight:600!important}
.det-plano-beneficio-em p{font-size:13px!important}
.det-plano-check-em{margin-right:7px;color:#168047}
.det-plano-nao-em{margin-top:12px;padding:12px;border-radius:9px;background:#f8fafc;color:#718096;font-size:12px}
.det-plano-grid-em{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.det-plano-final-em{display:flex;align-items:center;justify-content:space-between;gap:20px}
.det-plano-final-em strong{font-size:17px;font-weight:600}
@media(max-width:700px){.det-plano-main-em{padding:20px 12px 45px}.det-plano-resumo-em,.det-plano-grid-em{grid-template-columns:1fr}.det-plano-final-em{display:block}.det-plano-final-em .btn{width:100%;margin-top:14px}}



