/* =========================================================
   EMPREGAMAIS - TIPOGRAFIA ARIAL MAIS LEVE
   Remove apar&#234;ncia grossa sem tirar hierarquia dos t&#237;tulos
========================================================= */
html,body,button,input,select,textarea,
h1,h2,h3,h4,h5,h6,p,span,a,div,label,strong,b,small,li{
  font-family:Arial,Helvetica,sans-serif!important;
}

/* textos gerais */
body,p,span,a,div,label,li,input,select,textarea{
  font-weight:400!important;
}

/* t&#237;tulos: Arial sem peso excessivo */
h1{font-weight:600!important}
h2{font-weight:600!important}
h3,h4,h5,h6{font-weight:500!important}

/* cards de vagas */
.vaga-titulo,
.vaga-card h3,
.card-destaque h3{
  font-family:Arial,Helvetica,sans-serif!important;
  font-weight:600!important;
}
.vaga-empresa,
.vaga-meta,
.vaga-card p,
.vaga-card span,
.card-destaque p,
.card-destaque span{
  font-family:Arial,Helvetica,sans-serif!important;
  font-weight:400!important;
}

/* sal&#225;rio continua destacado, mas sem fonte pesada */
.vaga-salario,
.salario,
[class*="salario"]{
  font-family:Arial,Helvetica,sans-serif!important;
  font-weight:600!important;
}

/* selo e tags */
.tag,.badge,.selo,.vaga-tag,
[class*="badge"],[class*="selo"]{
  font-family:Arial,Helvetica,sans-serif!important;
  font-weight:500!important;
}

/* bot&#245;es */
button,.btn{
  font-family:Arial,Helvetica,sans-serif!important;
  font-weight:600!important;
}

/* cabe&#231;alhos das se&#231;&#245;es */
.titulo-secao h2,
.home-bloco-cab h2{
  font-family:Arial,Helvetica,sans-serif!important;
  font-weight:600!important;
}
.titulo-secao p,
.home-bloco-cab p{
  font-weight:400!important;
}

/* especificamente DESTAQUES */
#listaDestaques .card-destaque,
#listaDestaques .card-destaque *{
  font-family:Arial,Helvetica,sans-serif!important;
}
#listaDestaques .card-destaque .vaga-empresa,
#listaDestaques .card-destaque .vaga-meta,
#listaDestaques .card-destaque span{
  font-weight:400!important;
}
#listaDestaques .card-destaque .vaga-titulo,
#listaDestaques .card-destaque h3{
  font-weight:600!important;
}



/* =========================================================
   EMPREGAMAIS - TIPOGRAFIA PROFISSIONAL 2026
   Mant&#233;m TODOS os tamanhos existentes.
   Fam&#237;lia: Inter (fallback Arial)
========================================================= */
html,body,button,input,select,textarea,
h1,h2,h3,h4,h5,h6,p,span,a,div,label,strong,b,small,li{
  font-family:Inter,Arial,Helvetica,sans-serif!important;
}

/* Corpo e informa&#231;&#245;es: leitura limpa */
body,p,span,div,li,label,input,select,textarea{
  font-weight:400!important;
}

/* Hierarquia editorial */
h1{
  font-weight:700!important;
  letter-spacing:-.025em!important;
}
h2{
  font-weight:650!important;
  letter-spacing:-.018em!important;
}
h3{
  font-weight:600!important;
  letter-spacing:-.012em!important;
}
h4,h5,h6{
  font-weight:600!important;
}

/* &#202;nfase sem apar&#234;ncia pesada */
strong,b{
  font-weight:600!important;
}

/* Navega&#231;&#227;o */
header a,nav a,
.menu a,.nav a,
[class*="menu"] a{
  font-weight:500!important;
  letter-spacing:-.005em!important;
}

/* Bot&#245;es precisam de contraste, sem exagero */
button,.btn,
[class*="btn-"]{
  font-weight:600!important;
  letter-spacing:-.005em!important;
}

/* Formul&#225;rios */
label{
  font-weight:500!important;
}
input,select,textarea{
  font-weight:400!important;
}

/* T&#237;tulos de se&#231;&#245;es */
.titulo-secao h2,
.home-bloco-cab h2,
.dashboard-topo h1,
.page-header h1{
  font-weight:700!important;
  letter-spacing:-.022em!important;
}
.titulo-secao p,
.home-bloco-cab p,
.dashboard-topo p,
.page-header p{
  font-weight:400!important;
  letter-spacing:0!important;
}

/* Vagas */
.vaga-titulo,
.vaga-card h3,
.card-destaque h3{
  font-weight:650!important;
  letter-spacing:-.012em!important;
}
.vaga-empresa{
  font-weight:500!important;
}
.vaga-meta,
.vaga-card p,
.vaga-card span,
.card-destaque p,
.card-destaque span{
  font-weight:400!important;
  letter-spacing:0!important;
}

/* Sal&#225;rio: destaque visual moderado */
.vaga-salario,
.salario,
[class*="salario"]{
  font-weight:600!important;
  letter-spacing:-.005em!important;
}

/* Tags, badges e selos */
.tag,.badge,.selo,.vaga-tag,
[class*="badge"],[class*="selo"]{
  font-weight:500!important;
  letter-spacing:.01em!important;
}

/* Planos */
.plano-card-novo h2,
.plano-card h3{
  font-weight:700!important;
  letter-spacing:-.018em!important;
}
.plano-sub,
.plano-beneficios li{
  font-weight:400!important;
}
.plano-valor,
.plano-limite{
  font-weight:650!important;
}

/* Pain&#233;is */
.metrica strong{
  font-weight:700!important;
}
.metrica span,
.painel-sidebar-empresa span{
  font-weight:400!important;
}
.painel-sidebar-empresa strong{
  font-weight:600!important;
}

/* Login empresa/candidato */
#pagina-login-empresa .page-header h1,
#pagina-login-candidato .page-header h1{
  font-weight:700!important;
}
#pagina-login-empresa .grupo label,
#pagina-login-candidato .grupo label{
  font-weight:500!important;
}

/* Rodap&#233; e textos auxiliares */
footer,footer p,footer span,footer a,
.login-ajuda,.contato-ajuda,small{
  font-weight:400!important;
}

/* Corrige regras antigas de Arial que poderiam vencer a nova tipografia */
#listaDestaques .card-destaque,
#listaDestaques .card-destaque *{
  font-family:Inter,Arial,Helvetica,sans-serif!important;
}



/* =========================================================
   EMPREGAMAIS &#8212; SISTEMA VISUAL GLOBAL
   Padroniza&#231;&#227;o geral sem alterar os tamanhos de fonte atuais
========================================================= */
:root{
  --em-azul:#1769aa;
  --em-azul-escuro:#124d78;
  --em-azul-claro:#eef6fc;
  --em-texto:#172033;
  --em-texto-2:#536273;
  --em-texto-3:#7b8794;
  --em-fundo:#f5f8fb;
  --em-superficie:#ffffff;
  --em-borda:#dfe6ed;
  --em-borda-suave:#e9eef3;
  --em-verde:#168047;
  --em-amarelo:#a06c00;
  --em-vermelho:#b42318;

  --em-raio-sm:8px;
  --em-raio-md:11px;
  --em-raio-lg:15px;
  --em-raio-xl:18px;

  --em-sombra-sm:0 4px 14px rgba(15,47,72,.045);
  --em-sombra-md:0 10px 30px rgba(15,47,72,.07);

  --em-site:1240px;
  --em-conteudo:1120px;
  --em-form:760px;

  --em-esp-1:6px;
  --em-esp-2:10px;
  --em-esp-3:14px;
  --em-esp-4:18px;
  --em-esp-5:24px;
  --em-esp-6:32px;
  --em-esp-7:42px;
}

/* Base */
html,body{background:var(--em-fundo)!important;color:var(--em-texto)!important}
body{line-height:1.55}
p{color:var(--em-texto-2)}
small{color:var(--em-texto-3)}
a{transition:color .18s ease,background .18s ease,border-color .18s ease,opacity .18s ease}
hr{border:0;border-top:1px solid var(--em-borda-suave)}

/* Largura e respiro das p&#225;ginas */
.container,
.container-dashboard,
.page-header-inner,
.home-vagas-caixa,
.planos-pagina,
.detalhe-layout,
.empresas-contratando-inner{
  width:min(calc(100% - 48px),var(--em-site))!important;
  max-width:var(--em-site)!important;
  margin-left:auto!important;
  margin-right:auto!important;
}
.container-menor,
.formulario-container,
.publicar-container,
.login-container{
  width:min(calc(100% - 32px),var(--em-form))!important;
  margin-left:auto!important;
  margin-right:auto!important;
}

/* Cabe&#231;alhos internos */
.page-header{
  border-bottom:1px solid var(--em-borda)!important;
}
.page-header h1,
.dashboard-topo h1{
  color:var(--em-texto);
  margin-bottom:var(--em-esp-2)!important;
}
.page-header p,
.dashboard-topo p{
  color:var(--em-texto-2);
}
.voltar{
  border-radius:var(--em-raio-sm)!important;
}

/* Cards e superf&#237;cies &#8212; mesmo acabamento em todo portal */
.form-card,
.vaga-card,
.card-destaque,
.plano-card,
.plano-card-novo,
.metrica,
.candidatura-item,
.candidato-admin-card,
.publicacao-plano-atual,
.plano-publicacao-box,
.contato-candidatura-box,
.upgrade-plano-box,
.painel-uso-plano-em,
.recomendacoes-vaga,
.detalhe-card,
[class*="dashboard-card"],
[class*="painel-card"]{
  border-color:var(--em-borda)!important;
  border-radius:var(--em-raio-lg)!important;
  box-shadow:var(--em-sombra-sm)!important;
}

/* Formul&#225;rios */
.campo,
input[type="text"],
input[type="email"],
input[type="password"],
input[type="tel"],
input[type="number"],
input[type="url"],
input[type="search"],
select,
textarea{
  border:1px solid #cfd9e3!important;
  border-radius:var(--em-raio-md)!important;
  background:#fff!important;
  color:var(--em-texto)!important;
  box-shadow:none!important;
  transition:border-color .18s ease,box-shadow .18s ease!important;
}
.campo:focus,
input:focus,
select:focus,
textarea:focus{
  outline:none!important;
  border-color:var(--em-azul)!important;
  box-shadow:0 0 0 3px rgba(23,105,170,.10)!important;
}
label{color:#334155!important}
::placeholder{color:#9aa6b2!important;opacity:1}

/* Bot&#245;es */
.btn,
button[class*="btn"],
.btn-primary,
.btn-primario{
  border-radius:var(--em-raio-md)!important;
  transition:background .18s ease,border-color .18s ease,transform .18s ease,box-shadow .18s ease!important;
}
.btn-azul,
.btn-primary,
.btn-primario,
.btn-total{
  background:var(--em-azul)!important;
  border-color:var(--em-azul)!important;
  color:#fff!important;
  box-shadow:0 5px 14px rgba(23,105,170,.13)!important;
}
.btn-azul:hover,
.btn-primary:hover,
.btn-primario:hover,
.btn-total:hover{
  background:var(--em-azul-escuro)!important;
  border-color:var(--em-azul-escuro)!important;
  transform:translateY(-1px);
}
.btn-secondary,
.btn-secundario{
  background:#fff!important;
  color:var(--em-texto)!important;
  border:1px solid var(--em-borda)!important;
  box-shadow:none!important;
}

/* Tags, selos e informa&#231;&#245;es pequenas */
.tag,.badge,.selo,.vaga-tag,
[class*="vaga-tag"],
[class*="badge"]{
  border-radius:999px!important;
}
.vaga-meta span,
.vaga-tags span{
  border-color:#d9e5ef!important;
  background:#f6fafe!important;
}

/* Vagas */
.vaga-card,
.card-destaque{
  background:var(--em-superficie)!important;
}
.vaga-titulo{color:var(--em-texto)!important}
.vaga-empresa{color:#43546a!important}
.vaga-salario,
.salario,
[class*="salario"]{color:var(--em-verde)!important}
.vaga-card:hover{
  border-color:#cbd9e5!important;
  box-shadow:var(--em-sombra-md)!important;
}

/* Se&#231;&#245;es da home */
.titulo-secao,
.home-bloco-cab{
  margin-bottom:var(--em-esp-5)!important;
}
.titulo-secao h2,
.home-bloco-cab h2{
  color:var(--em-texto)!important;
}
.titulo-secao p,
.home-bloco-cab p{
  color:var(--em-texto-2)!important;
}

/* Planos */
.plano-card-novo{
  background:#fff!important;
}
.plano-card-novo.profissional{
  border-color:var(--em-azul)!important;
}
.plano-beneficios{
  border-color:var(--em-borda-suave)!important;
}
.plano-beneficios li{
  color:var(--em-texto-2)!important;
}

/* Pain&#233;is */
.metrica{
  background:#fff!important;
}
.metrica strong{color:var(--em-texto)!important}
.metrica span{color:var(--em-texto-3)!important}
.painel-side-nav button{
  border-radius:var(--em-raio-sm)!important;
}
.painel-side-nav button:hover{
  background:var(--em-azul-claro)!important;
}

/* Tabelas/listagens */
table{
  width:100%;
  border-collapse:separate;
  border-spacing:0;
}
th{
  color:#526174!important;
  background:#f8fafc!important;
}
th,td{
  border-color:var(--em-borda-suave)!important;
}

/* Divisores e &#225;reas auxiliares */
.login-ajuda,
.resumo-plano,
.planos-observacao{
  border-color:var(--em-borda-suave)!important;
}

/* Alertas por fun&#231;&#227;o */
.sucesso,[class*="sucesso"]{color:var(--em-verde)}
.erro,[class*="erro"]{color:var(--em-vermelho)}

/* Espa&#231;amento consistente em formul&#225;rios */
.form-card .grupo + .grupo{
  margin-top:var(--em-esp-4);
}

/* Evita sombras exageradas antigas */
.form-card{
  box-shadow:var(--em-sombra-md)!important;
}

/* Mobile */
@media(max-width:760px){
  .container,
  .container-dashboard,
  .page-header-inner,
  .home-vagas-caixa,
  .planos-pagina,
  .detalhe-layout,
  .empresas-contratando-inner{
    width:calc(100% - 24px)!important;
  }
  .container-menor,
  .formulario-container,
  .publicar-container,
  .login-container{
    width:calc(100% - 24px)!important;
  }
  .form-card,
  .vaga-card,
  .card-destaque,
  .plano-card-novo{
    border-radius:var(--em-raio-md)!important;
  }
}



/* =========================================================
   EMPREGAMAIS - BUSCA HOME ESTILO REFERENCIA
   Uma barra branca: O qu&#234;? | Onde? | ACHAR VAGAS
========================================================= */
#pagina-home .hero form,
#pagina-home .busca-form,
#pagina-home .hero-busca,
#pagina-home [class*="busca"] form{
  display:grid!important;
  grid-template-columns:minmax(0,1.15fr) minmax(0,.95fr) 190px!important;
  align-items:stretch!important;
  gap:0!important;
  width:min(100%,1000px)!important;
  margin:24px auto 0!important;
  padding:7px!important;
  border:0!important;
  border-radius:20px!important;
  background:#fff!important;
  box-shadow:0 10px 28px rgba(0,34,75,.13)!important;
  overflow:hidden!important;
}
#pagina-home .hero form .grupo,
#pagina-home .busca-form .grupo,
#pagina-home .hero-busca .grupo,
#pagina-home [class*="busca"] form .grupo{
  position:relative!important;
  margin:0!important;
  padding:6px 22px!important;
  background:#fff!important;
}
#pagina-home .hero form .grupo:first-of-type,
#pagina-home .busca-form .grupo:first-of-type,
#pagina-home .hero-busca .grupo:first-of-type{
  border-right:1px solid #d5dde6!important;
}
#pagina-home .hero form label,
#pagina-home .busca-form label,
#pagina-home .hero-busca label{
  display:block!important;
  margin:0 0 2px!important;
  color:#153d68!important;
  font-weight:600!important;
}
#pagina-home .hero form input,
#pagina-home .busca-form input,
#pagina-home .hero-busca input,
#pagina-home [class*="busca"] form input{
  width:100%!important;
  height:27px!important;
  min-height:27px!important;
  padding:0!important;
  border:0!important;
  border-radius:0!important;
  background:transparent!important;
  box-shadow:none!important;
  color:#172033!important;
  font-weight:400!important;
}
#pagina-home .hero form input:focus,
#pagina-home .busca-form input:focus,
#pagina-home .hero-busca input:focus{
  border:0!important;
  outline:0!important;
  box-shadow:none!important;
}
#pagina-home .hero form input::placeholder,
#pagina-home .busca-form input::placeholder,
#pagina-home .hero-busca input::placeholder{
  color:#aab4c0!important;
  font-style:italic!important;
}
#pagina-home .hero form button[type="submit"],
#pagina-home .busca-form button,
#pagina-home .hero-busca button,
#pagina-home [class*="busca"] form button[type="submit"]{
  align-self:stretch!important;
  width:100%!important;
  min-height:56px!important;
  margin:0!important;
  padding:0 20px!important;
  border:0!important;
  border-radius:999px!important;
  background:#174784!important;
  color:#fff!important;
  box-shadow:none!important;
  font-weight:700!important;
  text-transform:uppercase!important;
  white-space:nowrap!important;
}
#pagina-home .hero form button[type="submit"]:hover,
#pagina-home .busca-form button:hover,
#pagina-home .hero-busca button:hover{
  background:#123a70!important;
  transform:none!important;
}
@media(max-width:760px){
  #pagina-home .hero form,
  #pagina-home .busca-form,
  #pagina-home .hero-busca,
  #pagina-home [class*="busca"] form{
    grid-template-columns:1fr!important;
    width:100%!important;
    padding:8px!important;
    border-radius:16px!important;
  }
  #pagina-home .hero form .grupo,
  #pagina-home .busca-form .grupo,
  #pagina-home .hero-busca .grupo{
    padding:10px 14px!important;
  }
  #pagina-home .hero form .grupo:first-of-type,
  #pagina-home .busca-form .grupo:first-of-type,
  #pagina-home .hero-busca .grupo:first-of-type{
    border-right:0!important;
    border-bottom:1px solid #e2e8f0!important;
  }
  #pagina-home .hero form button[type="submit"],
  #pagina-home .busca-form button,
  #pagina-home .hero-busca button{
    min-height:48px!important;
    margin-top:5px!important;
  }
}



/* PERFIL PUBLICO + CONFIANCA E SEGURANCA */
.empresa-publica-hero-em{display:flex;align-items:center;gap:20px;padding-top:10px}
.empresa-publica-logo-em{width:82px;height:82px;flex:0 0 82px;display:flex;align-items:center;justify-content:center;overflow:hidden;border:1px solid #dce5ed;border-radius:16px;background:#fff;color:#1769aa;font-size:25px;font-weight:700;box-shadow:0 8px 24px rgba(15,47,72,.08)}
.empresa-publica-logo-em img{width:100%;height:100%;object-fit:contain}
.empresa-publica-selo-em{display:inline-flex;margin-bottom:7px;padding:5px 9px;border-radius:999px;background:#eaf7ef;color:#167347;font-size:10px;font-weight:600}
.empresa-publica-main-em{width:min(calc(100% - 48px),1120px);margin:32px auto 65px}
.empresa-publica-box-em{margin-bottom:16px;padding:24px;border:1px solid #dfe6ed;border-radius:15px;background:#fff;box-shadow:0 4px 14px rgba(15,47,72,.045)}
.empresa-publica-box-em h2{margin:0 0 10px!important;font-weight:650!important}
.empresa-publica-box-em p{margin:0!important;line-height:1.7!important;font-weight:400!important}
.empresa-publica-titulo-em{display:flex;justify-content:space-between;gap:15px;align-items:flex-end;margin-bottom:18px}
.empresa-publica-vagas-em{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
.empresa-publica-vagas-em .vaga-card{height:100%}
.empresa-link-em{cursor:pointer!important;color:#1769aa!important;text-decoration:none!important}
.empresa-link-em:hover{text-decoration:underline!important}
.seguranca-vaga-em{margin:18px 0;padding:15px 17px;border:1px solid #dce8f1;border-radius:12px;background:#f7fbfe}
.seguranca-vaga-top-em{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:8px}
.seguranca-chip-em{display:inline-flex;align-items:center;gap:5px;padding:5px 8px;border-radius:999px;background:#eaf7ef;color:#167347;font-size:10px;font-weight:600}
.seguranca-data-em{color:#718096;font-size:11px;font-weight:400}
.seguranca-vaga-em p{margin:0!important;color:#526174!important;font-size:11px!important;line-height:1.55!important;font-weight:400!important}
.seguranca-vaga-em a{color:#1769aa!important;font-weight:500!important}
@media(max-width:700px){.empresa-publica-main-em{width:calc(100% - 24px);margin-top:20px}.empresa-publica-vagas-em{grid-template-columns:1fr}.empresa-publica-hero-em{align-items:flex-start}.empresa-publica-logo-em{width:66px;height:66px;flex-basis:66px}}



/* EMPREGAMAIS - PERFIL PUBLICO: DADOS REAIS DA EMPRESA CADASTRADA */
.empresa-link-cadastro-em{cursor:pointer!important;color:#1769aa!important}
.empresa-link-cadastro-em:hover{text-decoration:underline!important}
.empresa-publica-status-cadastro-em{
 display:inline-flex;align-items:center;gap:5px;margin-top:7px;padding:5px 9px;
 border-radius:999px;background:#f1f6fa;color:#526174;font-size:10px;font-weight:500
}
.empresa-publica-status-cadastro-em.verificada{background:#eaf7ef;color:#167347}



/* EMPREGAMAIS - CLIQUE SOMENTE EM EMPRESA VERIFICADA E COM PERFIL COMPLETO */
.empresa-sem-perfil-publico-em{
  cursor:default!important;
  color:inherit!important;
  text-decoration:none!important;
}
.empresa-sem-perfil-publico-em:hover{
  text-decoration:none!important;
}



/* VAGA CONFIDENCIAL - IMPLEMENTACAO ESTAVEL */
.vaga-confidencial-box-em{margin:20px 0;padding:18px;border:1px solid #dfe6ed;border-radius:13px;background:#fbfdff}
.vaga-confidencial-topo-em{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:12px}
.vaga-confidencial-topo-em h3{margin:0 0 4px!important;font-size:16px!important;font-weight:600!important}
.vaga-confidencial-topo-em p{margin:0!important;color:#667085!important;font-size:11px!important}
.vaga-confidencial-topo-em>span{padding:5px 8px;border-radius:999px;background:#eef6fc;color:#1769aa;font-size:9px;font-weight:600;white-space:nowrap}
.vaga-confidencial-check-em{display:flex;align-items:center;gap:9px;padding:12px;border:1px solid #e3e9ee;border-radius:10px;background:#fff;cursor:pointer}
.vaga-confidencial-check-em b{font-size:12px;font-weight:600}
.vaga-confidencial-check-em.bloqueado{opacity:.55;cursor:not-allowed}
.vaga-confidencial-msg-em{margin:8px 0 0!important;color:#667085!important;font-size:10px!important}
.vaga-confidencial-publica-em{display:inline-flex;margin-top:5px;padding:4px 7px;border-radius:999px;background:#f2f4f7;color:#475467;font-size:9px;font-weight:600}



/* =========================================================
   EMPREGAMAIS &#8212; PLANOS 2026 | LAYOUT PROFISSIONAL
========================================================= */
#planosOficiaisEmpregaMais{
  background:
    radial-gradient(circle at 50% 0,rgba(23,105,170,.08),transparent 34%),
    linear-gradient(180deg,#f7fafe 0%,#f3f6fa 100%);
  border-top:1px solid #e5ebf1;
}
#planosOficiaisEmpregaMais .planos-novos-em{
  max-width:1220px;
  padding:54px 24px 64px;
}
#planosOficiaisEmpregaMais .planos-novos-cab-em{
  max-width:720px;
  margin:0 auto 34px;
}
#planosOficiaisEmpregaMais .planos-novos-cab-em:before{
  content:"PLANOS PARA EMPRESAS";
  display:inline-flex;
  margin-bottom:11px;
  padding:6px 10px;
  border:1px solid #d5e6f4;
  border-radius:999px;
  background:#edf6fd;
  color:#1769aa;
  font-size:9px;
  font-weight:700;
  letter-spacing:.08em;
}
#planosOficiaisEmpregaMais .planos-novos-cab-em h2{
  font-size:31px;
  font-weight:700;
  letter-spacing:-.035em;
  color:#172033;
}
#planosOficiaisEmpregaMais .planos-novos-cab-em p{
  margin-top:10px;
  color:#667085;
  font-size:13px;
  line-height:1.65;
}
#planosOficiaisEmpregaMais .planos-grid-novos-em{
  gap:16px;
  align-items:stretch;
}
#planosOficiaisEmpregaMais .plano-card-novo-em{
  min-width:0;
  padding:25px 20px 20px;
  border:1px solid #dce4ec;
  border-radius:18px;
  box-shadow:0 8px 28px rgba(16,24,40,.055);
  transition:transform .2s ease,border-color .2s ease,box-shadow .2s ease;
}
#planosOficiaisEmpregaMais .plano-card-novo-em:hover{
  transform:translateY(-4px);
  border-color:#b8d3e7;
  box-shadow:0 16px 38px rgba(16,24,40,.09);
}
#planosOficiaisEmpregaMais .plano-card-novo-em.plano-recomendado-em{
  border:2px solid #1769aa;
  box-shadow:0 14px 38px rgba(23,105,170,.13);
}
#planosOficiaisEmpregaMais .plano-selo-novo-em{
  top:-13px;
  padding:6px 12px;
  background:#1769aa;
  font-size:9px;
  font-weight:700;
  box-shadow:0 5px 14px rgba(23,105,170,.22);
}
#planosOficiaisEmpregaMais .plano-nome-novo-em{
  font-size:18px;
  font-weight:600;
  color:#172033;
}
#planosOficiaisEmpregaMais .plano-periodo-novo-em{
  margin-top:5px;
  font-size:10px;
  color:#8a96a6;
}
#planosOficiaisEmpregaMais .plano-preco-novo-em{
  margin:19px 0 5px;
  color:#1769aa;
  font-size:29px;
  line-height:1.05;
  font-weight:600;
  letter-spacing:-.03em;
}
#planosOficiaisEmpregaMais .plano-vagas-novo-em{
  min-height:30px;
  margin-bottom:13px;
  color:#344054;
  font-size:10.5px;
  font-weight:500;
}
#planosOficiaisEmpregaMais .plano-recursos-novo-em{
  gap:10px;
  padding-top:17px;
  border-top:1px solid #edf1f5;
}
#planosOficiaisEmpregaMais .plano-recurso-novo-em{
  gap:8px;
  color:#526174;
  font-size:10.5px;
  line-height:1.45;
}
#planosOficiaisEmpregaMais .plano-recurso-novo-em b{
  flex:none;
  width:15px;
  color:#1769aa;
  font-weight:700;
}
#planosOficiaisEmpregaMais .plano-recurso-novo-em span{
  min-width:0;
}
#planosOficiaisEmpregaMais .plano-recurso-novo-em.nao-em{
  color:#98a2b3;
}
#planosOficiaisEmpregaMais .plano-recurso-novo-em.especial-em{
  margin:2px -7px;
  padding:10px 9px;
  border:1px solid #cfe4f4;
  border-radius:10px;
  background:#f1f8fd;
  color:#174f78;
}
#planosOficiaisEmpregaMais .plano-recurso-novo-em.especial-em b{
  color:#138a4b;
}
#planosOficiaisEmpregaMais .plano-recurso-novo-em.especial-em span{
  font-weight:600;
}
#planosOficiaisEmpregaMais .plano-recurso-novo-em.especial-em small{
  display:block;
  margin-top:5px;
  color:#667085;
  font-size:9px;
  line-height:1.5;
  font-weight:400;
}
#planosOficiaisEmpregaMais .plano-btn-novo-em{
  min-height:43px;
  margin-top:auto;
  border-radius:10px;
  font-size:11px;
  font-weight:600;
  transition:.18s;
}
#planosOficiaisEmpregaMais .plano-btn-novo-em:hover{
  transform:translateY(-1px);
  background:#f1f7fc;
}
#planosOficiaisEmpregaMais .plano-recomendado-em .plano-btn-novo-em:hover{
  background:#125b93;
}
#planosOficiaisEmpregaMais .planos-nota-nova-em{
  max-width:760px;
  margin-top:24px;
  padding-top:18px;
  border-top:1px solid #dfe6ed;
  color:#7b8794;
  line-height:1.6;
}
@media(max-width:950px){
  #planosOficiaisEmpregaMais .planos-grid-novos-em{grid-template-columns:repeat(2,1fr);}
}
@media(max-width:580px){
  #planosOficiaisEmpregaMais .planos-novos-em{padding:40px 14px 48px;}
  #planosOficiaisEmpregaMais .planos-grid-novos-em{grid-template-columns:1fr;}
  #planosOficiaisEmpregaMais .planos-novos-cab-em h2{font-size:25px;}
  #planosOficiaisEmpregaMais .plano-card-novo-em{padding:23px 18px 19px;}
}



/* =========================================================
   ADMIN &#8212; ABA PUBLICAR VAGA
========================================================= */
.admin-nav-profissional-em{display:flex;gap:8px;margin:0 0 22px;padding:6px;border:1px solid #dfe6ed;border-radius:12px;background:#fff;width:max-content;max-width:100%}
.admin-nav-profissional-em button{border:0;border-radius:8px;background:transparent;color:#526174;padding:10px 15px;font:600 11px Inter,Arial,sans-serif;cursor:pointer}
.admin-nav-profissional-em button.ativo{background:#111827;color:#fff}
.admin-publicacao-identidade-em{margin:0 0 22px;padding:20px;border:1px solid #d9e2ea;border-radius:14px;background:linear-gradient(135deg,#fbfcfe,#f3f6f9)}
.admin-publicacao-titulo-em{margin-bottom:17px;padding-bottom:15px;border-bottom:1px solid #e2e8ee}
.admin-publicacao-titulo-em span{display:inline-flex;margin-bottom:6px;padding:5px 8px;border-radius:999px;background:#111827;color:#fff;font-size:9px;font-weight:700;letter-spacing:.06em}
.admin-publicacao-titulo-em h2{margin:0 0 5px!important;font-size:18px!important;font-weight:650!important}
.admin-publicacao-titulo-em p{margin:0!important;color:#667085!important;font-size:11px!important;line-height:1.55!important}
.admin-opcoes-publicacao-em{display:flex;flex-direction:column;gap:8px}
.admin-check-publicacao-em{display:flex!important;align-items:center;gap:8px;padding:10px 11px;border:1px solid #dfe6ed;border-radius:9px;background:#fff;cursor:pointer}
.admin-check-publicacao-em input{width:16px;height:16px}
.admin-check-publicacao-em span{font-size:11px;font-weight:500}
body.admin-publicando-em #pagina-publicar .page-header{border-top-color:#111827}
body.admin-publicando-em #pagina-publicar .publicacao-plano-atual{display:none!important}
body.admin-publicando-em #pagina-publicar .contato-upgrade-aviso{display:none!important}
body.admin-publicando-em #pagina-publicar .vaga-confidencial-topo-em>span{background:#111827;color:#fff}
@media(max-width:700px){.admin-nav-profissional-em{width:100%}.admin-nav-profissional-em button{flex:1}.admin-publicacao-identidade-em{padding:16px}}



/* =========================================================
   ADMIN &#8212; CENTRAL DE EMPRESAS
========================================================= */
.admin-empresas-central-em{
  margin:0 0 25px;
  padding:24px;
  background:#fff;
  border:1px solid #dfe6ed;
  border-radius:17px;
  box-shadow:0 7px 24px rgba(16,24,40,.04);
}
.admin-empresas-cab-em{
  display:flex;align-items:flex-start;justify-content:space-between;gap:20px;
  padding-bottom:19px;border-bottom:1px solid #edf0f3;
}
.admin-mini-label-em{
  display:inline-flex;margin-bottom:7px;padding:5px 8px;border-radius:999px;
  background:#eef4f8;color:#173f63;font-size:9px;font-weight:700;letter-spacing:.07em;
}
.admin-empresas-cab-em h2{margin:0 0 5px;font-size:20px;font-weight:650}
.admin-empresas-cab-em p{margin:0;color:#667085;font-size:11px;line-height:1.55}
.admin-empresas-resumo-em{
  min-width:78px;padding:10px 13px;border:1px solid #e1e7ed;border-radius:11px;
  background:#f8fafc;text-align:center
}
.admin-empresas-resumo-em strong{display:block;color:#173f63;font-size:20px;font-weight:650}
.admin-empresas-resumo-em span{color:#7b8794;font-size:9px}
.admin-empresas-filtros-em{
  display:flex;align-items:center;justify-content:space-between;gap:15px;margin:19px 0 17px;
}
.admin-empresas-tabs-em{display:flex;gap:5px;flex-wrap:wrap}
.admin-empresas-tabs-em button{
  border:1px solid #dfe5eb;border-radius:8px;background:#fff;color:#526174;
  padding:8px 11px;font:600 10px Inter,Arial,sans-serif;cursor:pointer
}
.admin-empresas-tabs-em button.ativo{border-color:#173f63;background:#173f63;color:#fff}
.admin-empresas-tabs-em button span{
  display:inline-flex;min-width:18px;height:18px;margin-left:4px;align-items:center;justify-content:center;
  border-radius:999px;background:#fff2f0;color:#b42318;font-size:9px
}
.admin-empresas-tabs-em button.ativo span{background:rgba(255,255,255,.16);color:#fff}
.admin-busca-empresa-em{width:220px;padding:9px 11px;font-size:11px}
.admin-empresas-grid-em{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.admin-empresa-box-em{
  position:relative;min-height:130px;padding:17px;border:1px solid #dfe5eb;border-radius:13px;
  background:#fff;cursor:pointer;transition:.18s
}
.admin-empresa-box-em:hover{transform:translateY(-2px);border-color:#b9d0e0;box-shadow:0 9px 22px rgba(16,24,40,.065)}
.admin-empresa-box-em.tem-pendencia-em{
  border-color:#efc36d;background:linear-gradient(180deg,#fffdf8,#fff);
  box-shadow:inset 3px 0 0 #e4a11b
}
.admin-empresa-box-top-em{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}
.admin-empresa-avatar-em{
  width:38px;height:38px;display:flex;align-items:center;justify-content:center;flex:none;
  border-radius:10px;background:#edf4f9;color:#173f63;font-size:13px;font-weight:700
}
.admin-empresa-identidade-em{flex:1;min-width:0}
.admin-empresa-identidade-em h3{
  margin:1px 0 4px;font-size:13px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis
}
.admin-empresa-identidade-em small{color:#8a96a6;font-size:9px}
.admin-pendente-selo-em{
  display:inline-flex;align-items:center;gap:4px;padding:5px 7px;border-radius:999px;
  background:#fff3d6;color:#946200;font-size:8.5px;font-weight:700;white-space:nowrap
}
.admin-empresa-box-meta-em{
  display:flex;align-items:center;justify-content:space-between;gap:10px;
  margin-top:17px;padding-top:13px;border-top:1px solid #edf0f3
}
.admin-empresa-box-meta-em span{color:#667085;font-size:9.5px}
.admin-empresa-box-meta-em b{color:#173f63;font-size:10px;font-weight:650}
.admin-vagas-empresa-selecionada-em{
  margin:0 0 15px;padding:18px 20px;border:1px solid #dce4eb;border-radius:14px;background:#f8fafc
}
.admin-voltar-empresas-em{
  margin:0 0 8px;padding:0;border:0;background:none;color:#1769aa;font:600 10px Inter,Arial,sans-serif;cursor:pointer
}
.admin-vagas-empresa-cab-em h2{margin:0 0 4px;font-size:19px}
.admin-vagas-empresa-cab-em p{margin:0;color:#667085;font-size:10px}
.admin-empresa-vazio-em{
  grid-column:1/-1;padding:28px;border:1px dashed #d7dfe7;border-radius:12px;
  color:#7b8794;text-align:center;font-size:11px
}
@media(max-width:950px){.admin-empresas-grid-em{grid-template-columns:repeat(2,1fr)}}
@media(max-width:650px){
