  .admin-empresas-cab-em,.admin-empresas-filtros-em{flex-direction:column}
  .admin-busca-empresa-em{width:100%}
  .admin-empresas-grid-em{grid-template-columns:1fr}
}



/* =========================================================
   PAINEL DA EMPRESA &#8212; ORGANIZA&#199;&#195;O PROFISSIONAL
========================================================= */
#pagina-painel-empresa{background:#f6f8fb}
#pagina-painel-empresa .container-dashboard{max-width:1220px;padding-top:32px}
.empresa-painel-boasvindas-em{
 display:flex;align-items:center;justify-content:space-between;gap:22px;
 margin-bottom:18px;padding:24px 26px;border:1px solid #dfe6ed;border-radius:17px;
 background:#fff;box-shadow:0 6px 22px rgba(16,24,40,.035)
}
.empresa-painel-eyebrow-em{
