 border:1px solid #dfe5eb;border-radius:12px;background:rgba(255,255,255,.96);
 box-shadow:0 5px 18px rgba(16,24,40,.035);backdrop-filter:blur(10px)
}
.empresa-painel-nav-em button{
 flex:1;border:0;border-radius:8px;background:transparent;color:#667085;
 padding:10px 12px;font:600 10.5px Inter,Arial,sans-serif;cursor:pointer;white-space:nowrap
}
.empresa-painel-nav-em button:hover{background:#f5f8fb;color:#173f63}
.empresa-painel-nav-em button.ativo{background:#173f63;color:#fff}
.empresa-acoes-necessarias-em{
 display:flex;align-items:flex-start;gap:11px;margin:0 0 18px;padding:14px 16px;
 border:1px solid #f0d59d;border-radius:12px;background:#fffbf2;color:#715300
}
.empresa-acoes-icone-em{
 width:26px;height:26px;display:flex;align-items:center;justify-content:center;flex:none;
 border-radius:8px;background:#f8e7b9;font-weight:700
}
.empresa-acoes-necessarias-em strong{display:block;margin-bottom:3px;font-size:11px}
#empresaA&#231;&#245;esNecessariasTextoEM{font-size:10px;line-height:1.55}
#pagina-painel-empresa .metricas{gap:12px}
#pagina-painel-empresa .metrica{
 padding:18px;border-color:#dfe6ed;border-radius:13px;box-shadow:0 4px 15px rgba(16,24,40,.025)
}
#pagina-painel-empresa .metrica span{font-size:10px}
#pagina-painel-empresa .metrica strong{font-size:22px;font-weight:650}
#pagina-painel-empresa .painel-card,
#pagina-painel-empresa .form-card{
 border-color:#dfe6ed;border-radius:15px;box-shadow:0 5px 18px rgba(16,24,40,.03)
}
#pagina-painel-empresa .dashboard-topo:first-of-type{display:none}
.empresa-aba-oculta-em{display:none!important}
.empresa-secao-titulo-em{
 margin:0 0 13px;padding:0 2px;color:#344054;font-size:11px;font-weight:650
}
@media(max-width:720px){
 .empresa-painel-boasvindas-em{align-items:flex-start;flex-direction:column;padding:19px 17px}
 .empresa-painel-publicar-em{width:100%}
