/* EMPRESA &#8212; ABA DE VERIFICA&#199;&#195;O */
.empresa-verificacao-nav-status-em{margin-left:4px;color:#98a2b3;font-size:15px;line-height:0}
.empresa-verificacao-painel-em{margin-bottom:20px;padding:24px;border:1px solid #dfe6ed;border-radius:17px;background:#fff;box-shadow:0 6px 22px rgba(16,24,40,.035)}
