.empresa-verificacao-icone-em{width:48px;height:48px;display:flex;align-items:center;justify-content:center;flex:none;border-radius:14px;background:#eaf5fc;color:#1769aa;font-size:21px;font-weight:700}
.empresa-verificacao-hero-em>div:nth-child(2){flex:1}
.empresa-verificacao-hero-em span{display:block;margin-bottom:5px;color:#1769aa;font-size:9px;font-weight:700;letter-spacing:.07em}
.empresa-verificacao-hero-em h2{margin:0 0 5px;font-size:19px;font-weight:650}
.empresa-verificacao-hero-em p{max-width:650px;margin:0;color:#667085;font-size:10.5px;line-height:1.6}
.empresa-verificacao-status-em{flex:none;padding:7px 10px;border-radius:999px;background:#f2f4f7;color:#667085;font-size:9px;font-weight:700}
.empresa-verificacao-status-em.pendente-em{background:#fff8df;color:#956900}
.empresa-verificacao-status-em.verificada-em{background:#ecfdf3;color:#138a4b}
.empresa-verificacao-grid-em{display:grid;grid-template-columns:1.15fr .85fr;gap:18px;margin-top:20px}
.empresa-verificacao-beneficios-em,.empresa-verificacao-acao-em{padding:19px;border:1px solid #e3e8ee;border-radius:13px;background:#fbfcfd}
.empresa-verificacao-beneficios-em h3{margin:0 0 14px;font-size:13px;font-weight:650}
.empresa-verificacao-beneficios-em>div{display:flex;gap:8px;margin:10px 0;color:#526174;font-size:10.5px}
.empresa-verificacao-beneficios-em b{color:#138a4b}
.empresa-verificacao-acao-em{display:flex;flex-direction:column;justify-content:center}
.empresa-verificacao-acao-em>span{margin-bottom:13px;color:#344054;font-size:11px;line-height:1.55}
.empresa-verificacao-acao-em small{display:block;margin-top:10px;color:#8a96a6;font-size:9px;line-height:1.5;text-align:center}
@media(max-width:700px){.empresa-verificacao-hero-em{align-items:flex-start;flex-wrap:wrap}.empresa-verificacao-status-em{margin-left:64px}.empresa-verificacao-grid-em{grid-template-columns:1fr}.empresa-verificacao-painel-em{padding:18px 15px}}



