/* =====================================================
   CANDIDATO &#8212; PERFIL PROFISSIONAL E ADER&#202;NCIA
===================================================== */
.painel-card-aderencia-em{position:relative;overflow:hidden}
.painel-card-aderencia-em:before{
 content:'';position:absolute;left:0;top:0;bottom:0;width:3px;background:#159447
}
.perfil-profissional-status-em{
 display:inline-flex;margin:4px 0 14px;padding:5px 8px;border-radius:999px;
 background:#f2f4f7;color:#667085;font-size:9px;font-weight:600
}
.perfil-profissional-status-em.completo{background:#eaf7ef;color:#137a3f}
.perfil-profissional-form-em{
 margin:4px 0 22px;padding:19px;border:1px solid #dfe7ee;border-radius:14px;background:#fbfcfd
}
.perfil-profissional-form-cab-em{margin-bottom:17px;padding-bottom:14px;border-bottom:1px solid #e6ebf0}
.perfil-profissional-form-cab-em span{
 display:block;margin-bottom:5px;color:#159447;font-size:9px;font-weight:700;letter-spacing:.09em
}
.perfil-profissional-form-cab-em h3{margin:0 0 5px;color:#172033;font-size:15px;font-weight:650}
.perfil-profissional-form-cab-em p{margin:0;color:#667085;font-size:10px;line-height:1.55}
.perfil-ajuda-em{display:block;margin-top:6px;color:#7b8794;font-size:9px;line-height:1.45}

.aderencia-vaga-em{
 margin:18px 0 14px;padding:19px;border:1px solid #dfe7ee;border-radius:14px;background:#fff
}
.aderencia-vaga-cab-em{display:flex;align-items:flex-end;justify-content:space-between;gap:16px}
.aderencia-vaga-cab-em span{
 display:block;margin-bottom:4px;color:#667085;font-size:8.5px;font-weight:700;letter-spacing:.09em
}
.aderencia-vaga-cab-em h3{margin:0;color:#172033;font-size:16px;font-weight:650}
.aderencia-vaga-cab-em strong{color:#159447;font-size:25px;font-weight:700;letter-spacing:-.04em}
.aderencia-barra-em{
 width:100%;height:8px;margin:14px 0 12px;overflow:hidden;border-radius:999px;background:#edf1f4
}
.aderencia-barra-em i{
 display:block;width:0;height:100%;border-radius:999px;background:#159447;transition:width .45s ease
}
.aderencia-resumo-em{margin:0 0 12px;color:#526174;font-size:10.5px;line-height:1.55}
.aderencia-criterios-em{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:12px}
.aderencia-criterio-em{
 display:flex;align-items:center;gap:7px;padding:8px 9px;border:1px solid #e7ebef;
 border-radius:9px;background:#fbfcfd;color:#526174;font-size:9.5px
}
.aderencia-criterio-em i{
 width:18px;height:18px;display:flex;align-items:center;justify-content:center;flex:none;
 border-radius:999px;background:#eaf7ef;color:#159447;font-style:normal;font-size:9px;font-weight:700
}
.aderencia-criterio-em.nao i{background:#f2f4f7;color:#98a2b3}
.aderencia-perfil-btn-em{margin-top:13px}
.aderencia-aviso-em{
 display:block;margin-top:12px;padding-top:11px;border-top:1px solid #edf0f2;
 color:#8a94a3;font-size:8.7px;line-height:1.5
}
@media(max-width:600px){
 .perfil-profissional-form-em,.aderencia-vaga-em{padding:15px}
 .aderencia-criterios-em{grid-template-columns:1fr}
 .aderencia-vaga-cab-em strong{font-size:22px}
}



.perfil-profissional-form-em{
 display:block!important;
 width:100%!important;
 margin:5px 0 22px!important;
 padding:20px!important;
 border:1px solid #cfe0d5!important;
 border-left:3px solid #159447!important;
 border-radius:13px!important;
 background:#fbfdfb!important;
}
.aderencia-explicacao-perfil-em{
 margin-top:16px;padding:13px 14px;border-radius:10px;background:#eef8f2;border:1px solid #d7ecdf
}
.aderencia-explicacao-perfil-em strong{display:block;margin-bottom:4px;color:#137a3f;font-size:10.5px;font-weight:700}
.aderencia-explicacao-perfil-em p{margin:0;color:#526174;font-size:9.5px;line-height:1.55}



/* DIST&#194;NCIA &#8212; UMA &#218;NICA EXIBI&#199;&#195;O PADRONIZADA */
.distancia-canonica-em{
 display:inline-flex!important;
 align-items:center!important;
 gap:4px!important;
 color:#526174!important;
 font-size:10px!important;
 font-weight:500!important;
}
.distancia-canonica-em strong{font-weight:600!important;color:#344054!important}

/* Oculta somente as representa&#231;&#245;es antigas de dist&#226;ncia criadas pelo tema. */
#pagina-vaga #vagaDistancia,
#pagina-vaga #vagaDistanciaBadge,
#pagina-vaga #distanciaVaga,
#pagina-vaga [class*='distancia-vaga']:not(.distancia-canonica-em),
.card-vaga [class*='distancia']:not(.distancia-canonica-em),
.card-destaque [class*='distancia']:not(.distancia-canonica-em){
 display:none!important;
}

/* Linha can&#244;nica na pr&#233;via */
.local-distancia-card-em{
 display:inline-flex!important;
 align-items:center!important;
 margin:0!important;
 padding:5px 9px!important;
 border:1px solid #d9e6f1!important;
 border-radius:999px!important;
 background:#f6faff!important;
 color:#526174!important;
 font-size:9.5px!important;
 line-height:1.2!important;
}

/* Linha can&#244;nica dentro da vaga */
#vagaLocalDistanciaCanonicaEM{
 display:block!important;
 margin-top:6px!important;
 color:#526174!important;
 font-size:10px!important;
 line-height:1.45!important;
}



/* =====================================================
   VAGA &#8212; AVALIA&#199;&#195;O DO PROCESSO SELETIVO NO CABE&#199;ALHO
===================================================== */
.avaliacao-empresa-vaga-em{
 margin-left:auto;
 display:none;
 align-items:center;
 gap:8px;
 flex:none;
 padding:7px 10px;
 border:1px solid #ead9a6;
 border-radius:10px;
 background:#fffdf6;
 cursor:pointer;
 transition:.18s ease;
}
.avaliacao-empresa-vaga-em:hover{transform:translateY(-1px);box-shadow:0 5px 14px rgba(16,24,40,.06)}
.avaliacao-empresa-vaga-em .estrela-em{color:#d99a00;font-size:15px;line-height:1}
.avaliacao-empresa-vaga-em .nota-em{color:#172033;font-size:12px;font-weight:700}
.avaliacao-empresa-vaga-em .qtd-em{color:#7b8794;font-size:9px;font-weight:500}
.avaliacao-empresa-vaga-em .rotulo-em{
 display:block;margin-top:1px;color:#8a94a3;font-size:7.8px;font-weight:500;white-space:nowrap
}
.avaliacao-cabecalho-linha-em{
 display:flex!important;align-items:flex-start!important;justify-content:space-between!important;gap:18px!important
}
@media(max-width:650px){
 .avaliacao-cabecalho-linha-em{flex-wrap:wrap!important}
 .avaliacao-empresa-vaga-em{margin-left:0}
 .avaliacao-empresa-vaga-em .rotulo-em{white-space:normal}
}



/* CENTRAL DE EMPRESAS &#8212; EXCLUSIVA DO PAINEL ADMIN */
#pagina-painel-empresa .admin-empresas-central-em,
#pagina-painel-empresa .admin-vagas-empresa-selecionada-em{
 display:none!important;
}
#pagina-painel-admin .admin-empresas-central-em{
 display:block;
}



/* =========================================================
   PAINEL DO RECRUTADOR &#8212; CENTRAL DE GEST&#195;O 2026
========================================================= */
#pagina-painel-empresa .recrutador-central-em{
 margin:0 0 22px;padding:22px;border:1px solid #dfe7ee;border-radius:16px;background:#fff
}
.recrutador-topo-em{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:18px}
.recrutador-topo-em .eyebrow{color:#0874c9;font-size:8.5px;font-weight:700;letter-spacing:.1em}
.recrutador-topo-em h2{margin:5px 0 5px;color:#172033;font-size:22px;font-weight:650}
.recrutador-topo-em p{margin:0;color:#667085;font-size:10px}
.recrutador-plano-em{padding:9px 12px;border:1px solid #dce5ed;border-radius:10px;background:#f8fafc;text-align:right}
.recrutador-plano-em small{display:block;color:#98a2b3;font-size:8px}
.recrutador-plano-em strong{display:block;margin-top:2px;color:#172033;font-size:11px}
.recrutador-metricas-em{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:18px}
.recrutador-metrica-em{padding:14px;border:1px solid #e3e9ef;border-radius:12px;background:#fbfcfd}
.recrutador-metrica-em span{display:block;color:#7b8794;font-size:8.5px;font-weight:600}
.recrutador-metrica-em strong{display:block;margin-top:5px;color:#172033;font-size:20px;font-weight:650}
.recrutador-tabs-em{display:flex;gap:6px;overflow:auto;padding-top:14px;border-top:1px solid #e7ebef;scrollbar-width:none}
.recrutador-tabs-em::-webkit-scrollbar{display:none}
.recrutador-tab-em{
 flex:none;padding:9px 12px;border:1px solid #dce5ed;border-radius:9px;background:#fff;
 color:#526174;font-size:9.5px;font-weight:600;cursor:pointer
}
.recrutador-tab-em.ativo,.recrutador-tab-em:hover{border-color:#0874c9;background:#f1f8fd;color:#0874c9}
.recrutador-tab-em.publicar{margin-left:auto;background:#0874c9;border-color:#0874c9;color:#fff}

.recrutador-verificacao-em{
 display:none;margin:0 0 18px;padding:15px 16px;border:1px solid #efd89a;border-radius:12px;background:#fffaf0
}
.recrutador-verificacao-em.visivel{display:flex;align-items:center;justify-content:space-between;gap:16px}
.recrutador-verificacao-em strong{display:block;color:#694f00;font-size:11px}
.recrutador-verificacao-em p{margin:4px 0 0;color:#806d38;font-size:9px;line-height:1.45}
.recrutador-verificacao-em button{
 flex:none;padding:9px 12px;border:0;border-radius:8px;background:#172033;color:#fff;font-size:9px;font-weight:700;cursor:pointer
}

.recrutador-status-empresa-em{
 margin:0 0 18px;padding:17px;border:1px solid #dfe7ee;border-radius:13px;background:#fff
}
.recrutador-status-empresa-em h3{margin:0 0 12px;color:#172033;font-size:13px}
.recrutador-checks-em{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}
.recrutador-check-em{display:flex;align-items:center;gap:7px;color:#526174;font-size:9.5px}
.recrutador-check-em i{
 width:19px;height:19px;display:flex;align-items:center;justify-content:center;border-radius:999px;
 background:#eaf7ef;color:#159447;font-style:normal;font-size:9px;font-weight:700
}
.recrutador-check-em.pendente i{background:#fff4db;color:#a66d00}

@media(max-width:760px){
 .recrutador-topo-em{flex-direction:column}
 .recrutador-plano-em{text-align:left}
 .recrutador-metricas-em{grid-template-columns:repeat(2,1fr)}
 .recrutador-verificacao-em.visivel{align-items:flex-start;flex-direction:column}
 .recrutador-checks-em{grid-template-columns:1fr}
 .recrutador-tab-em.publicar{margin-left:0}
}



/* PAINEL RECRUTADOR &#8212; REMO&#199;&#195;O DE BLOCOS LEGADOS */
#pagina-painel-empresa .auto-aprovacao-box,
#pagina-painel-empresa .aprovacao-automatica-box,
#pagina-painel-empresa [class*='aprovacao-automatica'],
