}



/* ADMIN &#8212; LIBERA&#199;&#195;O MANUAL DE PLANOS */
.admin-liberar-plano-em{
 margin:0 0 20px;padding:20px;border:1px solid #dce5ed;border-radius:15px;background:#fff
}
.admin-liberar-plano-cab-em{margin-bottom:17px;padding-bottom:14px;border-bottom:1px solid #e7ebef}
.admin-liberar-plano-cab-em span{display:block;margin-bottom:5px;color:#0874c9;font-size:8.5px;font-weight:700;letter-spacing:.1em}
.admin-liberar-plano-cab-em h3{margin:0 0 5px;color:#172033;font-size:16px;font-weight:650}
.admin-liberar-plano-cab-em p{margin:0;color:#667085;font-size:10px}
.admin-liberar-plano-grid-em{display:grid;grid-template-columns:1.35fr 1fr;gap:12px}
.admin-plano-resumo-em{
 margin-top:13px;padding:12px 13px;border:1px solid #e4e9ee;border-radius:10px;background:#f8fafc;
 color:#526174;font-size:9.5px;line-height:1.5
}
.admin-plano-resumo-em strong{color:#172033}
.admin-plano-acoes-em{display:flex;gap:8px;flex-wrap:wrap;margin-top:13px}
.admin-plano-aviso-em{
 display:block;margin-top:13px;padding-top:11px;border-top:1px solid #edf0f2;color:#8a94a3;font-size:8.5px;line-height:1.5
}
@media(max-width:650px){.admin-liberar-plano-grid-em{grid-template-columns:1fr}}



/* =========================================================
   RECRUTADOR &#8212; MEU PERFIL / RESUMO DO PLANO
========================================================= */
.recrutador-meu-perfil-em{
 margin:0 0 20px;padding:20px;border:1px solid #dfe7ee;border-radius:15px;background:#fff
}
.recrutador-meu-perfil-cab-em{
 display:flex;align-items:flex-start;justify-content:space-between;gap:16px;
 margin-bottom:16px;padding-bottom:14px;border-bottom:1px solid #e7ebef
}
.recrutador-meu-perfil-cab-em span{
 display:block;margin-bottom:4px;color:#0874c9;font-size:8.5px;font-weight:700;letter-spacing:.1em
}
.recrutador-meu-perfil-cab-em h3{margin:0;color:#172033;font-size:17px;font-weight:650}
.recrutador-meu-perfil-cab-em p{margin:5px 0 0;color:#667085;font-size:9.5px}
.recrutador-perfil-plano-em{
