 font-size:9.5px;font-weight:700
}
.recrutador-perfil-metricas-em{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:16px}
.recrutador-perfil-metrica-em{padding:13px;border:1px solid #e3e9ef;border-radius:11px;background:#fbfcfd}
.recrutador-perfil-metrica-em small{display:block;color:#7b8794;font-size:8px;font-weight:600}
.recrutador-perfil-metrica-em strong{display:block;margin-top:5px;color:#172033;font-size:18px;font-weight:650}
.recrutador-uso-barra-em{height:7px;margin-top:9px;overflow:hidden;border-radius:999px;background:#e9eef2}
.recrutador-uso-barra-em i{display:block;height:100%;border-radius:999px;background:#0874c9}
.recrutador-destaques-lista-em h4{margin:0 0 9px;color:#172033;font-size:11px;font-weight:650}
.recrutador-destaque-item-em{
 display:flex;align-items:center;justify-content:space-between;gap:12px;
 padding:10px 11px;border-top:1px solid #edf0f2;color:#526174;font-size:9.5px
}
.recrutador-destaque-item-em:first-of-type{border-top:0}
.recrutador-destaque-item-em strong{color:#172033;font-weight:600}
.recrutador-destaque-item-em span{
 flex:none;padding:4px 7px;border:1px solid #efd58d;border-radius:999px;background:#fff9e8;
 color:#9a6a00;font-size:8px;font-weight:700
}
.recrutador-sem-destaques-em{
 padding:11px;border:1px dashed #dfe5ea;border-radius:9px;color:#8a94a3;font-size:9.5px
}
@media(max-width:650px){
 .recrutador-meu-perfil-cab-em{flex-direction:column}
 .recrutador-perfil-metricas-em{grid-template-columns:1fr}
}



/* =========================================================
   ADMIN &#8212; CENTRAL DE COMANDO DO PROPRIET&#193;RIO
========================================================= */
.admin-central-comando-em{margin:0 0 22px;padding:22px;border:1px solid #dce5ed;border-radius:17px;background:#fff}
.admin-central-cab-em{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;margin-bottom:19px;padding-bottom:16px;border-bottom:1px solid #e8edf1}
.admin-central-cab-em span,.admin-bloco-titulo-em span{display:block;margin-bottom:5px;color:#0874c9;font-size:8px;font-weight:700;letter-spacing:.11em}
.admin-central-cab-em h2{margin:0 0 5px;color:#172033;font-size:22px;font-weight:650}
.admin-central-cab-em p{max-width:650px;margin:0;color:#667085;font-size:10px;line-height:1.55}
.admin-central-status-em{padding:7px 10px;border-radius:999px;background:#eef7fd;color:#0874c9;font-size:8px;font-weight:700;letter-spacing:.08em}
.admin-central-metricas-em{display:grid;grid-template-columns:repeat(6,1fr);gap:9px;margin-bottom:18px}
.admin-central-metrica-em{padding:13px;border:1px solid #e3e9ef;border-radius:11px;background:#fafcfd}
.admin-central-metrica-em small{display:block;color:#7b8794;font-size:7.7px;font-weight:700}
.admin-central-metrica-em strong{display:block;margin:5px 0 2px;color:#172033;font-size:20px;font-weight:650}
.admin-central-metrica-em span{color:#98a2b3;font-size:8px}
.admin-central-grid-em{display:grid;grid-template-columns:1.15fr .85fr;gap:12px}
.admin-pendencias-em,.admin-acoes-rapidas-em{padding:16px;border:1px solid #e3e9ef;border-radius:12px;background:#fbfcfd}
.admin-bloco-titulo-em{display:flex;justify-content:space-between;align-items:flex-end;gap:10px;margin-bottom:11px}
.admin-bloco-titulo-em h3{margin:0;color:#172033;font-size:13px;font-weight:650}
.admin-bloco-titulo-em small{color:#98a2b3;font-size:8px}
.admin-pendencia-item-em{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 0;border-top:1px solid #e9edf1}
.admin-pendencia-item-em:first-child{border-top:0}
.admin-pendencia-item-em div{display:flex;align-items:center;gap:9px;color:#526174;font-size:9.5px}
.admin-pendencia-item-em i{width:22px;height:22px;display:flex;align-items:center;justify-content:center;border-radius:999px;background:#fff3d6;color:#a66d00;font-style:normal;font-weight:700}
.admin-pendencia-item-em strong{color:#172033;font-size:11px}
.admin-pendencias-vazio-em{padding:12px;border:1px dashed #dce5ed;border-radius:9px;color:#7b8794;font-size:9.5px}
.admin-acoes-grid-em{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.admin-acoes-grid-em button{display:flex;align-items:center;gap:9px;text-align:left;padding:11px;border:1px solid #dce5ed;border-radius:10px;background:#fff;color:#172033;cursor:pointer}
.admin-acoes-grid-em button:hover{border-color:#0874c9;background:#f4faff}
.admin-acoes-grid-em b{width:27px;height:27px;display:flex;align-items:center;justify-content:center;border-radius:8px;background:#eef7fd;color:#0874c9;font-size:13px}
.admin-acoes-grid-em span{font-size:9.5px;font-weight:650}
.admin-acoes-grid-em small{display:block;margin-top:2px;color:#8a94a3;font-size:7.8px;font-weight:400}
@media(max-width:1050px){.admin-central-metricas-em{grid-template-columns:repeat(3,1fr)}}
@media(max-width:720px){.admin-central-grid-em{grid-template-columns:1fr}.admin-central-metricas-em{grid-template-columns:repeat(2,1fr)}.admin-central-cab-em{flex-direction:column}}
@media(max-width:460px){.admin-acoes-grid-em{grid-template-columns:1fr}}



/* PERFIL PROFISSIONAL &#8212; CIDADE E SALVAMENTO EST&#193;VEL */
#perfilCidadeProfissionalEM{background-color:#fff}
.perfil-cidade-status-em{display:block;margin-top:5px;color:#7b8794;font-size:8px}



/* =====================================================
   PERFIL CANDIDATO &#8212; LAYOUT LIMPO E ALINHADO
===================================================== */
#pagina-perfil .container-menor{max-width:860px}
#pagina-perfil .form-card{padding:0;overflow:hidden}
#pagina-perfil form{display:block}
#pagina-perfil form > .grupo,
#pagina-perfil .perfil-candidato-secao-em{margin:0;padding:24px 28px;border-bottom:1px solid #e8edf2}
#pagina-perfil form > .grupo{padding-bottom:0;border-bottom:0}
#pagina-perfil .perfil-candidato-secao-cab-em{margin-bottom:20px}
#pagina-perfil .perfil-candidato-secao-cab-em > span{display:block;margin-bottom:6px;color:#1769aa;font-size:9px;font-weight:700;letter-spacing:.09em}
#pagina-perfil .perfil-candidato-secao-cab-em h3{margin:0 0 6px;font-size:18px;color:#182230}
#pagina-perfil .perfil-candidato-secao-cab-em p{margin:0;max-width:680px;color:#667085;font-size:12px;line-height:1.6}
#pagina-perfil .perfil-linha-em{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}
#pagina-perfil .perfil-linha-em .grupo{min-width:0}
#pagina-perfil .campo{min-height:45px}
#pagina-perfil textarea.campo{min-height:115px}
#pagina-perfil .perfil-ajuda-em{display:block;margin-top:6px;color:#98a2b3;font-size:10px;line-height:1.45}
#pagina-perfil .aderencia-explicacao-perfil-em{margin-top:5px;padding:14px 15px;border:1px solid #dce8f2;border-radius:10px;background:#f7fbfe}
#pagina-perfil .aderencia-explicacao-perfil-em strong{display:block;margin-bottom:4px;color:#0d4f82;font-size:11px}
#pagina-perfil .aderencia-explicacao-perfil-em p{margin:0;color:#667085;font-size:10.5px;line-height:1.55}
#pagina-perfil form > button[type='submit']{margin:22px 28px 28px;min-width:170px}
@media(max-width:680px){
 #pagina-perfil .form-card{border-radius:12px}
 #pagina-perfil form > .grupo,#pagina-perfil .perfil-candidato-secao-em{padding:20px 18px}
 #pagina-perfil .perfil-linha-em{grid-template-columns:1fr;gap:0}
 #pagina-perfil form > button[type='submit']{width:calc(100% - 36px);margin:20px 18px 24px}
}



/* POPUP PROFISSIONAL &#8212; PERFIL ATUALIZADO */
.popup-perfil-em{position:fixed;inset:0;z-index:999999;display:none;align-items:center;justify-content:center;padding:20px;background:rgba(15,23,42,.42);backdrop-filter:blur(3px)}
.popup-perfil-em.ativo{display:flex}
.popup-perfil-card-em{width:min(430px,100%);background:#fff;border:1px solid #e6ebf0;border-radius:18px;padding:30px 28px 24px;text-align:center;box-shadow:0 24px 70px rgba(15,23,42,.22);animation:popupPerfilEntradaEM .22s ease-out}
.popup-perfil-icone-em{width:58px;height:58px;margin:0 auto 17px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#edf8f2;color:#168653;font-size:27px;font-weight:700}
.popup-perfil-card-em h3{margin:0 0 8px;color:#182230;font-size:20px}
.popup-perfil-card-em p{margin:0 auto 22px;max-width:330px;color:#667085;font-size:13px;line-height:1.6}
.popup-perfil-ok-em{min-width:145px;padding:12px 22px;border:0;border-radius:9px;background:#1769aa;color:#fff;font-size:12px;font-weight:700;cursor:pointer}
.popup-perfil-ok-em:hover{filter:brightness(.94)}
@keyframes popupPerfilEntradaEM{from{opacity:0;transform:translateY(10px) scale(.98)}to{opacity:1;transform:translateY(0) scale(1)}}



/* ADMIN &#8212; FILA DE VERIFICA&#199;&#195;O DE EMPRESAS */
.admin-fila-verificacao-final-em{margin:0 0 16px}
.admin-verificacao-item-final-em{
 display:flex;align-items:center;justify-content:space-between;gap:15px;
 padding:14px 15px;margin-bottom:8px;border:1px solid #e1e8ee;border-radius:11px;background:#fff
}
.admin-verificacao-item-final-em span{display:block;margin-bottom:4px;color:#b7791f;font-size:8px;font-weight:700;letter-spacing:.08em}
.admin-verificacao-item-final-em strong{display:block;color:#172033;font-size:12px}
.admin-verificacao-item-final-em small{display:block;margin-top:4px;color:#7b8794;font-size:8.5px}
.admin-verificacao-item-final-em button{
 flex:none;padding:9px 12px;border:0;border-radius:8px;background:#1769aa;color:#fff;
 font-size:9px;font-weight:700;cursor:pointer
