function somenteNumeros(valor){
return String(
valor ||
""
).replace(
/\D/g,
""
);
}
function escaparTexto(texto){
return String(
texto ||
""
)
.replace(/&/g,"&amp;")
.replace(/</g,"&lt;")
.replace(/>/g,"&gt;")
.replace(/"/g,"&quot;")
.replace(/'/g,"&#039;");
}
function dataHoje(){
return new Date()
.toISOString()
.substring(
0,
10
);
}
function formatarData(data){
if(!data){
return "-";
}
var partes =
data.split("-");
if(
partes.length !==
3
){
return data;
}
return partes[2] +
"/" +
partes[1] +
"/" +
partes[0];
}
function calcularExpiracao(dias){
var data =
new Date();
data.setDate(
data.getDate() +
dias
);
return data
.toISOString()
.substring(
0,
10
);
}
function extrairSalarioNumero(texto){
if(!texto){
return 0;
}
var limpo =
texto
.replace(/\s/g,"")
.replace(/R\$/gi,"");
var resultado =
limpo.match(
/\d{1,3}(?:\.\d{3})*(?:,\d{1,2})?|\d+/
);
if(!resultado){
return 0;
}
return parseFloat(
resultado[0]
.replace(/\./g,"")
.replace(",",".")
) || 0;
}
function vagaExpirada(vaga){
if(
!vaga.expiraEm
){
return false;
}
var hoje =
new Date();
hoje.setHours(
0,
0,
0,
0
);
var fim =
new Date(
vaga.expiraEm +
"T23:59:59"
);
return fim < hoje;
}
function statusDaVaga(vaga){
if(
vaga.status ===
"encerrada"
){
return "encerrada";
}
if(
vagaExpirada(
vaga
)
){
return "expirada";
}
return "ativa";
}
function papelAtual(){
return sessionStorage.getItem(
"empregaMaisPapel"
) || "";
}
function candidatoEstaLogado(){
return (
papelAtual() ===
"candidato"
);
}
function empresaEstaLogada(){
return (
papelAtual() ===
"empresa"
);
}
function adminEstaLogado(){
return (
papelAtual() ===
"admin"
);
}
function limparSessao(){
sessionStorage.removeItem(
"empregaMaisPapel"
);
sessionStorage.removeItem(
"candidatoNome"
);
sessionStorage.removeItem(
"candidatoEmail"
);
sessionStorage.removeItem(
"candidatoTelefone"
);
sessionStorage.removeItem(
"empresaNome"
);
sessionStorage.removeItem(
"empresaCnpj"
);
sessionStorage.removeItem(
"empresaEmail"
);
}
async function sairTodasContas(){
var papel="";
try{
papel=sessionStorage.getItem("empregaMaisPapel")||
localStorage.getItem("empregaMaisPapel")||"";
}catch(e){}
var adminToken="";
var empresaToken="";
try{
adminToken=localStorage.getItem("empregaMaisAdminSupabaseToken")||
sessionStorage.getItem("empregaMaisAdminSupabaseToken")||"";
empresaToken=sessionStorage.getItem("empregaMaisSupabaseAccessToken")||
localStorage.getItem("empregaMaisSupabaseAccessToken")||"";
}catch(e){}
try{
localStorage.removeItem("empregaMaisAdminSupabaseToken");
sessionStorage.removeItem("empregaMaisAdminSupabaseToken");
localStorage.removeItem("empregaMaisPapel");
sessionStorage.removeItem("empregaMaisPapel");
localStorage.removeItem("empregaMaisSupabaseAccessToken");
sessionStorage.removeItem("empregaMaisSupabaseAccessToken");
localStorage.removeItem("empregaMaisSupabaseRefreshToken");
sessionStorage.removeItem("empregaMaisSupabaseRefreshToken");
localStorage.removeItem("empregaMaisSupabaseEmpresaAccessToken");
sessionStorage.removeItem("empregaMaisSupabaseEmpresaAccessToken");
}catch(e){}
limparSessao();
var token = papel==="admin" ? adminToken : empresaToken;
if(token){
try{
await fetch("https://mkezlcewyengejdmtppl.supabase.co/auth/v1/logout",{
method:"POST",
headers:{
"apikey":"sb_publishable_8YnXpzGX8zj-tvzvcMYdyw_FVBhQutR",
"Authorization":"Bearer "+token
}
});
}catch(e){
console.warn("EmpregaMais: falha ao encerrar sess\u00E3o remota.",e);
}
}
try{
localStorage.removeItem("empregaMaisAdminSupabaseToken");
sessionStorage.removeItem("empregaMaisAdminSupabaseToken");
localStorage.removeItem("empregaMaisPapel");
sessionStorage.removeItem("empregaMaisPapel");
}catch(e){}
atualizarTopo();
window.location.replace(window.location.origin + window.location.pathname);
}
function atualizarTopo(){
var papel =
papelAtual();
var publico =
document.getElementById(
"acoesPublicas"
);
var menuPublico =
document.getElementById(
"menuPublico"
);
var candidato =
document.getElementById(
"contaCandidatoTopo"
);
var empresa =
document.getElementById(
"contaEmpresaTopo"
);
var admin =
document.getElementById(
"contaAdminTopo"
);
publico.style.display =
papel ?
"none" :
"block";
candidato.classList.remove(
"ativo"
);
empresa.classList.remove(
"ativo"
);
admin.classList.remove(
"ativo"
);
if(
papel ===
"candidato"
){
candidato.classList.add(
"ativo"
);
menuPublico.style.display =
"";
var nome =
sessionStorage.getItem(
"candidatoNome"
) ||
"Candidato";
document
.getElementById(
"nomeCandidatoTopo"
)
.textContent =
nome.split(" ")[0];
document
.getElementById(
"avatarCandidato"
)
.textContent =
nome
.substring(
0,
1
)
.toUpperCase();
}
if(
papel ===
"empresa"
){
empresa.classList.add(
"ativo"
);
menuPublico.style.display =
"none";
document
.getElementById(
"nomeEmpresaTopo"
)
.textContent =
sessionStorage.getItem(
"empresaNome"
) ||
"Empresa";
}
if(
papel ===
"admin"
){
admin.classList.add(
"ativo"
);
menuPublico.style.display =
"none";
}
if(
!papel
){
menuPublico.style.display =
"";
}
}
function alternarContaMenu(id){
var menu =
document.getElementById(
id
);
if(!menu){
return;
}
var estavaAberto =
menu.classList.contains(
"ativo"
);
fecharMenusConta();
if(
!estavaAberto
){
menu.classList.add(
"ativo"
);
}
}
function fecharMenusConta(){
var menus =
document.querySelectorAll(
".conta-menu"
);
for(
var i=0;
i<menus.length;
i++
){
menus[i]
.classList
.remove(
"ativo"
);
}
}
function carregarArray(chave){
try{
return JSON.parse(
localStorage.getItem(
chave
) ||
"[]"
);
}catch(e){
return [];
}
}
function salvarArray(
chave,
dados
){
localStorage.setItem(
chave,
JSON.stringify(
dados
)
