function vagasDaEmpresa(){
var cnpj =
String(
sessionStorage.getItem(
"empresaCnpj"
) ||
""
).replace(
/\D/g,
""
);
var emailEmpresaSessao =
String(
sessionStorage.getItem(
"empresaEmail"
) ||
""
).trim().toLowerCase();
var nomeEmpresaSessao =
String(
sessionStorage.getItem(
"empresaNome"
) ||
""
).trim().toLowerCase();
var vagas =
carregarVagasPortal();
var retorno =
[];
var alterouVinculo =
false;
for(
var i=0;
i<vagas.length;
i++
){
var vaga =
vagas[i] || {};
var cnpjVaga =
String(
vaga.empresaCnpj ||
vaga.cnpj ||
""
).replace(
/\D/g,
""
);
var emailVaga =
String(
vaga.empresaEmail ||
vaga.email ||
""
).trim().toLowerCase();
var nomeVaga =
String(
vaga.empresa ||
vaga.empresaNome ||
""
).trim().toLowerCase();
var pertence =
false;
if(
cnpj &&
cnpjVaga &&
cnpjVaga === cnpj
){
pertence = true;
}
if(
!pertence &&
emailEmpresaSessao &&
emailVaga &&
emailVaga === emailEmpresaSessao
){
pertence = true;
}
if(
!pertence &&
!cnpjVaga &&
!emailVaga &&
nomeEmpresaSessao &&
nomeVaga === nomeEmpresaSessao
){
pertence = true;
}
if(pertence){
if(
cnpj &&
!String(vaga.empresaCnpj || "").replace(/\D/g,"")
){
vaga.empresaCnpj = cnpj;
alterouVinculo = true;
}
if(
cnpj &&
!String(vaga.cnpj || "").replace(/\D/g,"")
){
vaga.cnpj = cnpj;
alterouVinculo = true;
}
if(
emailEmpresaSessao &&
!String(vaga.empresaEmail || "").trim()
){
vaga.empresaEmail = emailEmpresaSessao;
alterouVinculo = true;
}
if(
emailEmpresaSessao &&
!String(vaga.email || "").trim()
){
vaga.email = emailEmpresaSessao;
alterouVinculo = true;
}
retorno.push(
vaga
);
}
}
if(alterouVinculo){
try{
salvarVagasPortal(
vagas
);
}catch(e){}
}
return retorno;
}
function alternarFaq(botao){
