i<todos.length;
i++
){
if(
todos[i] !==
item
){
todos[i].classList.remove(
"aberto"
);
var outroSinal =
todos[i]
.querySelector(
".faq-pergunta span:last-child"
);
if(outroSinal){
outroSinal.textContent =
"+";
}
}
}
item.classList.toggle(
"aberto"
);
var sinal =
botao.querySelector(
"span:last-child"
);
if(sinal){
sinal.textContent =
item.classList.contains(
"aberto"
)
? "-"
: "+";
}
}
