function editarVagaEmpresa(id){
var vagas =
carregarVagasPortal();
var vaga =
null;
for(
var i=0;
i<vagas.length;
i++
){
if(
String(vagas[i].id) ===
String(id)
){
vaga =
vagas[i];
break;
}
}
if(!vaga){
alert("N\u00E3o foi poss\u00EDvel localizar esta vaga.");
return;
}
if(vaga.status === "encerrada"){
alert("Uma vaga encerrada n\u00E3o pode mais ser editada.");
return;
}
try{
sessionStorage.setItem(
"vagaEdicaoEmpregaMais",
JSON.stringify(vaga)
);
}catch(erro){}
irPara("publicar");
setTimeout(
function(){
var v = vaga;
try{
preencherFormularioEdicao(v);
}catch(erro){
console.warn("Preenchimento original:", erro);
}
function preencher(
seletores,
valor
){
if(
valor === undefined ||
valor === null
){
return;
}
for(
var s=0;
s<seletores.length;
s++
){
var campo =
document.querySelector(
seletores[s]
);
if(campo){
campo.value =
valor;
try{
campo.dispatchEvent(
new Event(
"input",
{bubbles:true}
)
);
campo.dispatchEvent(
new Event(
"change",
{bubbles:true}
)
);
}catch(e){}
return;
}
}
}
