function encerrarVagaEmpresa(
id
){
var vaga =
localizarVagaPortal(
id
);
if(
!vaga ||
!vagaPertenceEmpresaAtual(
vaga
)
){
alert(
"N\u00E3o foi poss\u00EDvel localizar esta vaga."
);
return;
}
if(
vaga.status ===
"encerrada"
){
return;
}
var confirmar =
window.confirm(
"Deseja realmente encerrar esta vaga? Ela deixar\u00E1 de aparecer para os candidatos."
);
if(!confirmar){
return;
}
var vagas =
carregarVagasPortal();
for(
var i=0;
i<vagas.length;
i++
){
if(
vagas[i].id ===
id
){
vagas[i].status =
"encerrada";
vagas[i].dataEncerramento =
dataHoje();
break;
}
}
salvarVagasPortal(
vagas
);
mostrarToast(
"Vaga encerrada com sucesso."
);
renderizarPainelEmpresa();
renderizarVagasAprovadasEmpresa();
}
