function textoSeguroEM(valor){
if(
typeof escaparTexto ===
"function"
){
return escaparTexto(
valor
);
}
return String(
valor == null ?
"" :
valor
)
.replace(
/&/g,
"&amp;"
)
.replace(
/</g,
"&lt;"
)
.replace(
/>/g,
"&gt;"
)
.replace(
/"/g,
"&quot;"
);
}
function valorVagaEM(
vaga,
campos,
padrao
){
for(
var i=0;
i<campos.length;
i++
){
var valor =
vaga[
campos[i]
];
if(
valor !==
undefined &&
valor !==
null &&
String(valor).trim() !==
""
){
return valor;
}
}
return padrao;
}
function dataVagaCompactaEM(
vaga
){
var valor =
valorVagaEM(
vaga,
[
"data",
"dataPublicacao",
"publicadaEm",
"created_at"
],
""
);
if(!valor){
return "-";
}
if(
typeof formatarDataBR ===
"function"
){
try{
return formatarDataBR(
valor
);
}catch(e){}
}
var txt =
String(
valor
);
var m =
txt.match(
/^(\d{4})-(\d{2})-(\d{2})/
);
if(m){
return (
m[3]+
"/"+
m[2]+
"/"+
m[1]
);
}
return txt;
}
