function empresaPorCnpj(
cnpj
){
var lista =
empresasCadastradas();
var alvo =
somenteNumeros(
cnpj
);
for(
var i=0;
i<lista.length;
i++
){
if(
somenteNumeros(
lista[i].cnpj
) === alvo
){
return lista[i];
}
}
return null;
}
function empresaEstaVerificada(
empresa
){
return !!(
empresa &&
empresa.verificada ===
true &&
empresa.verificacaoStatus ===
"verificada"
);
}
function statusVerificacaoTexto(
empresa
){
if(
empresaEstaVerificada(
empresa
)
){
return "Empresa verificada";
}
if(
empresa &&
empresa.verificacaoStatus ===
"em_analise"
){
return "Em an\u00E1lise";
}
if(
empresa &&
empresa.verificacaoStatus ===
"rejeitada"
){
return "Verifica\u00E7\u00E3o recusada";
}
return "N\u00E3o verificada";
}
