function textoLimpoAnalise(
valor
){
return (
valor ||
""
)
.toString()
.toLowerCase()
.normalize("NFD")
.replace(
/[\u0300-\u036f]/g,
""
);
}
function contemPadraoSuspeitoVaga(
vaga
){
var conteudo =
textoLimpoAnalise(
[
vaga.cargo,
vaga.descricao,
vaga.requisitos,
vaga.beneficios,
vaga.sobreEmpresa
].join(" ")
);
var padroes =
[
"pague para participar",
"taxa de inscricao",
"taxa para participar",
"pagamento de taxa",
"compra obrigatoria",
"curso obrigatorio pago",
"material obrigatorio pago",
"ganhos garantidos",
"dinheiro facil",
"renda garantida",
"pir\u00E2mide",
"piramide financeira",
"investimento inicial obrigatorio",
"deposito antecipado",
"pix para participar"
];
for(
var i=0;
i<padroes.length;
i++
){
if(
conteudo.indexOf(
textoLimpoAnalise(
padroes[i]
)
) !==
-1
){
return true;
}
}
return false;
}
function contatoCandidaturaValido(
vaga
){
if(
vaga.tipoContato ===
"email"
){
return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(
vaga.contatoCandidatura ||
""
);
}
if(
vaga.tipoContato ===
"whatsapp"
){
var numero =
normalizarWhatsappVaga(
vaga.contatoCandidatura ||
""
);
return numero.length >=
10;
}
if(
vaga.tipoContato ===
"link"
){
return /^https?:\/\//i.test(
vaga.contatoCandidatura ||
""
);
}
return true;
}
function vagaTemCamposObrigatorios(
vaga
){
var obrigatorios =
[
vaga.cargo,
vaga.area,
vaga.cidade,
vaga.modalidade,
vaga.contrato,
vaga.escolaridade,
vaga.descricao,
vaga.requisitos
];
for(
var i=0;
i<obrigatorios.length;
i++
){
if(
!obrigatorios[i] ||
obrigatorios[i]
.toString()
.trim() ===
""
){
return false;
}
}
return true;
}
function validarVagaParaAprovacaoAutomatica(
vaga,
empresa
){
var motivos =
[];
if(
!empresaPodeUsarAprovacaoAutomatica(
empresa
)
){
motivos.push(
"Empresa sem aprova\u00E7\u00E3o autom\u00E1tica ativa"
);
}
if(
!vagaTemCamposObrigatorios(
vaga
)
){
motivos.push(
"Cadastro da vaga incompleto"
);
}
if(
!contatoCandidaturaValido(
vaga
)
){
motivos.push(
"Forma de candidatura inv\u00E1lida"
);
}
if(
contemPadraoSuspeitoVaga(
vaga
)
){
motivos.push(
"Conte\u00FAdo que exige an\u00E1lise manual"
);
}
return {
aprovar:
motivos.length ===
0,
motivos:
motivos
};
}
function aplicarResultadoAprovacaoAutomatica(
vaga,
empresa
){
var resultado =
validarVagaParaAprovacaoAutomatica(
vaga,
empresa
);
if(
resultado.aprovar
){
vaga.aprovacao =
"aprovada";
vaga.jaFoiAprovada =
true;
vaga.status =
"ativa";
vaga.aprovacaoAutomatica =
true;
vaga.aprovacaoAutomaticaEm =
dataHoje();
vaga.ultimaAprovacaoEm =
dataHoje();
vaga.motivoAnaliseManual =
"";
}else{
vaga.aprovacao =
"pendente";
vaga.status =
"ativa";
vaga.aprovacaoAutomatica =
false;
vaga.motivoAnaliseManual =
resultado.motivos.join(
"; "
);
}
return resultado;
}
