'<button type="button" class="popup-excluir-cancelar">Cancelar</button>' +
'<button type="button" class="popup-excluir-confirmar">Sim, excluir</button>' +
'</div>' +
'</div>';
var strong =
overlay.querySelector(
"strong"
);
if(strong){
strong.textContent =
cargo;
}
document.body.appendChild(
overlay
);
function fechar(){
overlay.classList.remove(
"ativo"
);
setTimeout(
function(){
if(overlay.parentNode){
overlay.parentNode.removeChild(
overlay
);
}
},
150
);
}
overlay.querySelector(
".popup-excluir-cancelar"
).onclick =
fechar;
overlay.querySelector(
".popup-excluir-confirmar"
).onclick =
function(){
fechar();
if(
typeof aoConfirmar ===
"function"
){
aoConfirmar();
}
};
overlay.onclick =
function(event){
if(
event.target ===
overlay
){
