function dataDaquiDias(
dias
){
var data =
new Date();
data.setDate(
data.getDate() +
dias
);
var ano =
data.getFullYear();
var mes =
String(
data.getMonth() + 1
).padStart(
2,
"0"
);
var dia =
String(
data.getDate()
).padStart(
2,
"0"
);
return (
ano +
"-" +
mes +
"-" +
dia
);
}
function destacarVagaGratisAdmin(
