vagas[i].id
) ===
String(
id
)
){
vagas[i].destaque =
true;
vagas[i].destaqueCortesia =
true;
vagas[i].destaqueOrigem =
"admin_gratis";
vagas[i].destaqueInicio =
dataHoje();
vagas[i].fimDestaque =
dataDaquiDias(
