function vagaTemDestaqueGratisAtivo(
vaga
){
if(
!vaga ||
vaga.destaque !==
true ||
vaga.destaqueCortesia !==
true
){
return false;
}
if(
!vaga.fimDestaque
){
return true;
}
var hoje =
new Date(
dataHoje() +
"T00:00:00"
);
var fim =
new Date(
vaga.fimDestaque +
"T23:59:59"
);
return fim >=
hoje;
}
