function aplicarOverrideAdminVaga(
vaga
){
if(!vaga){
return vaga;
}
var copia =
Object.assign(
{},
vaga
);
var overrides =
carregarOverridesVagasAdmin();
var override =
overrides[
String(
vaga.id
)
];
if(override){
copia =
Object.assign(
copia,
override
);
}
return copia;
}
function todasAsVagasAdmin(){
var resultado =
[];
var ids =
{};
var salvas =
carregarVagasPortal();
for(
var i=0;
i<salvas.length;
i++
){
var salva =
aplicarOverrideAdminVaga(
salvas[i]
);
salva.origemAdmin =
"empresa";
resultado.push(
salva
);
ids[
String(
salva.id
)
] =
true;
}
for(
var j=0;
j<vagasPadrao.length;
j++
){
if(
ids[
String(
vagasPadrao[j].id
)
]
){
continue;
}
var padrao =
aplicarOverrideAdminVaga(
vagasPadrao[j]
);
padrao.origemAdmin =
"sistema";
resultado.push(
padrao
);
}
return resultado;
}
