);
if(encontrada){
encontrada.lista[
encontrada.indice
].destaque =
!!ativo;
encontrada.lista[
encontrada.indice
].destaqueCortesia =
!!ativo;
encontrada.lista[
encontrada.indice
].destaqueOrigem =
ativo
? "admin"
: "";
encontrada.lista[
encontrada.indice
].destaqueInicio =
ativo
? dataHoje()
: "";
encontrada.lista[
encontrada.indice
].fimDestaque =
"";
encontrada.lista[
encontrada.indice
].destaqueConsomePlano =
false;
salvarVagasPortal(
encontrada.lista
);
}else{
var overrides =
carregarOverridesVagasAdmin();
var chave =
String(
id
);
if(
!overrides[chave]
){
overrides[chave] =
{};
}
overrides[chave].destaque =
!!ativo;
overrides[chave].destaqueCortesia =
!!ativo;
overrides[chave].destaqueOrigem =
ativo
? "admin"
: "";
overrides[chave].destaqueInicio =
ativo
? dataHoje()
: "";
overrides[chave].fimDestaque =
"";
overrides[chave].destaqueConsomePlano =
false;
salvarOverridesVagasAdmin(
overrides
);
}
mostrarToast(
ativo
? "Vaga colocada em destaque."
: "Destaque removido."
);
renderizarPainelAdmin();
renderizarVagas();
}
