function atualizarAprovacaoVaga(
id,
status
){
var vagas =
carregarVagasPortal();
for(
var i=0;
i<vagas.length;
i++
){
if(
vagas[i].id ===
id
){
vagas[i].aprovacao =
status;
if(
status ===
"aprovada"
){
vagas[i].jaFoiAprovada =
true;
vagas[i].status =
vagas[i].status ===
"encerrada"
? "encerrada"
: "ativa";
vagas[i].ultimaAprovacaoEm =
dataHoje();
if(
typeof vagas[i].edicoesAposAprovacao ===
"undefined"
){
vagas[i].edicoesAposAprovacao =
0;
}
}
break;
}
}
salvarVagasPortal(
vagas
);
alert(
status ===
"aprovada" ?
"Vaga aprovada e liberada no portal." :
"Vaga reprovada."
);
renderizarPainelAdmin();
renderizarFilaPendentesAdmin();
}
