i<vagas.length;
i++
){
if(
String(vagas[i].id) ===
String(candidatura.vagaId)
){
return true;
}
}
return false;
}
function classeStatusProcesso(status){
if(
status ===
"Contratado"
){
return "status-selecionado";
}
if(
status ===
"Aprovado"
){
return "status-selecionado";
}
if(
status ===
"Selecionado"
){
return "status-selecionado";
}
if(
status ===
"Pr\u00E9-selecionado"
){
return "status-pre";
}
if(
status ===
"Entrevista agendada"
){
return "status-entrevista";
}
if(
status.indexOf(
"Reprovado"
) !== -1 ||
status ===
"Processo encerrado"
){
return "status-reprovado";
}
return "status-analise";
}
