new Date().toISOString();
if(
novoStatus ===
"Aprovado"
){
candidaturas[i].aprovadoEm =
candidaturas[i].aprovadoEm ||
new Date().toISOString();
}
if(
novoStatus ===
"Contratado"
){
candidaturas[i].contratadoEm =
candidaturas[i].contratadoEm ||
new Date().toISOString();
