function localizarVaga(id){
var todas =
vagasPadrao.concat(
carregarVagasPortal()
);
for(
var i=0;
i<todas.length;
i++
){
if(
String(todas[i].id) ===
String(id)
){
return todas[i];
}
}
return null;
}
function inicioDoDiaLocal(
valor
){
if(!valor){
return null;
}
var partes =
String(valor).split("-");
if(
partes.length ===
3
){
return new Date(
Number(partes[0]),
Number(partes[1]) - 1,
Number(partes[2]),
0,
0,
0,
0
);
}
var data =
new Date(valor);
if(
isNaN(
data.getTime()
)
){
return null;
}
data.setHours(
0,
0,
0,
0
);
return data;
}
function diferencaDiasInteiros(
dataFinal,
dataInicial
){
if(
!dataFinal ||
!dataInicial
){
return null;
}
var msDia =
24 *
60 *
60 *
1000;
return Math.round(
(
dataFinal.getTime() -
dataInicial.getTime()
) /
msDia
);
}
function obterStatusVisualVaga(
vaga
){
if(!vaga){
return {
texto:"",
classe:"normal"
};
}
var hoje =
new Date();
hoje.setHours(
0,
0,
0,
0
);
var publicada =
inicioDoDiaLocal(
vaga.dataPublicacao
);
var encerra =
inicioDoDiaLocal(
vaga.expiraEm
);
if(
vaga.status ===
"encerrada"
){
return {
texto:"Vaga encerrada",
classe:"encerrada"
};
}
if(
encerra
){
var diasRestantes =
diferencaDiasInteiros(
encerra,
hoje
);
if(
diasRestantes <
0
){
return {
texto:"Vaga encerrada",
classe:"encerrada"
};
}
if(
diasRestantes ===
0
){
return {
texto:"\u00DAltimo dia",
classe:"ultimo-dia"
};
}
if(
diasRestantes <=
7
){
return {
texto:
"Encerra em " +
diasRestantes +
(
diasRestantes ===
1
? " dia"
: " dias"
),
classe:"atencao"
};
}
}
if(
publicada
){
var diasPublicada =
diferencaDiasInteiros(
hoje,
publicada
);
if(
diasPublicada >=
0 &&
diasPublicada <=
3
){
return {
texto:"Publicada recentemente",
classe:"recente"
};
}
}
if(
encerra
){
var restante =
diferencaDiasInteiros(
encerra,
hoje
);
if(
restante >
7
){
return {
texto:
"Encerra em " +
restante +
" dias",
classe:"normal"
};
}
}
return {
texto:"Vaga ativa",
classe:"normal"
};
}
