function pontuacaoRecomendacaoVaga(
referencia,
candidata
){
var pontos =
0;
if(
referencia.area &&
candidata.area &&
referencia.area ===
candidata.area
){
pontos +=
50;
}
if(
referencia.modalidade &&
candidata.modalidade &&
referencia.modalidade ===
candidata.modalidade
){
pontos +=
20;
}
if(
referencia.cidade &&
candidata.cidade &&
referencia.cidade
.toLowerCase() ===
candidata.cidade
.toLowerCase()
){
pontos +=
15;
}
if(
referencia.contrato &&
candidata.contrato &&
referencia.contrato ===
candidata.contrato
){
pontos +=
10;
}
if(
referencia.escolaridade &&
candidata.escolaridade &&
referencia.escolaridade ===
candidata.escolaridade
){
pontos +=
8;
}
var cargoReferencia =
(
referencia.cargo ||
""
)
.toLowerCase()
.split(/\s+/);
var cargoCandidata =
(
candidata.cargo ||
""
)
.toLowerCase();
for(
var i=0;
i<cargoReferencia.length;
i++
){
var palavra =
cargoReferencia[i];
if(
palavra.length >=
4 &&
cargoCandidata.indexOf(
palavra
) !==
-1
){
pontos +=
4;
}
}
return pontos;
}
function renderizarRecomendacoesVaga(
vagaReferencia
){
var bloco =
document.getElementById(
"listaRecomendacoesVaga"
);
var secao =
document.getElementById(
"secaoRecomendacoesVaga"
);
if(
!bloco ||
!secao ||
!vagaReferencia
){
return;
}
bloco.innerHTML =
"";
var vagas =
todasAsVagasPublicas();
var candidatas =
[];
for(
var i=0;
i<vagas.length;
i++
){
var vaga =
vagas[i];
if(
String(
vaga.id
) ===
String(
vagaReferencia.id
)
){
continue;
}
var pontos =
pontuacaoRecomendacaoVaga(
vagaReferencia,
vaga
);
candidatas.push({
vaga:vaga,
pontos:pontos
});
}
candidatas.sort(
function(a,b){
if(
b.pontos !==
a.pontos
){
return b.pontos -
a.pontos;
}
var dataA =
new Date(
a.vaga.dataPublicacao ||
0
).getTime();
var dataB =
new Date(
b.vaga.dataPublicacao ||
0
).getTime();
return dataB -
dataA;
}
);
var limite =
Math.min(
12,
candidatas.length
);
if(
limite ===
0
){
bloco.innerHTML =
"<div class='recomendacoes-vaga-vazio'>Ainda n\u00E3o encontramos outras vagas semelhantes a esta.</div>";
return;
}
for(
var j=0;
j<limite;
j++
){
bloco.appendChild(
criarCardRecomendacaoVaga(
candidatas[j].vaga
)
);
}
}
