function formatarSalarioExibicao(
valor
){
if(
valor === null ||
valor === undefined ||
String(valor).trim() === ""
){
return "A combinar";
}
var original =
String(valor).trim();
if(
original.toLowerCase().indexOf("combinar") !== -1
){
return "A combinar";
}
var limpo =
original
.replace(/R\$/gi,"")
.replace(/\s/g,"");
var numero;
if(
limpo.indexOf(",") !== -1
){
numero =
Number(
limpo
.replace(/\./g,"")
.replace(",",".")
);
}else{
numero =
Number(
limpo.replace(/[^\d.-]/g,"")
);
}
if(
!isFinite(numero)
){
return original;
}
return numero.toLocaleString(
"pt-BR",
{
minimumFractionDigits:2,
maximumFractionDigits:2
}
);
}
function formatarSalarioPrevia(
valor
){
var formatado =
formatarSalarioExibicao(
valor
);
if(
formatado ===
"A combinar"
){
return "Sal\u00E1rio: A combinar";
}
return "Sal\u00E1rio: R$ " +
formatado;
}
