function renderizarVagas(){
renderizarEmpresasContratando();
atualizarEstatisticasHome();
var vagas =
todasAsVagasPublicas()
.slice();
var ordem =
document
.getElementById(
"ordenacaoVagas"
)
.value;
if(ordem==="recentes"){
function dataBaseV56(v){
var raw=v.dataPublicacao||v.criadoEm||v.dataCriacao||"";
var d=new Date(raw);
return isNaN(d.getTime())?0:d.getTime();
}
function urgenteV56(v){
return v.contratacaoUrgente===true ||
String(v.contratacaoUrgente).toLowerCase()==="true" ||
v.urgente===true ||
String(v.urgente).toLowerCase()==="true";
}
function ultimoReimpulsoV56(v){
var base=dataBaseV56(v);
if(!urgenteV56(v))return base;
var agora=new Date(),horas=[8,14,20],melhor=base;
for(var h=0;h<horas.length;h++){
var x=new Date(agora.getFullYear(),agora.getMonth(),agora.getDate(),horas[h],0,0,0);
if(x.getTime()<=agora.getTime() && x.getTime()>melhor)melhor=x.getTime();
}
var ontem=new Date(agora.getFullYear(),agora.getMonth(),agora.getDate()-1,20,0,0,0);
if(ontem.getTime()>melhor)melhor=ontem.getTime();
return melhor;
}
vagas.sort(function(a,b){return ultimoReimpulsoV56(b)-ultimoReimpulsoV56(a);});
}
if(
ordem ===
"maiorSalario"
){
vagas.sort(
function(a,b){
return (
b.salarioNumero -
a.salarioNumero
);
}
);
}
if(
ordem ===
"menorSalario"
){
vagas.sort(
function(a,b){
return (
a.salarioNumero -
b.salarioNumero
);
}
);
}
if(
ordem ===
"cargo"
){
vagas.sort(
function(a,b){
return String(
a.cargo
).localeCompare(
String(
b.cargo
)
);
}
);
}
