}
function filtrarVagas(){
var palavra =
document
.getElementById(
"filtroPalavra"
)
.value
.toLowerCase();
var cidade =
document
.getElementById(
"filtroCidade"
)
.value
.toLowerCase();
var salario =
parseFloat(
document
.getElementById(
"filtroSalario"
)
.value
) ||
0;
var area =
document
.getElementById(
"filtroArea"
)
.value
.toLowerCase();
var contrato =
document
.getElementById(
"filtroContrato"
)
.value
.toLowerCase();
var pcd =
document
.getElementById(
"filtroPcd"
)
.value
.toLowerCase();
var modalidade =
document
.getElementById(
"filtroModalidade"
)
.value
.toLowerCase();
var cards =
document.querySelectorAll(
"#listaVagas .vaga-card"
);
var total =
0;
for(
var i=0;
i<cards.length;
i++
){
var card =
cards[i];
var titulo =
(
card.getAttribute(
"data-titulo"
) ||
""
).toLowerCase();
var empresa =
(
card.getAttribute(
"data-empresa"
) ||
""
).toLowerCase();
var cidadeCard =
(
card.getAttribute(
"data-cidade"
) ||
""
).toLowerCase();
var areaCard =
(
card.getAttribute(
"data-area"
) ||
""
).toLowerCase();
var contratoCard =
(
card.getAttribute(
"data-contrato"
) ||
""
).toLowerCase();
var pcdCard =
(
card.getAttribute(
"data-pcd"
) ||
""
).toLowerCase();
var modalidadeCard =
(
card.getAttribute(
"data-modalidade"
) ||
""
).toLowerCase();
var salarioCard =
parseFloat(
card.getAttribute(
"data-salario"
)
) ||
0;
var mostrar =
(
!palavra ||
titulo.indexOf(
palavra
) !== -1 ||
empresa.indexOf(
palavra
) !== -1
) &&
(
!cidade ||
cidadeCard.indexOf(
cidade
) !== -1
) &&
(
!salario ||
salarioCard >=
salario
) &&
(
!area ||
areaCard ===
area
) &&
(
!contrato ||
contratoCard ===
contrato
) &&
(
!pcd ||
pcdCard ===
pcd
) &&
(
!modalidade ||
modalidadeCard ===
modalidade
);
card.style.display =
mostrar ?
"block" :
"none";
if(mostrar){
total++;
}
}
document
.getElementById(
"contador"
)
.innerHTML =
"<strong>" +
total +
"</strong> vaga(s) encontrada(s)";
document
.getElementById(
"semVaga"
)
.style.display =
total === 0 ?
"block" :
"none";
}
