function configuracaoPlanoEmpresa(plano){
var planos = {
essencial:{
id:"essencial",
nome:"Essencial",
preco:0,
vagasMes:5,
destaquesMes:0,
diasVaga:15
},
profissional:{
id:"profissional",
nome:"Profissional",
preco:29.90,
vagasMes:15,
destaquesMes:3,
diasVaga:30
},
premium:{
id:"premium",
nome:"Premium",
preco:59.90,
vagasMes:40,
destaquesMes:10,
diasVaga:45
}
};
return planos[plano] || planos.essencial;
}
function planoEmpresaAtual(){
var empresa =
obterEmpresaAtual();
if(!empresa){
return configuracaoPlanoEmpresa(
"essencial"
);
}
return configuracaoPlanoEmpresa(
empresa.plano || "essencial"
);
}
function inicioMesAtual(){
var hoje =
new Date();
return new Date(
hoje.getFullYear(),
hoje.getMonth(),
1
);
}
function contarVagasEmpresaMes(cnpj){
var vagas =
carregarVagasPortal();
var inicio =
inicioMesAtual();
var total =
0;
for(
var i=0;
i<vagas.length;
i++
){
if(
somenteNumeros(
vagas[i].empresaCnpj || ""
) !==
somenteNumeros(
cnpj || ""
)
){
continue;
}
if(
vagas[i].status ===
"encerrada" ||
vagas[i].status ===
"excluida"
){
continue;
}
var data =
new Date(
vagas[i].dataPublicacao +
"T12:00:00"
);
if(
data >= inicio
){
total++;
}
}
return total;
}
