function normalizarWhatsappVaga(
numero
){
return String(
numero ||
""
).replace(
/\D/g,
""
);
}
function abrirContatoExternoVaga(
vaga
){
if(
!vaga ||
!vaga.tipoContato
){
abrirCandidaturaProtegida(
vaga.id
);
return;
}
if(
vaga.tipoContato ===
"email"
){
var assunto =
encodeURIComponent(
"Candidatura - " +
vaga.cargo
);
window.location.href =
"mailto:" +
vaga.contatoCandidatura +
"?subject=" +
assunto;
return;
}
if(
vaga.tipoContato ===
"whatsapp"
){
var numero =
normalizarWhatsappVaga(
vaga.contatoCandidatura
);
var mensagem =
encodeURIComponent(
"Ol\u00E1! Tenho interesse na vaga de " +
vaga.cargo +
" divulgada no EmpregaMais."
);
window.open(
"https://wa.me/" +
numero +
"?text=" +
mensagem,
"_blank"
);
return;
}
if(
vaga.tipoContato ===
"link"
){
window.open(
vaga.contatoCandidatura,
"_blank"
);
return;
}
abrirCandidaturaProtegida(
vaga.id
);
}
function textoBotaoContatoVaga(
vaga
){
if(
!vaga ||
!vaga.tipoContato
){
return "Candidatar-se";
}
if(
vaga.tipoContato ===
"email"
){
return "Candidatar-se por e-mail";
}
if(
vaga.tipoContato ===
"whatsapp"
){
return "Candidatar-se pelo WhatsApp";
}
if(
vaga.tipoContato ===
"link"
){
return "Candidatar-se no site da empresa";
}
return "Candidatar-se";
