function nomeEmpresaInicial(nome){
var partes =
String(nome || "Empresa")
.trim()
.split(/\s+/);
var iniciais =
"";
for(
var i=0;
i<partes.length && i<2;
i++
){
if(partes[i]){
iniciais +=
partes[i]
.charAt(0)
.toUpperCase();
}
}
return iniciais || "E";
}
