var VALOR_CONTRATACAO_URGENTE = 9.90;
var DIAS_CONTRATACAO_URGENTE = 7;
function instalarOpcaoContratacaoUrgente() {
if (document.getElementById("contratacaoUrgenteEmpregaMais")) return;
var form = document.querySelector(
"#form-publicar-vaga, #formPublicarVaga, form[data-form='vaga'], form[data-form='publicar-vaga']"
);
if (!form) {
var botoes = Array.prototype.slice.call(
document.querySelectorAll("button")
);
for (var i = 0; i < botoes.length; i++) {
var t = (botoes[i].textContent || "").toLowerCase();
if (t.indexOf("publicar vaga") !== -1 || t.indexOf("enviar vaga") !== -1) {
form = botoes[i].closest("form");
if (form) break;
}
}
}
if (!form) return;
var box = document.createElement("div");
box.className = "opcao-urgente-em";
box.innerHTML =
'<label>' +
'<input type="checkbox" id="contratacaoUrgenteEmpregaMais" name="contratacaoUrgente"/>' +
'<span>\u26A1 Contrata\u00E7\u00E3o Urgente \u2014 R$ 9,90</span>' +
'</label>' +
'<small>Adicione a tag \u201CContrata\u00E7\u00E3o Urgente\u201D \u00E0 vaga por 7 dias. A vaga continua sujeita \u00E0 aprova\u00E7\u00E3o do administrador.</small>';
var submit = form.querySelector("button[type='submit'], input[type='submit']");
if (submit && submit.parentNode) submit.parentNode.insertBefore(box, submit);
else form.appendChild(box);
}
function vagaEhUrgenteEmpregaMais(vaga) {
if (!vaga) return false;
return vaga.contratacaoUrgente === true ||
String(vaga.contratacaoUrgente).toLowerCase() === "true" ||
String(vaga.urgente).toLowerCase() === "true";
}
function tagUrgenteEmpregaMais() {
return '<span class="tag-contratacao-urgente">\u26A1 Contrata\u00E7\u00E3o Urgente</span>';
}
var publicarVagaAntesUrgenteEmpregaMais = publicarVaga;
publicarVaga = function(event) {
var marcado = false;
var check = document.getElementById("contratacaoUrgenteEmpregaMais");
if (check) marcado = !!check.checked;
var idsAntes = {};
var antes = [];
try { antes = carregarVagasPortal(); } catch (e) { antes = []; }
for (var i = 0; i < antes.length; i++) {
idsAntes[String(antes[i].id || "")] = true;
}
publicarVagaAntesUrgenteEmpregaMais(event);
if (!marcado) return;
setTimeout(function() {
var vagas = [];
try { vagas = carregarVagasPortal(); } catch (e) { vagas = []; }
for (var j = vagas.length - 1; j >= 0; j--) {
var id = String(vagas[j].id || "");
if (id && !idsAntes[id]) {
vagas[j].contratacaoUrgente = true;
vagas[j].valorContratacaoUrgente = VALOR_CONTRATACAO_URGENTE;
vagas[j].diasContratacaoUrgente = DIAS_CONTRATACAO_URGENTE;
vagas[j].urgenteAte = new Date(
Date.now() + DIAS_CONTRATACAO_URGENTE * 86400000
).toISOString();
salvarVagasPortal(vagas);
try { renderizarPainelEmpresa(); } catch (e) {}
try { renderizarPainelAdmin(); } catch (e) {}
try { renderizarHome(); } catch (e) {}
break;
}
}
}, 350);
};
function aplicarTagsUrgentesEmpregaMais() {
var vagas = [];
try { vagas = carregarVagasPortal(); } catch (e) { vagas = []; }
var urgentes = {};
for (var i = 0; i < vagas.length; i++) {
if (vagaEhUrgenteEmpregaMais(vagas[i])) {
var ate = vagas[i].urgenteAte ? new Date(vagas[i].urgenteAte).getTime() : 0;
if (!ate || ate >= Date.now()) {
urgentes[String(vagas[i].id || "")] = true;
}
}
}
document.querySelectorAll("[data-vaga-id]").forEach(function(card) {
var id = String(card.getAttribute("data-vaga-id") || "");
if (!urgentes[id] || card.querySelector(".tag-contratacao-urgente")) return;
var alvo = card.querySelector(".labels, .tags, .vaga-tags, .job-tags, h3, h2") || card;
alvo.insertAdjacentHTML("beforeend", " " + tagUrgenteEmpregaMais());
});
}
window.addEventListener("load", function() {
setTimeout(instalarOpcaoContratacaoUrgente, 700);
setTimeout(aplicarTagsUrgentesEmpregaMais, 1200);
var observer = new MutationObserver(function() {
instalarOpcaoContratacaoUrgente();
aplicarTagsUrgentesEmpregaMais();
});
observer.observe(document.body, {childList:true, subtree:true});
});
function valorCampoUrgente(seletores){
for(var i=0;i<seletores.length;i++){
var el=document.querySelector(seletores[i]);
if(el && String(el.value||"").trim()){
return String(el.value).trim();
}
}
return "";
}
function escaparPreviewUrgente(valor){
return String(valor || "")
.replace(/&/g,"&amp;")
.replace(/</g,"&lt;")
.replace(/>/g,"&gt;")
.replace(/"/g,"&quot;");
}
