function abrirPreviewUrgente(aoConfirmar){
criarModalPreviewUrgente();
var cargo=valorCampoUrgente(["#cargo","[name='cargo']"]) || "T\u00EDtulo da vaga";
var cidade=valorCampoUrgente(["#cidade","[name='cidade']"]) || "Cidade";
