var salario=valorCampoUrgente(["#salario","[name='salario']"]);
var descricao=valorCampoUrgente(["#descricao","[name='descricao']"]);
var requisitos=valorCampoUrgente(["#requisitos","[name='requisitos']"]);
var meta=[cidade,modalidade,contrato].filter(Boolean).join(" \u2022 ");
var html=
'<div class="preview-urgente-card">'+
'<span class="preview-urgente-tag">\u26A1 Contrata\u00E7\u00E3o Urgente</span>'+
'<h2>'+escaparPreviewUrgente(cargo)+'</h2>'+
'<div class="preview-urgente-meta">'+escaparPreviewUrgente(meta)+'</div>'+
(salario?'<div class="preview-urgente-secao"><strong>Sal\u00E1rio</strong>R$ '+escaparPreviewUrgente(salario)+'</div>':'')+
(descricao?'<div class="preview-urgente-secao"><strong>Descri\u00E7\u00E3o da vaga</strong>'+escaparPreviewUrgente(descricao).replace(/\n/g,"<br/>")+'</div>':'')+
(requisitos?'<div class="preview-urgente-secao"><strong>Requisitos</strong>'+escaparPreviewUrgente(requisitos).replace(/\n/g,"<br/>")+'</div>':'')+
'<div class="preview-urgente-preco"><strong>Contrata\u00E7\u00E3o Urgente: R$ 9,90</strong><br/>A identifica\u00E7\u00E3o de urg\u00EAncia fica ativa por 7 dias ap\u00F3s a publica\u00E7\u00E3o/aprova\u00E7\u00E3o.</div>'+
'</div>'+
'<div class="preview-urgente-acoes">'+
'<button type="button" class="preview-urgente-voltar">Voltar e editar</button>'+
'<button type="button" class="preview-urgente-confirmar">Confirmar e enviar</button>'+
'</div>';
var conteudo=document.getElementById("conteudoPreviewUrgente");
conteudo.innerHTML=html;
conteudo.querySelector(".preview-urgente-voltar").onclick=fecharPreviewUrgente;
conteudo.querySelector(".preview-urgente-confirmar").onclick=function(){
fecharPreviewUrgente();
if(typeof aoConfirmar==="function") aoConfirmar();
};
document.getElementById("previewUrgenteEmpregaMais").classList.add("ativo");
}
var publicarVagaAntesPreviewUrgenteEmpregaMais=publicarVaga;
var confirmandoPreviewUrgenteEmpregaMais=false;
publicarVaga=function(event){
var check=document.getElementById("contratacaoUrgenteEmpregaMais");
if(
check &&
check.checked &&
!confirmandoPreviewUrgenteEmpregaMais
){
if(event){
if(typeof event.preventDefault==="function") event.preventDefault();
if(typeof event.stopPropagation==="function") event.stopPropagation();
}
abrirPreviewUrgente(function(){
confirmandoPreviewUrgenteEmpregaMais=true;
try{
publicarVagaAntesPreviewUrgenteEmpregaMais(event);
}finally{
setTimeout(function(){
confirmandoPreviewUrgenteEmpregaMais=false;
},300);
}
});
return false;
}
return publicarVagaAntesPreviewUrgenteEmpregaMais(event);
};
