atualizarAprovacaoVaga =
function(id, aprovacao){
var alteracoes = {
aprovacao:
aprovacao
};
if(
aprovacao ===
"aprovada"
){
alteracoes.jaFoiAprovada =
true;
alteracoes.status =
"ativa";
alteracoes.ultimaAprovacaoEm =
dataHoje();
}
atualizarVagaLocalAdminEmpregaMais(
id,
alteracoes
);
atualizarTelasAdminEmpregaMais();
apiEmpregaMaisPost({
acao:
aprovacao === "aprovada"
? "aprovar"
: "rejeitar",
id:id
})
.then(function(resultado){
if(
!resultado ||
resultado.sucesso !== true
){
throw new Error(
resultado &&
resultado.erro
? resultado.erro
: "O servidor n\u00E3o confirmou a altera\u00E7\u00E3o."
);
}
mostrarModalSite(
aprovacao === "aprovada"
? "Vaga aprovada"
: "Vaga reprovada",
aprovacao === "aprovada"
? "A vaga foi aprovada e liberada no portal."
: "A vaga foi reprovada e retirada da fila de aprova\u00E7\u00E3o.",
"Fechar"
);
})
.catch(function(erro){
console.error(
"EmpregaMais - aprova\u00E7\u00E3o:",
erro
);
mostrarModalSite(
"Aten\u00E7\u00E3o",
"A altera\u00E7\u00E3o apareceu no painel, mas o Google Sheets n\u00E3o confirmou a atualiza\u00E7\u00E3o. Tente novamente.",
"Fechar"
);
});
};
definirDestaqueAdmin =
function(id, ativo){
var hoje =
dataHoje();
var alteracoes = {
destaque:
!!ativo,
destaqueCortesia:
!!ativo,
destaqueOrigem:
ativo
? "admin"
: "",
destaqueInicio:
ativo
? hoje
: "",
fimDestaque:
"",
destaqueConsomePlano:
false
};
var encontrada =
atualizarVagaLocalAdminEmpregaMais(
id,
alteracoes
);
if(!encontrada){
var overrides =
carregarOverridesVagasAdmin();
var chave =
String(id);
if(
!overrides[chave]
){
overrides[chave] =
{};
}
for(
var campo in alteracoes
){
if(
Object.prototype.hasOwnProperty.call(
alteracoes,
campo
)
){
overrides[chave][campo] =
alteracoes[campo];
}
}
salvarOverridesVagasAdmin(
overrides
);
}
atualizarTelasAdminEmpregaMais();
apiEmpregaMaisPost({
acao:
ativo
? "destacar"
: "removerDestaque",
id:id
})
.then(function(resultado){
if(
resultado &&
resultado.sucesso === true
){
mostrarToast(
ativo
? "Vaga colocada em destaque."
: "Destaque removido."
);
}
})
.catch(function(erro){
console.warn(
"EmpregaMais - destaque:",
erro
);
});
};
