function(){},
target:
document.getElementById(
"formPublicarVaga"
) ||
document.getElementById(
"form-publicar-vaga"
) ||
null
};
try{
if(
typeof publicarVagaAntesPreviewUrgenteEmpregaMais ===
"function"
){
