function escolherRegistroMaisAtualEmpregaMais(atual, candidato){
if(!atual){
return candidato;
}
if(!candidato){
return atual;
}
var atualAprovada =
String(atual.aprovacao || "").toLowerCase() === "aprovada";
var candidatoAprovada =
String(candidato.aprovacao || "").toLowerCase() === "aprovada";
if(candidatoAprovada && !atualAprovada){
return candidato;
}
if(atualAprovada && !candidatoAprovada){
return atual;
}
var atualReprovada =
String(atual.aprovacao || "").toLowerCase() === "reprovada";
var candidatoReprovada =
String(candidato.aprovacao || "").toLowerCase() === "reprovada";
if(candidatoReprovada && !atualReprovada && !atualAprovada){
return candidato;
}
if(atualReprovada && !candidatoReprovada && !candidatoAprovada){
return atual;
}
var atualDestaque =
atual.destaque === true ||
String(atual.destaque).toLowerCase() === "true";
var candidatoDestaque =
candidato.destaque === true ||
String(candidato.destaque).toLowerCase() === "true";
if(candidatoDestaque && !atualDestaque){
return candidato;
}
return atual;
}
sincronizarVagasGoogleSheets =
function(){
return apiEmpregaMaisGet(
"listar"
)
.then(function(resultado){
if(
!resultado ||
resultado.sucesso !== true
){
throw new Error(
resultado && resultado.erro
? resultado.erro
: "API indispon\u00EDvel."
);
}
var remotas =
Array.isArray(resultado.vagas)
? resultado.vagas
: [];
var remotasPorId =
{};
var ordemIds =
[];
for(
var r=0;
r<remotas.length;
r++
){
var vr =
remotas[r] || {};
if(!vr.empresaCnpj && vr.cnpj){
vr.empresaCnpj = vr.cnpj;
}
if(!vr.cnpj && vr.empresaCnpj){
vr.cnpj = vr.empresaCnpj;
}
if(!vr.empresaEmail && vr.email){
vr.empresaEmail = vr.email;
}
if(!vr.email && vr.empresaEmail){
vr.email = vr.empresaEmail;
}
var rid =
String(vr.id || "");
if(!rid){
continue;
}
if(
!Object.prototype.hasOwnProperty.call(
remotasPorId,
rid
)
){
remotasPorId[rid] =
vr;
ordemIds.push(
rid
);
}else{
remotasPorId[rid] =
escolherRegistroMaisAtualEmpregaMais(
remotasPorId[rid],
vr
);
}
}
var locais =
[];
try{
locais =
carregarVagasPortal();
}catch(erro){
locais = [];
}
var combinadas =
[];
var mapa =
{};
for(
var i=0;
i<locais.length;
i++
){
var lid =
String(locais[i].id || "");
if(!lid){
continue;
}
if(
Object.prototype.hasOwnProperty.call(
mapa,
lid
)
){
combinadas[
mapa[lid]
] =
escolherRegistroMaisAtualEmpregaMais(
combinadas[mapa[lid]],
locais[i]
);
}else{
mapa[lid] =
combinadas.length;
combinadas.push(
locais[i]
);
}
}
for(
var o=0;
o<ordemIds.length;
o++
){
var id =
ordemIds[o];
var remota =
remotasPorId[id];
if(
Object.prototype.hasOwnProperty.call(
mapa,
id
)
){
var localAntesEM =
combinadas[mapa[id]] || {};
var escolhidaEM =
escolherRegistroMaisAtualEmpregaMais(
localAntesEM,
remota
) || {};
escolhidaEM.empresaCnpj =
escolhidaEM.empresaCnpj ||
escolhidaEM.cnpj ||
localAntesEM.empresaCnpj ||
localAntesEM.cnpj ||
remota.empresaCnpj ||
remota.cnpj ||
"";
escolhidaEM.cnpj =
escolhidaEM.cnpj ||
escolhidaEM.empresaCnpj ||
localAntesEM.cnpj ||
localAntesEM.empresaCnpj ||
remota.cnpj ||
remota.empresaCnpj ||
"";
escolhidaEM.empresaEmail =
escolhidaEM.empresaEmail ||
escolhidaEM.email ||
localAntesEM.empresaEmail ||
localAntesEM.email ||
remota.empresaEmail ||
remota.email ||
"";
escolhidaEM.email =
escolhidaEM.email ||
escolhidaEM.empresaEmail ||
localAntesEM.email ||
localAntesEM.empresaEmail ||
remota.email ||
remota.empresaEmail ||
"";
escolhidaEM.empresa =
escolhidaEM.empresa ||
escolhidaEM.empresaNome ||
localAntesEM.empresa ||
localAntesEM.empresaNome ||
remota.empresa ||
remota.empresaNome ||
"";
combinadas[
mapa[id]
] =
escolhidaEM;
}else{
mapa[id] =
combinadas.length;
combinadas.push(
remota
);
}
}
salvarVagasPortal(
combinadas
);
atualizarTelasAdminEmpregaMais();
return combinadas;
})
.catch(function(erro){
console.error(
"EmpregaMais / Google Sheets:",
erro
);
return [];
});
};
