var cidadesMgEmpregaMaisCarregadas = false;
function carregarCidadesMgEmpregaMais(){
var campo =
document.getElementById(
"cidadeVaga"
);
if(
!campo ||
campo.tagName.toLowerCase() !==
"select"
){
return Promise.resolve();
}
if(cidadesMgEmpregaMaisCarregadas){
return Promise.resolve();
}
var valorAtual =
campo.value || "";
campo.innerHTML =
"<option value=''>Carregando cidades de Minas Gerais...</option>";
return fetch(
"https://servicodados.ibge.gov.br/api/v1/localidades/estados/MG/municipios?orderBy=nome"
)
.then(function(resposta){
if(!resposta.ok){
throw new Error(
"N\u00E3o foi poss\u00EDvel carregar as cidades."
);
}
return resposta.json();
})
.then(function(cidades){
campo.innerHTML =
"<option value=''>Selecione uma cidade de Minas Gerais</option>";
cidades.forEach(
function(cidade){
var opcao =
document.createElement(
"option"
);
opcao.value =
cidade.nome;
opcao.textContent =
cidade.nome;
campo.appendChild(
opcao
);
}
);
cidadesMgEmpregaMaisCarregadas =
true;
if(valorAtual){
campo.value =
valorAtual;
}
})
.catch(function(erro){
console.error(
"EmpregaMais - cidades MG:",
erro
);
campo.innerHTML =
"<option value=''>Selecione a cidade</option>";
[
"Belo Horizonte",
"Betim",
"Contagem",
"Ibirit\u00E9",
"Nova Lima",
"Ribeir\u00E3o das Neves",
"Sabar\u00E1",
"Santa Luzia"
].forEach(
function(nome){
var opcao =
document.createElement(
"option"
);
opcao.value =
nome;
opcao.textContent =
nome;
campo.appendChild(
opcao
);
}
);
});
}
window.addEventListener(
"load",
function(){
setTimeout(
carregarCidadesMgEmpregaMais,
500
);
}
);
document.addEventListener(
"click",
function(){
setTimeout(
carregarCidadesMgEmpregaMais,
150
);
}
);
var estadosBrasilEmpregaMaisCarregados = false;
function obterEstadoSalvoDaVagaEmpregaMais(){
var id =
document.getElementById(
"vagaEditandoId"
);
if(!id || !id.value){
return "";
}
try{
var vagas =
carregarVagasPortal();
for(
var i=0;
i<vagas.length;
i++
){
if(
String(vagas[i].id) ===
String(id.value)
){
return (
vagas[i].estado ||
vagas[i].uf ||
""
);
}
}
}catch(erro){}
return "";
}
function carregarEstadosBrasilEmpregaMais(){
var estado =
document.getElementById(
"estadoVaga"
);
if(!estado){
return Promise.resolve();
}
if(
estadosBrasilEmpregaMaisCarregados &&
estado.options.length > 1
){
return Promise.resolve();
}
estado.innerHTML =
"<option value=''>Carregando estados...</option>";
return fetch(
"https://servicodados.ibge.gov.br/api/v1/localidades/estados?orderBy=nome"
)
.then(function(resposta){
if(!resposta.ok){
throw new Error(
"N\u00E3o foi poss\u00EDvel carregar os estados."
);
}
return resposta.json();
})
.then(function(estados){
estado.innerHTML =
"<option value=''>Selecione o estado</option>";
estados.forEach(
function(item){
var opcao =
document.createElement(
"option"
);
opcao.value =
item.sigla;
opcao.textContent =
item.nome +
" (" +
item.sigla +
")";
opcao.setAttribute(
"data-id-ibge",
item.id
);
estado.appendChild(
opcao
);
}
);
estadosBrasilEmpregaMaisCarregados =
true;
})
.catch(function(erro){
console.error(
"EmpregaMais - estados:",
erro
);
estado.innerHTML =
"<option value=''>N\u00E3o foi poss\u00EDvel carregar os estados</option>";
});
}
function carregarCidadesPorEstadoEmpregaMais(
uf,
cidadeSelecionada
){
var cidade =
document.getElementById(
"cidadeVaga"
);
if(!cidade){
return Promise.resolve();
}
if(!uf){
cidade.disabled =
true;
cidade.innerHTML =
"<option value=''>Selecione primeiro o estado</option>";
return Promise.resolve();
}
cidade.disabled =
true;
cidade.innerHTML =
"<option value=''>Carregando cidades...</option>";
return fetch(
"https://servicodados.ibge.gov.br/api/v1/localidades/estados/" +
encodeURIComponent(uf) +
"/municipios?orderBy=nome"
)
.then(function(resposta){
if(!resposta.ok){
throw new Error(
"N\u00E3o foi poss\u00EDvel carregar as cidades."
);
}
return resposta.json();
})
.then(function(cidades){
cidade.innerHTML =
"<option value=''>Selecione a cidade</option>";
cidades.forEach(
function(item){
var opcao =
document.createElement(
"option"
);
opcao.value =
item.nome;
opcao.textContent =
item.nome;
cidade.appendChild(
opcao
);
}
);
cidade.disabled =
false;
if(cidadeSelecionada){
cidade.value =
cidadeSelecionada;
}
})
.catch(function(erro){
console.error(
"EmpregaMais - cidades:",
erro
);
cidade.innerHTML =
"<option value=''>N\u00E3o foi poss\u00EDvel carregar as cidades</option>";
});
}
function instalarLocalizacaoBrasilEmpregaMais(){
var estado =
document.getElementById(
"estadoVaga"
);
var cidade =
document.getElementById(
"cidadeVaga"
);
if(!estado || !cidade){
return;
}
cidadesMgEmpregaMaisCarregadas =
true;
carregarEstadosBrasilEmpregaMais()
.then(function(){
if(
estado.getAttribute(
"data-evento-brasil"
) !== "1"
){
estado.setAttribute(
"data-evento-brasil",
"1"
);
estado.addEventListener(
"change",
function(){
carregarCidadesPorEstadoEmpregaMais(
estado.value,
""
);
}
);
}
});
}
var preencherFormularioEdicaoLocalizacaoBrasilEmpregaMais =
preencherFormularioEdicao;
