function(vaga){
preencherFormularioEdicaoLocalizacaoBrasilEmpregaMais(
vaga
);
instalarLocalizacaoBrasilEmpregaMais();
setTimeout(
function(){
var estado =
document.getElementById(
"estadoVaga"
);
if(!estado){
return;
}
var uf =
vaga.estado ||
vaga.uf ||
"";
if(
!uf &&
[
"Belo Horizonte",
"Betim",
"Contagem",
"Ibirit\u00E9",
"Nova Lima",
"Ribeir\u00E3o das Neves",
"Sabar\u00E1",
"Santa Luzia"
].indexOf(
vaga.cidade
) !== -1
){
uf =
"MG";
}
if(uf){
estado.value =
uf;
carregarCidadesPorEstadoEmpregaMais(
uf,
vaga.cidade || ""
);
}
},
350
);
};
var publicarVagaLocalizacaoBrasilEmpregaMais =
publicarVaga;
publicarVaga =
function(event){
var estado =
document.getElementById(
"estadoVaga"
);
var uf =
estado
? estado.value
: "";
var antes =
[];
try{
antes =
carregarVagasPortal();
}catch(erro){
antes = [];
}
var idsAntes =
{};
for(
var i=0;
i<antes.length;
i++
){
idsAntes[
String(antes[i].id || "")
] =
true;
}
var retorno =
publicarVagaLocalizacaoBrasilEmpregaMais(
event
);
setTimeout(
function(){
var vagas =
[];
try{
vagas =
carregarVagasPortal();
}catch(erro){
vagas = [];
}
var mudou =
false;
for(
var j=vagas.length-1;
j>=0;
j--
){
var id =
String(
vagas[j].id || ""
);
if(
id &&
!idsAntes[id]
){
vagas[j].estado =
uf;
vagas[j].uf =
uf;
mudou =
true;
break;
}
}
if(mudou){
salvarVagasPortal(
vagas
);
}
},
250
);
return retorno;
};
