function padronizarTituloVagaEmpregaMais(titulo){
if(!titulo){
return "";
}
var texto =
String(titulo)
.trim()
.toLocaleLowerCase("pt-BR");
var minusculas = {
"a":true,
"as":true,
"o":true,
"os":true,
"de":true,
"da":true,
"das":true,
"do":true,
"dos":true,
"e":true,
"em":true,
"na":true,
"nas":true,
"no":true,
"nos":true,
"para":true,
"por":true
};
var especiais = {
"rh":"RH",
"ti":"TI",
"t.i.":"TI",
"pj":"PJ",
"clt":"CLT",
"pcd":"PCD",
"cnpj":"CNPJ",
"seo":"SEO",
"crm":"CRM",
"erp":"ERP",
"sac":"SAC",
"b2b":"B2B",
"b2c":"B2C",
"e-commerce":"E-commerce",
"ecommerce":"E-commerce"
};
var palavras =
texto.split(/\s+/);
return palavras.map(
function(palavra, indice){
var correspondencia =
palavra.match(
/^(.+?)([,.!?;:]*)$/
);
var base =
correspondencia
? correspondencia[1]
: palavra;
var pontuacao =
correspondencia
? correspondencia[2]
: "";
if(
Object.prototype.hasOwnProperty.call(
especiais,
base
)
){
return especiais[base] + pontuacao;
}
if(
indice > 0 &&
minusculas[base]
){
return base + pontuacao;
}
var partes =
base.split("-");
var formatada =
partes.map(
function(parte){
if(!parte){
return parte;
}
if(
Object.prototype.hasOwnProperty.call(
especiais,
parte
)
){
return especiais[parte];
}
return (
parte.charAt(0)
.toLocaleUpperCase("pt-BR") +
parte.slice(1)
);
}
).join("-");
return formatada + pontuacao;
}
).join(" ");
}
function aplicarTitulosPadronizadosEmpregaMais(){
var seletores = [
".vaga-titulo",
".job-title",
".titulo-vaga",
".card-destaque .vaga-titulo",
".vaga-card .vaga-titulo",
"[data-vaga-titulo]"
];
var elementos =
document.querySelectorAll(
seletores.join(",")
);
for(
var i=0;
i<elementos.length;
i++
){
var elemento =
elementos[i];
if(
elemento.tagName === "INPUT" ||
elemento.tagName === "TEXTAREA"
){
continue;
}
var original =
elemento.textContent || "";
var formatado =
padronizarTituloVagaEmpregaMais(
original
);
if(
formatado &&
original !== formatado
){
elemento.textContent =
formatado;
}
}
}
