window._timerTitulosEmpregaMais
);
window._timerTitulosEmpregaMais =
setTimeout(
aplicarTitulosPadronizadosEmpregaMais,
50
);
}
);
observadorTitulosEmpregaMais.observe(
document.body,
{
childList:true,
subtree:true
}
);
}
);
