function renderizarEmpresasDestaqueLateralEmpregaMais(){
var params=new URLSearchParams(window.location.search);
if(params.get("pagina")==="vaga"){return;}
var lateral=
document.querySelector(".filtros-lateral") ||
document.querySelector(".sidebar-filtros") ||
document.querySelector(".filtros") ||
document.querySelector("aside");
if(!lateral){return;}
var existente=document.getElementById("empresasDestaqueLateralEmpregaMais");
if(existente){existente.remove();}
var vagas=[];
try{
vagas=carregarVagasPortal();
}catch(e){return;}
var destaques=vagas.filter(function(v){
var aprovado=String(v.aprovacao || "").toLowerCase()==="aprovada";
var ativo=String(v.status || "ativa").toLowerCase()!=="encerrada";
var destaque=v.destaque===true || String(v.destaque).toLowerCase()==="true";
return aprovado && ativo && destaque;
});
if(!destaques.length){return;}
var vistos={};
destaques=destaques.filter(function(v){
var chave=String(v.cnpj || v.empresaCnpj || v.empresa || "").toLowerCase();
if(vistos[chave]){return false;}
vistos[chave]=true;
return true;
}).slice(0,4);
var box=document.createElement("section");
box.id="empresasDestaqueLateralEmpregaMais";
box.className="empresas-destaque-lateral-em";
var titulo=document.createElement("h3");
titulo.textContent="Empresas em destaque";
box.appendChild(titulo);
var sub=document.createElement("p");
sub.className="subtitulo-em";
sub.textContent="Conhe\u00E7a empresas com oportunidades em destaque";
box.appendChild(sub);
destaques.forEach(function(vaga){
var item=document.createElement("div");
item.className="empresa-destaque-item-em";
item.appendChild(criarLogoEmpresaDestaqueEmpregaMais(vaga));
var info=document.createElement("div");
info.className="empresa-destaque-info-em";
var nome=document.createElement("div");
nome.className="empresa-destaque-nome-em";
nome.textContent=vaga.empresa || "Empresa";
if(vaga.empresaVerificada || vaga.verificada){
var selo=document.createElement("span");
selo.className="empresa-destaque-verificada-em";
selo.textContent="\u25CF";
selo.title="Empresa verificada";
nome.appendChild(selo);
}
var cargo=document.createElement("div");
cargo.className="empresa-destaque-cargo-em";
cargo.textContent=padronizarTituloVagaEmpregaMais(vaga.cargo || vaga.titulo || "Ver oportunidade");
var meta=document.createElement("div");
meta.className="empresa-destaque-meta-em";
meta.textContent=(vaga.cidade ? vaga.cidade + (vaga.uf || vaga.estado ? " / " + (vaga.uf || vaga.estado) : "") : "") +
(vaga.modalidade ? " \u2022 " + vaga.modalidade : "");
info.appendChild(nome);
info.appendChild(cargo);
if(meta.textContent){info.appendChild(meta);}
item.appendChild(info);
item.addEventListener("click",function(){
if(vaga.id){
window.location.href="?pagina=vaga&id="+encodeURIComponent(vaga.id);
}
});
box.appendChild(item);
});
lateral.appendChild(box);
}
