function sofisticarPainelEmpresaEmpregaMais(){
var pagina=document.getElementById("pagina-painel-empresa");
if(!pagina){return;}
var titulos=pagina.querySelectorAll("h2,h3");
for(var i=0;i<titulos.length;i++){
var el=titulos[i];
var t=(el.textContent||"").trim().toLowerCase();
if(
t.indexOf("vagas em an\u00E1lise")!==-1 ||
t.indexOf("vagas em analise")!==-1 ||
t.indexOf("vagas publicadas")!==-1 ||
t.indexOf("minhas vagas")!==-1
){
var pai=el.parentElement;
if(pai){pai.classList.add("painel-titulo-premium-em");}
}
}
var walker=document.createTreeWalker(pagina,NodeFilter.SHOW_TEXT);
var no;
while((no=walker.nextNode())){
if(no.nodeValue && /Essencial\s+\d+\s*\/\s*5\b/i.test(no.nodeValue)){
no.nodeValue=no.nodeValue.replace(
/(Essencial\s+)(\d+)(\s*\/\s*)5\b/ig,
"$1$2$3100"
);
}
}
if(!document.getElementById("painelUsoPlanoEmpregaMais")){
var texto=pagina.textContent||"";
var match=texto.match(/Essencial\s+(\d+)\s*\/\s*(?:5|100)\b/i);
if(match){
var usadas=parseInt(match[1],10)||0;
var limite=100;
var pct=Math.min(100,Math.round((usadas/limite)*100));
var bloco=document.createElement("div");
bloco.id="painelUsoPlanoEmpregaMais";
bloco.className="painel-uso-plano-em";
bloco.innerHTML=
'<div class="painel-uso-plano-topo-em">'+
'<strong>Uso do Plano Essencial</strong>'+
'<span>'+usadas+' / '+limite+' vagas</span>'+
'</div>'+
'<div class="painel-uso-plano-barra-em">'+
'<div class="painel-uso-plano-progresso-em" style="width:'+pct+'%"></div>'+
'</div>'+
'<small class="painel-uso-plano-legenda-em">'+
usadas+' de '+limite+' vagas utilizadas neste m\u00EAs'+
'</small>';
var alvo=null;
