function organizarHomeRealEmpregaMais(){
var pagina=document.getElementById("pagina-home");
if(!pagina){return;}
var nomes=[
"vagas em destaque",
"vagas mais recentes",
"encontre vagas por \u00E1rea",
"empresas que est\u00E3o contratando"
];
var titulos=pagina.querySelectorAll("h2,h3");
for(var i=0;i<titulos.length;i++){
var t=(titulos[i].textContent||"").trim().toLowerCase();
if(nomes.indexOf(t)!==-1){
var pai=titulos[i].parentElement;
if(pai){
pai.style.setProperty("text-align","center","important");
if(pai.classList.contains("titulo-secao")){
pai.style.setProperty("display","flex","important");
pai.style.setProperty("flex-direction","column","important");
pai.style.setProperty("align-items","center","important");
}
}
titulos[i].style.setProperty("text-align","center","important");
}
}
var tituloEmpresas=null;
var tituloDestaques=null;
for(var j=0;j<titulos.length;j++){
var tx=(titulos[j].textContent||"").trim().toLowerCase();
if(tx==="empresas que est\u00E3o contratando"){tituloEmpresas=titulos[j];}
if(tx==="vagas em destaque"){tituloDestaques=titulos[j];}
}
if(tituloEmpresas && tituloDestaques){
var secEmp=tituloEmpresas.closest("section");
var secDest=tituloDestaques.closest("section");
if(secEmp && secDest && secEmp!==secDest && secDest.parentElement){
secDest.parentElement.insertBefore(secEmp,secDest);
}
}
}
