],"Escolher Semestral","semestral",true)+
planoCardNovoEM("Anual","12 meses","R$ 239,90","300 vagas",[
["sim","Painel completo do recrutador"],["sim","Empresa Verificada apos validacao"],["sim","Pagina Exclusiva da Empresa"],
["sim","Perfil institucional, cultura e beneficios"],["sim","Gestao completa de candidatos"],["sim","Estatisticas completas"],
