function planoCardNovoEM(nome,periodo,preco,vagas,recursos,botao,chave,recomendado){
var itens="";
for(var i=0;i<recursos.length;i++){
var tipoRecurso=recursos[i][0];
var classeRecurso=tipoRecurso==="nao"?"nao-em":(tipoRecurso==="especial"?"especial-em":"");
var iconeRecurso=tipoRecurso==="nao"?"\u00D7":"\u2713";
var complemento=tipoRecurso==="especial"?
'<small>Recrutamento sigiloso para processos que exigem discri\u00E7\u00E3o, inclusive quando a empresa precisa buscar um substituto sem expor antecipadamente a movimenta\u00E7\u00E3o interna.</small>':'';
itens+='<div class="plano-recurso-novo-em '+classeRecurso+'"><b>'+iconeRecurso+'</b><span>'+recursos[i][1]+complemento+'</span></div>';
}
return '<article class="plano-card-novo-em '+(recomendado?"plano-recomendado-em":"")+'">'+
(recomendado?'<span class="plano-selo-novo-em">MAIS ESCOLHIDO</span>':'')+
'<div class="plano-nome-novo-em">'+nome+'</div><div class="plano-periodo-novo-em">'+periodo+'</div>'+
'<div class="plano-preco-novo-em">'+preco+'</div><div class="plano-vagas-novo-em">'+vagas+' durante a vig\u00EAncia</div>'+
'<div class="plano-recursos-novo-em">'+itens+'</div>'+
'<button class="plano-mais-info-v16" type="button" data-info-plano-v16="'+chave+'">Mais informacoes</button>'+
'<button class="plano-btn-novo-em" type="button" data-plano-em="'+chave+'">'+botao+'</button></article>';
}
