}
}
}
var tipo=document.getElementById("tipoContatoVaga") ||
document.querySelector('[name="tipoContato"]') ||
document.querySelector('#pagina-publicar select[id*="Contato"]');
if(tipo && !plano.candidatura.includes("whatsapp")){
var opts=tipo.options;
for(var i=0;i<opts.length;i++){
var val=(opts[i].value+" "+opts[i].textContent).toLowerCase();
if(val.indexOf("whatsapp")>=0 || val.indexOf("link")>=0 || val.indexOf("site")>=0 || val.indexOf("portal")>=0){
opts[i].disabled=true;
}
}
for(var j=0;j<opts.length;j++){
if((opts[j].value+" "+opts[j].textContent).toLowerCase().indexOf("mail")>=0){
tipo.selectedIndex=j; break;
}
}
tipo.dispatchEvent(new Event("change",{bubbles:true}));
}
}
