function adicionarBotaoVerVagaAdminEmpregaMais(){
var pagina=document.getElementById("pagina-admin");
if(!pagina) return;
var titulos=pagina.querySelectorAll("h1,h2,h3,strong");
var area=null;
for(var i=0;i<titulos.length;i++){
var tx=(titulos[i].textContent||"").trim().toLowerCase();
if(tx.indexOf("vagas aguardando aprova\u00E7\u00E3o")>=0 ||
tx.indexOf("vagas aguardando aprovacao")>=0){
area=titulos[i].parentElement;
while(area && area!==pagina){
if(area.querySelectorAll("button").length>=1) break;
area=area.parentElement;
}
break;
}
}
if(!area) return;
var botoes=area.querySelectorAll("button");
for(var b=0;b<botoes.length;b++){
var aprovar=botoes[b];
var texto=(aprovar.textContent||"").trim().toLowerCase();
if(texto!=="aprovar") continue;
var card=aprovar.parentElement;
while(card && card!==area){
var t=(card.textContent||"").toLowerCase();
if(t.indexOf("aprovar")>=0 && t.indexOf("reprovar")>=0) break;
card=card.parentElement;
}
if(!card || card===area || card.querySelector(".btn-ver-vaga-admin-em")) continue;
var acoes=aprovar.parentElement;
var btn=document.createElement("button");
btn.type="button";
btn.className="btn-ver-vaga-admin-em";
btn.innerHTML="\uD83D\uDC41 Ver vaga";
(function(cardAtual){
btn.addEventListener("click",function(){
var id="";
var bs=cardAtual.querySelectorAll("button");
for(var x=0;x<bs.length;x++){
var onclick=bs[x].getAttribute("onclick")||"";
var m=onclick.match(/vaga_[0-9]+/);
if(m){ id=m[0]; break; }
}
if(!id){
var html=cardAtual.outerHTML||"";
var m2=html.match(/vaga_[0-9]+/);
if(m2) id=m2[0];
}
if(id){
var url=window.location.origin+window.location.pathname+"?pagina=vaga&id="+encodeURIComponent(id);
window.open(url,"_blank","noopener");
return;
}
var tituloEl=cardAtual.querySelector("h2,h3,strong");
var titulo=tituloEl?(tituloEl.textContent||"").trim():"";
var vagas=[];
try{
vagas=JSON.parse(localStorage.getItem("vagasEmpregaMais")||"[]");
}catch(e){}
var vaga=vagas.find(function(v){
return String(v.cargo||v.titulo||"").trim()===titulo;
});
if(vaga && vaga.id){
var url2=window.location.origin+window.location.pathname+"?pagina=vaga&id="+encodeURIComponent(vaga.id);
window.open(url2,"_blank","noopener");
}else{
alert("N\u00E3o foi poss\u00EDvel localizar o ID desta vaga.");
}
});
})(card);
acoes.insertBefore(btn,aprovar);
}
}
