: null;
function identidadeEmpresaLogadaFinalEM(){
var empresa = null;
try{
empresa =
JSON.parse(
sessionStorage.getItem("empresaLogada") ||
localStorage.getItem("empresaLogada") ||
"null"
);
}catch(e){}
empresa = empresa || {};
var cnpj =
String(
empresa.cnpj ||
empresa.empresaCnpj ||
sessionStorage.getItem("empresaCnpj") ||
localStorage.getItem("empresaCnpj") ||
sessionStorage.getItem("cnpjEmpresa") ||
localStorage.getItem("cnpjEmpresa") ||
""
).replace(/\D/g,"");
var email =
String(
empresa.email ||
empresa.empresaEmail ||
sessionStorage.getItem("empresaEmail") ||
localStorage.getItem("empresaEmail") ||
""
).trim().toLowerCase();
var nome =
String(
empresa.nome ||
empresa.empresa ||
sessionStorage.getItem("empresaNome") ||
localStorage.getItem("empresaNome") ||
""
).trim().toLowerCase();
return {
cnpj:cnpj,
email:email,
nome:nome
};
}
function vagaPertenceEmpresaFinalEM(vaga, identidade){
vaga = vaga || {};
identidade = identidade || identidadeEmpresaLogadaFinalEM();
var cnpjVaga =
String(
vaga.empresaCnpj ||
vaga.cnpj ||
""
).replace(/\D/g,"");
var emailVaga =
String(
vaga.empresaEmail ||
vaga.email ||
""
).trim().toLowerCase();
var nomeVaga =
String(
vaga.empresa ||
vaga.empresaNome ||
""
).trim().toLowerCase();
if(
identidade.cnpj &&
cnpjVaga &&
identidade.cnpj === cnpjVaga
){
return true;
}
if(
identidade.email &&
emailVaga &&
identidade.email === emailVaga
){
return true;
}
if(
identidade.nome &&
nomeVaga &&
identidade.nome === nomeVaga
){
return true;
}
return false;
}
function vagasDaEmpresa(){
var todas =
typeof carregarVagasPortal === "function"
? carregarVagasPortal()
: [];
if(!Array.isArray(todas)){
todas = [];
}
var identidade =
identidadeEmpresaLogadaFinalEM();
var retorno = [];
for(var i=0;i<todas.length;i++){
var vaga = todas[i] || {};
if(
vagaPertenceEmpresaFinalEM(
vaga,
identidade
)
){
if(!vaga.empresaCnpj && vaga.cnpj){
vaga.empresaCnpj = vaga.cnpj;
}
if(!vaga.cnpj && vaga.empresaCnpj){
vaga.cnpj = vaga.empresaCnpj;
}
if(!vaga.empresaEmail && vaga.email){
vaga.empresaEmail = vaga.email;
}
if(!vaga.email && vaga.empresaEmail){
vaga.email = vaga.empresaEmail;
}
retorno.push(vaga);
}
}
return retorno;
}
