function renderizarEmpresasContratandoCarrosselEM(){
var faixa=document.getElementById("empresasContratandoFaixaEM");
var track=document.getElementById("empresasContratandoTrackEM");
if(!faixa || !track){
return;
}
var vagas=[];
if(typeof todasAsVagasPublicas === "function"){
vagas=todasAsVagasPublicas() || [];
}else if(typeof carregarVagasPortal === "function"){
vagas=carregarVagasPortal() || [];
}
var empresas=[];
var usadas={};
for(var i=0;i<vagas.length;i++){
var vaga=vagas[i] || {};
var logo=String(vaga.logo || "").trim();
if(!logo){
continue;
}
var nome=String(vaga.empresa || vaga.nomeEmpresa || "").trim();
var cnpj=String(vaga.empresaCnpj || vaga.cnpj || "").replace(/\D/g,"");
var email=String(vaga.empresaEmail || vaga.email || "").trim().toLowerCase();
var chave=cnpj || email || nome.toLowerCase();
if(!chave || usadas[chave]){
continue;
}
usadas[chave]=true;
empresas.push({
nome:nome || "Empresa",
logo:logo,
cnpj:cnpj
});
}
track.innerHTML="";
if(!empresas.length){
faixa.style.display="none";
return;
}
faixa.style.display="block";
var repeticoes=empresas.length < 5 ? 4 : 2;
for(var r=0;r<repeticoes;r++){
for(var e=0;e<empresas.length;e++){
(function(empresa){
var item=document.createElement("div");
item.className="empresa-logo-carrossel-em";
item.title=empresa.nome;
var img=document.createElement("img");
img.src=empresa.logo;
img.alt="Logo "+empresa.nome;
img.loading="lazy";
item.appendChild(img);
if(empresa.cnpj){
item.onclick=function(){
if(typeof irPara === "function"){
irPara("empresa-publica",empresa.cnpj);
}else{
window.location.href="?pagina=empresa-publica&id="+encodeURIComponent(empresa.cnpj);
}
};
}
track.appendChild(item);
})(empresas[e]);
}
}
}
