var paginaVagasEM = 0;
var vagasPorPaginaEM = 10;
function aplicarPaginacaoVagasEM(){
var lista=document.getElementById("listaVagas");
var paginacao=document.getElementById("paginacaoVagasEM");
if(!lista || !paginacao){
return;
}
var todos=lista.querySelectorAll(".vaga-card");
var elegiveis=[];
for(var i=0;i<todos.length;i++){
var ocultoFiltro =
todos[i].getAttribute("data-oculto-filtro-em") === "1";
if(!ocultoFiltro){
elegiveis.push(todos[i]);
}
}
var totalPaginas=Math.max(
1,
Math.ceil(elegiveis.length/vagasPorPaginaEM)
);
if(paginaVagasEM >= totalPaginas){
paginaVagasEM=totalPaginas-1;
}
if(paginaVagasEM < 0){
paginaVagasEM=0;
}
for(var t=0;t<todos.length;t++){
todos[t].style.setProperty("display","none","important");
}
var inicio=paginaVagasEM*vagasPorPaginaEM;
var fim=inicio+vagasPorPaginaEM;
for(var e=0;e<elegiveis.length;e++){
if(e>=inicio && e<fim){
elegiveis[e].style.setProperty("display","flex","important");
}
}
paginacao.innerHTML="";
if(totalPaginas<=1){
paginacao.style.display="none";
return;
}
paginacao.style.display="flex";
function botao(rotulo,pagina,classe,desabilitado){
var b=document.createElement("button");
b.type="button";
b.textContent=rotulo;
if(classe){b.className=classe;}
b.disabled=!!desabilitado;
b.onclick=function(){
paginaVagasEM=pagina;
aplicarPaginacaoVagasEM();
var alvo=document.getElementById("vagas");
if(alvo){
alvo.scrollIntoView({behavior:"smooth",block:"start"});
}
};
paginacao.appendChild(b);
}
botao("\u2039",paginaVagasEM-1,"",paginaVagasEM===0);
for(var p=0;p<totalPaginas;p++){
botao(
String(p+1),
p,
p===paginaVagasEM ? "ativo" : "",
false
);
}
botao("\u203A",paginaVagasEM+1,"",paginaVagasEM===totalPaginas-1);
}
function sincronizarFiltroEPaginacaoVagasEM(){
var lista=document.getElementById("listaVagas");
if(!lista){return;}
var cards=lista.querySelectorAll(".vaga-card");
for(var i=0;i<cards.length;i++){
var display=window.getComputedStyle(cards[i]).display;
if(!cards[i].hasAttribute("data-paginado-em")){
cards[i].setAttribute(
"data-oculto-filtro-em",
display==="none" ? "1" : "0"
);
}
cards[i].setAttribute("data-paginado-em","1");
}
aplicarPaginacaoVagasEM();
}
