function garantirLogosPreviaHomeEM(){
var lista=document.getElementById("listaVagas");
if(!lista){return;}
var vagas=[];
if(typeof todasAsVagasPublicas==="function"){
vagas=todasAsVagasPublicas() || [];
}else if(typeof carregarVagasPortal==="function"){
vagas=carregarVagasPortal() || [];
}
var cards=lista.querySelectorAll(".vaga-card");
for(var c=0;c<cards.length;c++){
var card=cards[c];
if(card.querySelector(".logo-empresa,.logo-placeholder")){
continue;
}
var vaga=null;
var id=
card.getAttribute("data-id") ||
card.getAttribute("data-vaga-id") ||
"";
if(id){
for(var v=0;v<vagas.length;v++){
if(String(vagas[v].id)===String(id)){
vaga=vagas[v];
break;
}
}
}
if(!vaga){
var empresaEl=card.querySelector(".vaga-empresa");
var tituloEl=card.querySelector(".vaga-titulo");
var empresaTxt=empresaEl ? empresaEl.textContent.trim().toLowerCase() : "";
var tituloTxt=tituloEl ? tituloEl.textContent.trim().toLowerCase() : "";
for(var x=0;x<vagas.length;x++){
var emp=String(vagas[x].empresa || vagas[x].nomeEmpresa || "").trim().toLowerCase();
var tit=String(vagas[x].cargo || vagas[x].titulo || "").trim().toLowerCase();
if(emp===empresaTxt && tit===tituloTxt){
vaga=vagas[x];
break;
}
}
}
if(!vaga){continue;}
var top=card.querySelector(".vaga-card-top");
var principal=card.querySelector(".vaga-principal");
if(!top){
top=document.createElement("div");
top.className="vaga-card-top";
if(principal){
card.insertBefore(top,card.firstChild);
top.appendChild(principal);
}else{
continue;
}
}
var logo=String(vaga.logo || "").trim();
var elemento;
if(logo){
elemento=document.createElement("img");
elemento.className="logo-empresa";
elemento.src=logo;
elemento.alt="Logo "+String(vaga.empresa || "empresa");
elemento.loading="lazy";
}else{
elemento=document.createElement("div");
elemento.className="logo-placeholder";
var nome=String(vaga.empresa || "E").trim();
elemento.textContent=nome ? nome.charAt(0).toUpperCase() : "E";
}
if(principal && principal.parentNode===top){
top.insertBefore(elemento,principal);
}else{
top.insertBefore(elemento,top.firstChild);
}
}
}
