var coordenadasCepVagaEM=null;
var localizacaoCandidatoEM=null;
function mascaraCepEM(valor){
var n=String(valor||"").replace(/\D/g,"").slice(0,8);
return n.length>5 ? n.slice(0,5)+"-"+n.slice(5) : n;
}
async function localizarCepEM(cep){
var n=String(cep||"").replace(/\D/g,"");
if(n.length!==8){return null;}
try{
var r=await fetch("https://brasilapi.com.br/api/cep/v2/"+n);
if(!r.ok){return null;}
var d=await r.json();
var c=d && d.location && d.location.coordinates;
if(!c){return null;}
var lat=parseFloat(c.latitude), lng=parseFloat(c.longitude);
if(!isFinite(lat)||!isFinite(lng)){return null;}
return {
cep:n,latitude:lat,longitude:lng,
cidade:d.city||"",uf:d.state||"",
rua:d.street||d.address||"",
bairro:d.neighborhood||""
};
}catch(e){return null;}
}
function instalarCepVagaEM(){
var input=document.getElementById("cepVaga");
var status=document.getElementById("cepStatusEM");
if(!input || input.dataset.cepEm==="1"){return;}
input.dataset.cepEm="1";
input.addEventListener("input",function(){
input.value=mascaraCepEM(input.value);
coordenadasCepVagaEM=null;
if(status){status.textContent="";}
});
input.addEventListener("blur",async function(){
var n=input.value.replace(/\D/g,"");
if(n.length!==8){return;}
if(status){status.style.color="#667b8f";status.textContent="Localizando CEP...";}
var geo=await localizarCepEM(n);
coordenadasCepVagaEM=geo;
if(geo && typeof preencherEnderecoCepV130==="function"){
preencherEnderecoCepV130(geo);
}
if(status){
if(geo){
status.style.color="#13804d";
status.textContent="CEP localizado"+(geo.rua?" — "+geo.rua:"")+(geo.bairro?" · "+geo.bairro:"")+(geo.cidade?" · "+geo.cidade+"/"+geo.uf:"");
}else{
status.style.color="#a96b00";
status.textContent="N\u00E3o foi poss\u00EDvel localizar este CEP.";
}
}
});
}
function distanciaHaversineEM(lat1,lon1,lat2,lon2){
function rad(x){return x*Math.PI/180;}
var R=6371,dLat=rad(lat2-lat1),dLon=rad(lon2-lon1);
var a=Math.sin(dLat/2)**2+Math.cos(rad(lat1))*Math.cos(rad(lat2))*Math.sin(dLon/2)**2;
return R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));
}
function textoDistanciaEM(km){
if(km<1){return Math.max(1,Math.round(km*1000))+" m de voc\u00EA";}
if(km<10){return km.toFixed(1).replace(".",",")+" km de voc\u00EA";}
return Math.round(km)+" km de voc\u00EA";
}
function vagaCorrespondenteCardDistanciaEM(card,vagas){
