var titulo=(card.getAttribute("data-titulo")||"").trim().toLowerCase();
for(var i=0;i<vagas.length;i++){
if(String(vagas[i].empresa||"").trim().toLowerCase()===empresa &&
String(vagas[i].cargo||"").trim().toLowerCase()===titulo){return vagas[i];}
}
return null;
}
