function timestampPublicacaoEmpregaMais(vaga){
if(!vaga){ return 0; }
var valor =
vaga.dataPublicacao ||
vaga.data ||
vaga.criadoEm ||
vaga.createdAt ||
vaga.atualizadoEm ||
"";
if(valor){
var direto = Date.parse(valor);
if(!isNaN(direto)){
return direto;
}
var m = String(valor).match(
/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?$/
);
if(m){
return new Date(
parseInt(m[3],10),
parseInt(m[2],10)-1,
parseInt(m[1],10),
parseInt(m[4]||"0",10),
parseInt(m[5]||"0",10),
parseInt(m[6]||"0",10)
).getTime();
}
}
var id = String(vaga.id || "");
var numeros = id.match(/(\d{10,13})/);
if(numeros){
var n = parseInt(numeros[1],10);
if(numeros[1].length===10){
n = n*1000;
}
return n;
}
return 0;
}
function ordenarVagasMaisRecentesEmpregaMais(vagas){
if(!Array.isArray(vagas)){
return vagas;
}
return vagas.sort(function(a,b){
var dataB = timestampPublicacaoEmpregaMais(b);
var dataA = timestampPublicacaoEmpregaMais(a);
if(dataB !== dataA){
return dataB - dataA;
}
return String(b.id || "").localeCompare(
String(a.id || ""),
"pt-BR",
{numeric:true}
);
});
}
if(typeof todasAsVagasPublicas === "function"){
var todasAsVagasPublicasAntesOrdemEM =
todasAsVagasPublicas;
todasAsVagasPublicas =
function(){
var vagas =
todasAsVagasPublicasAntesOrdemEM
.apply(this,arguments);
if(!Array.isArray(vagas)){
return vagas;
}
return ordenarVagasMaisRecentesEmpregaMais(
vagas.slice()
);
};
}
function reordenarCardsHomePorPostagemEM(){
var lista =
document.getElementById(
"listaVagas"
);
if(!lista){
return;
}
var vagas =
typeof todasAsVagasPublicas === "function"
? (todasAsVagasPublicas() || [])
: [];
ordenarVagasMaisRecentesEmpregaMais(
vagas
);
var cards =
Array.prototype.slice.call(
lista.querySelectorAll(
".vaga-card"
)
);
cards.sort(function(cardA,cardB){
function achar(card){
var empresa =
String(
card.getAttribute("data-empresa") || ""
).trim().toLowerCase();
var cargo =
String(
card.getAttribute("data-titulo") || ""
).trim().toLowerCase();
for(var i=0;i<vagas.length;i++){
if(
String(vagas[i].empresa || "")
.trim().toLowerCase() === empresa &&
String(vagas[i].cargo || "")
.trim().toLowerCase() === cargo
){
return vagas[i];
}
}
return null;
}
return (
timestampPublicacaoEmpregaMais(
achar(cardB)
) -
timestampPublicacaoEmpregaMais(
achar(cardA)
)
);
});
for(var i=0;i<cards.length;i++){
lista.appendChild(cards[i]);
}
if(
typeof aplicarPaginacaoVagasEM ===
"function"
){
paginaVagasEM = 0;
setTimeout(
