);
var coordenadasCepCandidatoCadastroEM=null;
var coordenadasCepCandidatoPerfilEM=null;
function mascaraCepCandidatoEM(v){
var n=String(v||"").replace(/\D/g,"").slice(0,8);
return n.length>5?n.slice(0,5)+"-"+n.slice(5):n;
}
async function geocodificarCepCandidatoEM(cep){
var n=String(cep||"").replace(/\D/g,"");
if(n.length!==8){return null;}
try{
var r=await fetch("https://brasilapi.com.br/api/cep/v2/"+n);
if(!r.ok){return null;}
var d=await r.json(),c=d&&d.location&&d.location.coordinates;
if(!c){return null;}
var lat=parseFloat(c.latitude),lng=parseFloat(c.longitude);
if(!isFinite(lat)||!isFinite(lng)){return null;}
return {cep:n,latitude:lat,longitude:lng,cidade:d.city||"",uf:d.state||""};
}catch(e){return null;}
}
function instalarCampoCepCandidatoEM(id,statusId,tipo){
var input=document.getElementById(id),status=document.getElementById(statusId);
if(!input||input.dataset.cepCandEm==="1"){return;}
input.dataset.cepCandEm="1";
input.addEventListener("input",function(){
input.value=mascaraCepCandidatoEM(input.value);
if(tipo==="cadastro"){coordenadasCepCandidatoCadastroEM=null;}
else{coordenadasCepCandidatoPerfilEM=null;}
if(status){status.textContent="";}
});
input.addEventListener("blur",async function(){
var n=input.value.replace(/\D/g,"");
if(n.length!==8){return;}
if(status){status.style.color="#667b8f";status.textContent="Localizando CEP...";}
var geo=await geocodificarCepCandidatoEM(n);
if(tipo==="cadastro"){coordenadasCepCandidatoCadastroEM=geo;}
else{coordenadasCepCandidatoPerfilEM=geo;}
if(status){
if(geo){
status.style.color="#13804d";
status.textContent="\u2713 CEP localizado"+(geo.cidade?" \u2014 "+geo.cidade+"/"+geo.uf:"");
}else{
status.style.color="#a96b00";
status.textContent="N\u00E3o foi poss\u00EDvel localizar este CEP.";
}
}
});
}
function candidatoAtualCompletoEM(){
var email=(sessionStorage.getItem("candidatoEmail")||"").toLowerCase();
if(!email){return null;}
var lista=typeof candidatosCadastrados==="function"?candidatosCadastrados():[];
for(var i=0;i<lista.length;i++){
if(String(lista[i].email||"").toLowerCase()===email){return lista[i];}
}
return null;
}
function distanciaCepKmEM(lat1,lon1,lat2,lon2){
function rad(x){return x*Math.PI/180;}
var R=6371,dLat=rad(lat2-lat1),dLon=rad(lon2-lon1);
var a=Math.sin(dLat/2)*Math.sin(dLat/2)+Math.cos(rad(lat1))*Math.cos(rad(lat2))*Math.sin(dLon/2)*Math.sin(dLon/2);
return R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));
}
function textoKmCepEM(km){
if(km<1){return Math.max(1,Math.round(km*1000))+" m de voc\u00EA";}
if(km<10){return km.toFixed(1).replace(".",",")+" km de voc\u00EA";}
return Math.round(km)+" km de voc\u00EA";
}
function aplicarDistanciaAutomaticaCepEM(){
if(typeof candidatoEstaLogado==="function"&&!candidatoEstaLogado()){return;}
var cand=candidatoAtualCompletoEM();
if(!cand){return;}
var clat=parseFloat(cand.latitude),clng=parseFloat(cand.longitude);
if(!isFinite(clat)||!isFinite(clng)){return;}
var vagas=typeof todasAsVagasPublicas==="function"?(todasAsVagasPublicas()||[]):[];
var cards=document.querySelectorAll("#listaVagas .vaga-card, #listaDestaques .card-destaque");
for(var i=0;i<cards.length;i++){
var card=cards[i];
var old=card.querySelector(".distancia-automatica-em,.ativar-distancia-em,.distancia-vaga-em");
if(old){old.remove();}
var empresa=String(card.getAttribute("data-empresa")||"").trim().toLowerCase();
var cargo=String(card.getAttribute("data-titulo")||"").trim().toLowerCase();
var vaga=null;
for(var j=0;j<vagas.length;j++){
if(String(vagas[j].empresa||"").trim().toLowerCase()===empresa &&
String(vagas[j].cargo||"").trim().toLowerCase()===cargo){vaga=vagas[j];break;}
}
if(!vaga||String(vaga.modalidade||"").toLowerCase().indexOf("remot")!==-1){continue;}
var vlat=parseFloat(vaga.latitude),vlng=parseFloat(vaga.longitude);
if(!isFinite(vlat)||!isFinite(vlng)){continue;}
var principal=card.querySelector(".vaga-principal");
if(!principal){continue;}
var km=distanciaCepKmEM(clat,clng,vlat,vlng);
var selo=document.createElement("span");
selo.className="distancia-automatica-em";
selo.textContent="\u2316 "+textoKmCepEM(km);
selo.title="Dist\u00E2ncia aproximada calculada pelo CEP";
principal.appendChild(selo);
}
}
