var cacheGeoCepFinalEM={};
async function geoCepFinalEM(cep){
var n=String(cep||"").replace(/\D/g,"");
if(n.length!==8){return null;}
if(cacheGeoCepFinalEM[n]){return cacheGeoCepFinalEM[n];}
try{
var r=await fetch("https://brasilapi.com.br/api/cep/v2/"+n);
if(!r.ok){return null;}
var d=await r.json();
var c=d&&d.location&&d.location.coordinates;
if(!c){return null;}
var lat=parseFloat(c.latitude),lng=parseFloat(c.longitude);
if(!isFinite(lat)||!isFinite(lng)){return null;}
cacheGeoCepFinalEM[n]={latitude:lat,longitude:lng};
return cacheGeoCepFinalEM[n];
}catch(e){return null;}
}
async function coordenadasPessoaFinalEM(cand){
if(!cand){return null;}
var lat=parseFloat(cand.latitude),lng=parseFloat(cand.longitude);
if(isFinite(lat)&&isFinite(lng)){return {latitude:lat,longitude:lng};}
return await geoCepFinalEM(cand.cep||sessionStorage.getItem("candidatoCep")||"");
}
async function coordenadasVagaFinalEM(vaga){
if(!vaga){return null;}
var lat=parseFloat(vaga.latitude),lng=parseFloat(vaga.longitude);
if(isFinite(lat)&&isFinite(lng)){return {latitude:lat,longitude:lng};}
return await geoCepFinalEM(vaga.cep||"");
}
function candidatoDistanciaFinalEM(){
if(typeof candidatoEstaLogado==="function"&&!candidatoEstaLogado()){return null;}
var cand=typeof candidatoAtualCompletoEM==="function"?candidatoAtualCompletoEM():null;
if(cand){return cand;}
var cep=sessionStorage.getItem("candidatoCep")||"";
if(!cep){return null;}
return {
cep:cep,
latitude:sessionStorage.getItem("candidatoLatitude")||"",
longitude:sessionStorage.getItem("candidatoLongitude")||""
};
}
function acharVagaCardFinalEM(card,vagas){
var id=card.getAttribute("data-id")||card.getAttribute("data-vaga-id")||"";
if(id){
for(var x=0;x<vagas.length;x++){
if(String(vagas[x].id)===String(id)){return vagas[x];}
}
}
var empresa=String(card.getAttribute("data-empresa")||"").trim().toLowerCase();
var cargo=String(card.getAttribute("data-titulo")||"").trim().toLowerCase();
for(var i=0;i<vagas.length;i++){
if(String(vagas[i].empresa||"").trim().toLowerCase()===empresa &&
String(vagas[i].cargo||"").trim().toLowerCase()===cargo){return vagas[i];}
}
return null;
}
async function distanciaEntreCandidatoEVagaFinalEM(vaga){
if(!vaga||String(vaga.modalidade||"").toLowerCase().indexOf("remot")!==-1){return null;}
var cand=candidatoDistanciaFinalEM();
if(!cand){return null;}
var cg=await coordenadasPessoaFinalEM(cand);
var vg=await coordenadasVagaFinalEM(vaga);
if(!cg||!vg){return null;}
return distanciaCepKmEM(cg.latitude,cg.longitude,vg.latitude,vg.longitude);
}
async function renderizarDistanciasCardsFinalEM(){
var cand=candidatoDistanciaFinalEM();
if(!cand){return;}
var vagas=typeof todasAsVagasPublicas==="function"?(todasAsVagasPublicas()||[]):[];
var cards=document.querySelectorAll("#listaVagas .vaga-card,#listaDestaques .card-destaque");
for(var i=0;i<cards.length;i++){
var card=cards[i];
var olds=card.querySelectorAll(".distancia-automatica-em,.ativar-distancia-em,.distancia-vaga-em,.distancia-cep-final-em");
for(var o=0;o<olds.length;o++){olds[o].remove();}
var vaga=acharVagaCardFinalEM(card,vagas);
if(!vaga){continue;}
var km=await distanciaEntreCandidatoEVagaFinalEM(vaga);
if(km===null){continue;}
var principal=card.querySelector(".vaga-principal")||card;
var selo=document.createElement("span");
selo.className="distancia-cep-final-em";
selo.textContent="\u2316 "+textoKmCepEM(km);
selo.title="Dist\u00E2ncia aproximada calculada pelos CEPs";
principal.appendChild(selo);
}
}
async function renderizarDistanciaDetalheFinalEM(vaga){
var pagina=document.getElementById("pagina-vaga");
if(!pagina||!vaga){return;}
var olds=pagina.querySelectorAll(".distancia-cep-final-em");
for(var i=0;i<olds.length;i++){olds[i].remove();}
var km=await distanciaEntreCandidatoEVagaFinalEM(vaga);
if(km===null){return;}
var alvo=document.getElementById("detalheCidade")||
document.getElementById("detalheModalidade")||
document.getElementById("detalheEmpresaCab");
if(!alvo){return;}
var selo=document.createElement("span");
selo.className="distancia-cep-final-em";
selo.textContent="\u2316 "+textoKmCepEM(km);
selo.title="Dist\u00E2ncia aproximada calculada pelos CEPs";
var pai=alvo.parentNode||alvo;
pai.appendChild(selo);
}
