async function obterGeoQualquerCepEM(obj, cepSessao){
obj=obj||{};
var lat=parseFloat(obj.latitude), lng=parseFloat(obj.longitude);
if(isFinite(lat)&&isFinite(lng)){return {latitude:lat,longitude:lng};}
var cep=String(obj.cep||cepSessao||"").replace(/\D/g,"");
if(cep.length!==8){return null;}
return await geoCepFinalEM(cep);
}
function candidatoDistanciaVisivelEM(){
var cand=typeof candidatoAtualCompletoEM==="function"?candidatoAtualCompletoEM():null;
if(cand){return cand;}
if(typeof candidatoEstaLogado==="function"&&!candidatoEstaLogado()){return null;}
return {
cep:sessionStorage.getItem("candidatoCep")||"",
latitude:sessionStorage.getItem("candidatoLatitude")||"",
longitude:sessionStorage.getItem("candidatoLongitude")||""
};
}
async function calcularKmVisivelEM(vaga){
if(!vaga){return null;}
if(String(vaga.modalidade||"").toLowerCase().indexOf("remot")!==-1){return null;}
var cand=candidatoDistanciaVisivelEM();
if(!cand){return null;}
var cg=await obterGeoQualquerCepEM(cand,sessionStorage.getItem("candidatoCep")||"");
var vg=await obterGeoQualquerCepEM(vaga,"");
if(!cg||!vg){return null;}
return distanciaCepKmEM(cg.latitude,cg.longitude,vg.latitude,vg.longitude);
}
async function mostrarDistanciaDetalheVisivelEM(vaga){
var box=document.getElementById("detalheDistanciaBoxEM");
var el=document.getElementById("detalheDistanciaEM");
if(!box||!el){return;}
box.style.display="none";
if(!vaga){return;}
var km=await calcularKmVisivelEM(vaga);
if(km===null||!isFinite(km)){return;}
el.textContent=textoKmCepEM(km);
box.style.display="";
}
