(function(){
function numEM(v){
if(v === null || typeof v === "undefined" || v === "") return null;
var n = Number(String(v).replace(",","."));
return isFinite(n) ? n : null;
}
function cepEM(v){
return String(v || "").replace(/\D/g,"").slice(0,8);
}
function haversineEM(lat1,lon1,lat2,lon2){
var R=6371, p=Math.PI/180;
var a=Math.sin((lat2-lat1)*p/2)*Math.sin((lat2-lat1)*p/2)+
Math.cos(lat1*p)*Math.cos(lat2*p)*
Math.sin((lon2-lon1)*p/2)*Math.sin((lon2-lon1)*p/2);
return R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));
}
function remotoEM(vaga){
return String((vaga && vaga.modalidade)||"").toLowerCase().indexOf("remot") !== -1;
}
function candidatoEM(){
var obj={};
try{
obj=JSON.parse(sessionStorage.getItem("candidatoLogado")||localStorage.getItem("candidatoLogado")||"null")||{};
}catch(e){}
return {
cep: cepEM(obj.cep || sessionStorage.getItem("candidatoCep") || localStorage.getItem("candidatoCep") || ""),
latitude: numEM(obj.latitude || sessionStorage.getItem("candidatoLatitude") || localStorage.getItem("candidatoLatitude")),
longitude: numEM(obj.longitude || sessionStorage.getItem("candidatoLongitude") || localStorage.getItem("candidatoLongitude"))
};
}
function geoCepEM(cep){
cep=cepEM(cep);
if(cep.length!==8) return Promise.resolve(null);
var chave="geoCepEM_"+cep;
try{
var salvo=JSON.parse(localStorage.getItem(chave)||"null");
if(salvo && numEM(salvo.latitude)!==null && numEM(salvo.longitude)!==null) return Promise.resolve(salvo);
}catch(e){}
return fetch("https://brasilapi.com.br/api/cep/v2/"+encodeURIComponent(cep))
.then(function(r){ if(!r.ok) throw new Error("CEP"); return r.json(); })
.then(function(d){
var g={
latitude:numEM(d && d.location && d.location.coordinates && d.location.coordinates.latitude),
longitude:numEM(d && d.location && d.location.coordinates && d.location.coordinates.longitude)
};
if(g.latitude===null || g.longitude===null) return null;
try{localStorage.setItem(chave,JSON.stringify(g));}catch(e){}
return g;
}).catch(function(){return null;});
}
function geoObjetoEM(o){
o=o||{};
var lat=numEM(o.latitude), lon=numEM(o.longitude);
if(lat!==null && lon!==null) return Promise.resolve({latitude:lat,longitude:lon});
return geoCepEM(o.cep);
}
function kmVagaEM(vaga){
if(!vaga || remotoEM(vaga)) return Promise.resolve(null);
var cand=candidatoEM();
return Promise.all([geoObjetoEM(cand),geoObjetoEM(vaga)]).then(function(g){
if(!g[0] || !g[1]) return null;
return haversineEM(g[0].latitude,g[0].longitude,g[1].latitude,g[1].longitude);
});
}
function textoKmEM(km){
if(km===null || !isFinite(km)) return "";
if(km<1) return "A menos de 1 km de voc\u00EA";
return km.toLocaleString("pt-BR",{maximumFractionDigits:1,minimumFractionDigits:1})+" km de voc\u00EA";
}
function vagasEM(){
try{return carregarVagasPortal()||[];}catch(e){return [];}
}
function aplicarCardsEM(){
var cand=candidatoEM();
if(!cand.cep && (cand.latitude===null || cand.longitude===null)) return;
var vs=vagasEM(), mapa={};
for(var i=0;i<vs.length;i++) mapa[String(vs[i].id||"")]=vs[i];
var cards=document.querySelectorAll(".vaga-card,.card-destaque");
Array.prototype.forEach.call(cards,function(card){
var id=String(card.getAttribute("data-id")||"");
var vaga=mapa[id];
if(!vaga){
var cargo=String(card.getAttribute("data-titulo")||"").trim().toLowerCase();
var empresa=String(card.getAttribute("data-empresa")||"").trim().toLowerCase();
for(var j=0;j<vs.length;j++){
if(String(vs[j].cargo||"").trim().toLowerCase()===cargo &&
String(vs[j].empresa||"").trim().toLowerCase()===empresa){ vaga=vs[j]; break; }
}
}
if(!vaga || remotoEM(vaga)) return;
kmVagaEM(vaga).then(function(km){
var txt=textoKmEM(km);
if(!txt) return;
var el=card.querySelector(".distancia-cep-final-em");
if(!el){
el=document.createElement("div");
el.className="distancia-cep-final-em";
el.style.cssText="margin-top:8px;font-size:13px;font-weight:700;color:#16794b;";
var alvo=card.querySelector(".vaga-principal")||card;
alvo.appendChild(el);
}
el.textContent="\u2316 "+txt;
});
});
}
function aplicarDetalheEM(id){
var vs=vagasEM(), vaga=null;
for(var i=0;i<vs.length;i++) if(String(vs[i].id)===String(id)){vaga=vs[i];break;}
var box=document.getElementById("detalheDistanciaBoxEM");
var out=document.getElementById("detalheDistanciaEM");
if(!box || !out || !vaga || remotoEM(vaga)){ if(box) box.style.display="none"; return; }
var cand=candidatoEM();
if(!cand.cep && (cand.latitude===null || cand.longitude===null)){box.style.display="none";return;}
box.style.display="";
out.textContent="Calculando...";
kmVagaEM(vaga).then(function(km){
var txt=textoKmEM(km);
if(txt){out.textContent=txt;}else{box.style.display="none";}
});
}
