irPara("empresa-publica",nome);
}
function renderizarEmpresaPublicaEM(nome){
var chave=decodeURIComponent(String(nome||""));
var vagas=todasAsVagasPublicas().filter(function(v){return normalizarEmpresaEM(v.empresa)===normalizarEmpresaEM(chave);});
var base=vagas[0]||null;
document.getElementById("empresaPublicaNomeEM").textContent=chave||"Empresa";
var local=base?(base.cidade||base.localizacao||"Localiza\u00E7\u00E3o n\u00E3o informada"):"Localiza\u00E7\u00E3o n\u00E3o informada";
document.getElementById("empresaPublicaLocalEM").textContent=local;
var sobre=base?(base.sobreEmpresa||base.sobre||base.descricaoEmpresa||""):"";
document.getElementById("empresaPublicaSobreEM").textContent=sobre||"Esta empresa ainda n\u00E3o adicionou uma apresenta\u00E7\u00E3o p\u00FAblica.";
var logo=document.getElementById("empresaPublicaLogoEM");
var url=base&&(base.logo||base.logoEmpresa||"");
logo.innerHTML=url?'<img alt="Logo da empresa" src="'+url+'"/>':(chave?chave.charAt(0).toUpperCase():"E");
var ver=base&&(base.verificada===true||String(base.verificada).toLowerCase()==="sim"||String(base.verificada)==="1");
document.getElementById("empresaPublicaSeloEM").textContent=ver?"\u2713 Empresa verificada":"Empresa no EmpregaMais";
document.getElementById("empresaPublicaQtdEM").textContent=vagas.length===1?"1 vaga aberta":vagas.length+" vagas abertas";
var box=document.getElementById("empresaPublicaVagasEM");box.innerHTML="";
