return null;
}
function empresaDaVagaEM(vaga){
if(!vaga)return null;
var cnpj=String(vaga.empresaCnpj||vaga.cnpj||"").replace(/\D/g,"");
if(cnpj){
var porCnpj=empresaPorCnpj(cnpj);
if(porCnpj)return porCnpj;
}
return empresaCadastradaPorNomeEM(vaga.empresa||"");
}
abrirPerfilEmpresaPublica=function(cnpj){
var empresa=empresaPorCnpj(cnpj);
if(!empresa){
alert("N\u00E3o foi poss\u00EDvel localizar o cadastro desta empresa.");
return;
}
var nome=empresa.nomeFantasia||empresa.nome||empresa.razaoSocial||"Empresa";
var el=document.getElementById("empresaPublicaNome");if(el)el.textContent=nome;
var logo=document.getElementById("empresaPublicaLogo");
if(logo){
if(empresa.logo){
logo.src=empresa.logo;logo.style.display="block";
}else{
logo.removeAttribute("src");logo.style.display="none";
}
}
el=document.getElementById("empresaPublicaRazaoSocial");
if(el)el.textContent=empresa.razaoSocial||empresa.nome||"";
el=document.getElementById("empresaPublicaMatriz");
if(el)el.textContent=empresa.matriz||empresa.cidade||empresa.localizacao||"N\u00E3o informada";
el=document.getElementById("empresaPublicaFuncionarios");
if(el)el.textContent=empresa.funcionarios||"N\u00E3o informado";
el=document.getElementById("empresaPublicaFaturamento");
if(el)el.textContent=empresa.faturamento||"N\u00E3o informado";
el=document.getElementById("empresaPublicaSetor");
if(el)el.textContent=empresa.setor||"N\u00E3o informado";
el=document.getElementById("empresaPublicaSobre");
if(el)el.textContent=empresa.sobreInstitucional||empresa.sobre||"A empresa ainda n\u00E3o adicionou uma apresenta\u00E7\u00E3o institucional.";
var vagas=todasAsVagasPublicas().filter(function(v){
var ec=String(v.empresaCnpj||v.cnpj||"").replace(/\D/g,"");
if(ec && ec===String(empresa.cnpj||"").replace(/\D/g,""))return true;
return String(v.empresa||"").trim().toLowerCase()===String(empresa.nome||empresa.nomeFantasia||"").trim().toLowerCase();
});
el=document.getElementById("empresaPublicaTotalVagas");
if(el)el.textContent=vagas.length;
var bloco=document.getElementById("empresaPublicaListaVagas");
if(bloco){
bloco.innerHTML="";
vagas.forEach(function(v){bloco.appendChild(criarCardVaga(v,false));});
if(!vagas.length)bloco.innerHTML="<div class='vazio'>Esta empresa n\u00E3o possui vagas abertas no momento.</div>";
}
var cab=document.querySelector("#pagina-empresa-publica .empresa-publica-cab,#pagina-empresa-publica .empresa-publica-topo");
if(cab){
var antigo=cab.querySelector(".empresa-publica-status-cadastro-em");
if(antigo)antigo.remove();
var selo=document.createElement("span");
var ver=empresaEstaVerificada(empresa);
selo.className="empresa-publica-status-cadastro-em"+(ver?" verificada":"");
selo.textContent=ver?"\u2713 Empresa verificada":"Empresa cadastrada no EmpregaMais";
cab.appendChild(selo);
}
mostrarPagina("empresa-publica");
};
