function textoPreenchidoEmpresaEM(v){
return String(v||"").trim().length>0;
}
function empresaPerfilCompletoEM(empresa){
if(!empresa)return false;
var nome=empresa.nomeFantasia||empresa.nome||empresa.razaoSocial||"";
var razao=empresa.razaoSocial||empresa.nome||"";
var cnpj=String(empresa.cnpj||"").replace(/\D/g,"");
var local=empresa.matriz||empresa.cidade||empresa.localizacao||"";
var setor=empresa.setor||"";
var sobre=empresa.sobreInstitucional||empresa.sobre||"";
var logo=empresa.logo||"";
return (
textoPreenchidoEmpresaEM(nome) &&
textoPreenchidoEmpresaEM(razao) &&
cnpj.length===14 &&
textoPreenchidoEmpresaEM(local) &&
textoPreenchidoEmpresaEM(setor) &&
textoPreenchidoEmpresaEM(sobre) &&
textoPreenchidoEmpresaEM(logo)
);
}
function empresaPodeTerPerfilPublicoEM(empresa){
return !!empresa && empresaEstaVerificada(empresa) && empresaPerfilCompletoEM(empresa);
}
