function planoPermiteConfidencialEM(){
var chave="";
try{
var empresa=typeof obterEmpresaAtual==="function" ? obterEmpresaAtual() : null;
chave=String(
(empresa && (
empresa.plano_id ||
empresa.planoId ||
empresa.plano ||
empresa.plano_nome ||
empresa.planoNome
)) ||
localStorage.getItem("planoEmpresaEmpregaMais") ||
sessionStorage.getItem("planoEscolhidoEmpregaMais") ||
""
).toLowerCase().trim();
if(chave.indexOf("anual")>=0)chave="anual";
else if(chave.indexOf("semestral")>=0)chave="semestral";
else if(chave.indexOf("trimestral")>=0)chave="trimestral";
else if(chave==="gratuito"||chave==="gratis"||chave==="basic")chave="basico";
}catch(e){}
return chave==="trimestral" || chave==="semestral" || chave==="anual";
}
function atualizarCampoConfidencialEM(){
var c=document.getElementById("vagaConfidencialEM");
var msg=document.getElementById("vagaConfidencialMsgEM");
if(!c)return;
var ok=planoPermiteConfidencialEM();
c.disabled=!ok;
var lab=c.parentElement;
if(lab)lab.classList.toggle("bloqueado",!ok);
if(!ok){
c.checked=false;
if(msg)msg.textContent="Dispon\u00EDvel nos planos Trimestral, Semestral e Anual.";
}else if(msg){
msg.textContent="A empresa continuar\u00E1 identificada para o EmpregaMais e para a modera\u00E7\u00E3o.";
}
}
function vagaEhConfidencialEM(vaga){
if(!vaga)return false;
var valor=vaga.confidencial;
if(valor===true || valor===1)return true;
valor=String(valor==null?"":valor).toLowerCase().trim();
return valor==="1" || valor==="sim" || valor==="true" || valor==="confidencial";
}
