function publicarVagaAdminEM(event){
event.preventDefault();
if(!adminEstaLogado()){
irPara("login-admin");
return;
}
var nome=valorCampoAdminEM("adminEmpresaNomeVagaEM") || valorCampoAdminEM("empresaVaga");
var email=valorCampoAdminEM("adminEmpresaEmailVagaEM");
var cnpj=valorCampoAdminEM("adminEmpresaCnpjVagaEM").replace(/\D/g,"");
if(!nome){
alert("Informe o nome da empresa anunciante.");
return;
}
var contato=document.querySelector("input[name='tipoContatoVaga']:checked");
var tipoContato=contato?contato.value:"email";
var contatoCandidatura="";
if(tipoContato==="email")contatoCandidatura=valorCampoAdminEM("emailCandidaturaVaga");
if(tipoContato==="whatsapp")contatoCandidatura=normalizarWhatsappVaga(valorCampoAdminEM("whatsappCandidaturaVaga"));
if(tipoContato==="link")contatoCandidatura=valorCampoAdminEM("linkCandidaturaVaga");
if(tipoContato==="email" && !contatoCandidatura){alert("Informe o e-mail para receber as candidaturas.");return;}
if(tipoContato==="whatsapp" && contatoCandidatura.length<10){alert("Informe um WhatsApp v\u00E1lido.");return;}
if(tipoContato==="link" && !/^https?:\/\//i.test(contatoCandidatura)){alert("Informe um link completo come\u00E7ando com https://");return;}
var obrigatorios=["cargoVaga","estadoVaga","cidadeVaga","areaVaga","contratoVaga","escolaridadeVaga","experienciaVaga","jornadaVaga","descricaoVaga","requisitosVaga"];
for(var i=0;i<obrigatorios.length;i++){
var el=document.getElementById(obrigatorios[i]);
if(el && !String(el.value||"").trim()){
alert("Preencha todos os campos obrigat\u00F3rios da vaga.");
el.focus();
return;
}
}
var salario=valorCampoAdminEM("salarioVaga")||"Sal\u00E1rio a combinar";
