var nova={
id:"vaga_"+agora,
empresa:nome,
empresaCnpj:cnpj,
empresaEmail:email||contatoCandidatura,
tipoContato:tipoContato,
contatoCandidatura:contatoCandidatura,
cargo:valorCampoAdminEM("cargoVaga"),
estado:valorCampoAdminEM("estadoVaga"),
cidade:valorCampoAdminEM("cidadeVaga"),
cep:valorCampoAdminEM("cepVaga").replace(/\D/g,""),
latitude:typeof coordenadasCepVagaEM!=="undefined"&&coordenadasCepVagaEM?coordenadasCepVagaEM.latitude:"",
longitude:typeof coordenadasCepVagaEM!=="undefined"&&coordenadasCepVagaEM?coordenadasCepVagaEM.longitude:"",
area:valorCampoAdminEM("areaVaga"),
contrato:valorCampoAdminEM("contratoVaga"),
modalidade:valorCampoAdminEM("modalidadeVaga"),
escolaridade:valorCampoAdminEM("escolaridadeVaga"),
experiencia:valorCampoAdminEM("experienciaVaga"),
jornada:valorCampoAdminEM("jornadaVaga"),
beneficiosTags:typeof beneficiosTagsSelecionados==="function"?beneficiosTagsSelecionados():[],
pcd:valorCampoAdminEM("pcdVaga"),
salario:salario,
salarioNumero:extrairSalarioNumero(salario),
descricao:valorCampoAdminEM("descricaoVaga"),
requisitos:valorCampoAdminEM("requisitosVaga"),
beneficios:valorCampoAdminEM("beneficiosVaga"),
sobreEmpresa:valorCampoAdminEM("sobreEmpresaVaga"),
logo:typeof logoAtual!=="undefined"?logoAtual:"",
planoDias:365,
planoId:"admin",
planoNome:"Publica\u00E7\u00E3o administrativa",
planoPreco:0,
confidencial:!!(conf&&conf.checked),
dataPublicacao:dataHoje(),
expiraEm:calcularExpiracao(365),
visualizacoes:0,
destaque:!!(destacar&&destacar.checked),
status:"ativa",
aprovacao:(aprovar&&aprovar.checked)?"aprovada":"pendente",
jaFoiAprovada:!!(aprovar&&aprovar.checked),
edicoesAposAprovacao:0,
publicadaPeloAdmin:true
};
var vagas=carregarVagasPortal();
vagas.unshift(nova);
salvarVagasPortal(vagas);
try{
fetch(EMPREGAMAIS_API_URL,{
method:"POST",
headers:{"Content-Type":"text/plain;charset=utf-8"},
body:JSON.stringify({acao:"publicar",vaga:nova})
}).then(function(){
if(typeof sincronizarVagasGoogleSheets==="function")return sincronizarVagasGoogleSheets();
}).catch(function(){});
}catch(e){}
event.target.reset();
if(typeof logoAtual!=="undefined")logoAtual="";
