if(prev)prev.style.display="none";
mostrarModalSite(
nova.aprovacao==="aprovada"?"Vaga publicada com sucesso!":"Vaga enviada para a fila!",
nova.aprovacao==="aprovada"?"A oportunidade j\u00E1 est\u00E1 ativa no portal.":"A oportunidade foi salva e est\u00E1 aguardando aprova\u00E7\u00E3o administrativa.",
"sucesso",
"Voltar ao painel",
function(){irPara("painel-admin");}
);
