});
var filtroEmpresasAdminAtualEM="todas";
var empresaAdminSelecionadaEM="";
function normalizarEmpresaAdminEM(v){
return String(v||"Empresa n\u00E3o informada").trim()||"Empresa n\u00E3o informada";
}
function chaveEmpresaAdminEM(v){
return normalizarEmpresaAdminEM(v).toLowerCase();
}
function vagaPendenteAdminEM(v){
var a=String(v&&v.aprovacao||"pendente").toLowerCase();
var s=String(v&&v.status||"").toLowerCase();
return s!=="encerrada" && s!=="expirada" && a==="pendente";
}
function agruparEmpresasAdminEM(){
var vagas=carregarVagasPortal();
var mapa={};
vagas.forEach(function(v){
if(String(v.status||"").toLowerCase()==="encerrada")return;
var nome=normalizarEmpresaAdminEM(v.empresa);
var chave=chaveEmpresaAdminEM(nome);
if(!mapa[chave])mapa[chave]={chave:chave,nome:nome,total:0,pendentes:0,vagas:[]};
mapa[chave].total++;
if(vagaPendenteAdminEM(v))mapa[chave].pendentes++;
mapa[chave].vagas.push(v);
});
return Object.keys(mapa).map(function(k){return mapa[k];}).sort(function(a,b){
if(b.pendentes!==a.pendentes)return b.pendentes-a.pendentes;
return a.nome.localeCompare(b.nome,"pt-BR");
});
}
function iniciaisEmpresaAdminEM(nome){
return String(nome||"E").split(/\s+/).filter(Boolean).slice(0,2).map(function(x){return x.charAt(0).toUpperCase();}).join("");
}
function filtrarEmpresasAdminEM(filtro,botao){
filtroEmpresasAdminAtualEM=filtro||"todas";
document.querySelectorAll("[data-filtro-empresa-em]").forEach(function(b){b.classList.remove("ativo");});
if(botao)botao.classList.add("ativo");
renderizarEmpresasAdminEM();
}
function renderizarEmpresasAdminEM(){
var grid=document.getElementById("adminEmpresasGridEM");
if(!grid)return;
var empresas=agruparEmpresasAdminEM();
var totalPendencias=empresas.reduce(function(n,e){return n+e.pendentes;},0);
var qtd=document.getElementById("adminEmpresasQtdEM");
var badge=document.getElementById("adminPendenciasBadgeEM");
if(qtd)qtd.textContent=empresas.length;
if(badge)badge.textContent=totalPendencias;
var busca=String((document.getElementById("adminBuscaEmpresaEM")||{}).value||"").toLowerCase().trim();
empresas=empresas.filter(function(e){
if(busca && e.nome.toLowerCase().indexOf(busca)===-1)return false;
if(filtroEmpresasAdminAtualEM==="pendentes")return e.pendentes>0;
if(filtroEmpresasAdminAtualEM==="sem-pendencias")return e.pendentes===0;
return true;
});
if(!empresas.length){
grid.innerHTML='<div class="admin-empresa-vazio-em">Nenhuma empresa encontrada neste filtro.</div>';
return;
}
grid.innerHTML=empresas.map(function(e){
var pend=e.pendentes>0
?'<span class="admin-pendente-selo-em">\u25CF '+e.pendentes+' pendente'+(e.pendentes>1?'s':'')+'</span>'
:'<span class="admin-pendente-selo-em" style="background:#ecfdf3;color:#138a4b">\u2713 Em dia</span>';
return '<div class="admin-empresa-box-em '+(e.pendentes?'tem-pendencia-em':'')+'" onclick="abrirEmpresaAdminEM('+JSON.stringify(e.chave).replace(/"/g,"&quot;")+')">'+
'<div class="admin-empresa-box-top-em">'+
'<div class="admin-empresa-avatar-em">'+iniciaisEmpresaAdminEM(e.nome)+'</div>'+
'<div class="admin-empresa-identidade-em"><h3>'+esc(e.nome)+'</h3><small>'+e.total+' vaga'+(e.total!==1?'s':'')+' ativa'+(e.total!==1?'s':'')+'</small></div>'+
pend+
'</div>'+
'<div class="admin-empresa-box-meta-em"><span>Gerenciar oportunidades</span><b>Abrir \u2192</b></div>'+
'</div>';
}).join("");
}
function abrirEmpresaAdminEM(chave){
empresaAdminSelecionadaEM=String(chave||"");
var empresas=agruparEmpresasAdminEM();
var emp=empresas.find(function(e){return e.chave===empresaAdminSelecionadaEM;});
if(!emp)return;
var box=document.getElementById("adminVagasEmpresaSelecionadaEM");
var nome=document.getElementById("adminEmpresaSelecionadaNomeEM");
var resumo=document.getElementById("adminEmpresaSelecionadaResumoEM");
if(box)box.classList.remove("oculto");
if(nome)nome.textContent=emp.nome;
if(resumo)resumo.textContent=emp.total+" vaga"+(emp.total!==1?"s":"")+" \u2022 "+emp.pendentes+" aguardando aprova\u00E7\u00E3o";
var busca=document.getElementById("buscaAdmin");
if(busca)busca.value=emp.nome;
renderizarAdminVagas();
if(box)box.scrollIntoView({behavior:"smooth",block:"start"});
}
