function empresaAtualPainelEM(){
try{
if(typeof obterEmpresaAtual==="function"){
var e=obterEmpresaAtual();
if(e)return e;
}
}catch(err){}
return null;
}
function vagasDaEmpresaPainelEM(){
var e=empresaAtualPainelEM();
if(!e)return [];
var cnpj=String(e.cnpj||"").replace(/\D/g,"");
var nome=String(e.nomeFantasia||e.nome||e.razaoSocial||"").toLowerCase().trim();
return carregarVagasPortal().filter(function(v){
var vc=String(v.empresaCnpj||v.cnpj||"").replace(/\D/g,"");
var vn=String(v.empresa||"").toLowerCase().trim();
return (cnpj&&vc===cnpj)||(nome&&vn===nome);
});
}
function atualizarCabecalhoEmpresaPainelEM(){
var e=empresaAtualPainelEM();
var nome=e?String(e.nomeFantasia||e.nome||e.razaoSocial||"Empresa"):"Empresa";
var saud=document.getElementById("empresaPainelSaudacaoEM");
if(saud)saud.textContent="Ol\u00E1, "+nome;
var vagas=vagasDaEmpresaPainelEM();
var pend=vagas.filter(function(v){return String(v.aprovacao||"pendente").toLowerCase()==="pendente"&&String(v.status||"")!=="encerrada";}).length;
var acoes=[];
if(pend)acoes.push(pend+" vaga"+(pend>1?"s":"")+" aguardando aprova\u00E7\u00E3o");
var box=document.getElementById("empresaAcoesNecessariasEM");
var txt=document.getElementById("empresaAcoesNecessariasTextoEM");
if(box&&txt){
if(acoes.length){txt.textContent=acoes.join(" \u2022 ");box.classList.remove("oculto");}
else{box.classList.add("oculto");}
}
}
function classificarBlocoEmpresaEM(el){
var t=String(el.textContent||"").toLowerCase();
if(t.indexOf("plano")>=0||t.indexOf("assinatura")>=0||t.indexOf("upgrade")>=0)return"plano";
if(t.indexOf("candidat")>=0||t.indexOf("curr\u00EDculo")>=0||t.indexOf("curriculo")>=0)return"candidatos";
if(t.indexOf("cnpj")>=0||t.indexOf("raz\u00E3o social")>=0||t.indexOf("razao social")>=0||t.indexOf("verifica")>=0||t.indexOf("logo")>=0)return"empresa";
if(t.indexOf("vaga")>=0||t.indexOf("oportunidade")>=0)return"vagas";
return"visao";
}
