var status=String(e.verificacaoStatus||"nao_verificada").toLowerCase();
var verificada=e.verificada===true || status==="verificada" || status==="aprovada";
var pendente=status==="pendente" || status==="em_analise" || status==="analise";
var selo=document.getElementById("empresaVerificacaoStatusEM");
var nav=document.getElementById("empresaVerificacaoNavStatusEM");
