if(selo){
selo.className="empresa-verificacao-status-em"+(verificada?" verificada-em":(pendente?" pendente-em":""));
selo.textContent=verificada?"\u2713 Empresa verificada":(pendente?"Em an\u00E1lise":"N\u00E3o verificada");
}
if(nav){nav.textContent=verificada?"\u2713":(pendente?"\u25CF":"\u2022");nav.style.color=verificada?"#138a4b":(pendente?"#956900":"#98a2b3");}
if(txt)txt.textContent=verificada?"Sua empresa foi verificada e est\u00E1 apta a exibir o selo.":(pendente?"Sua solicita\u00E7\u00E3o foi enviada e est\u00E1 aguardando an\u00E1lise da administra\u00E7\u00E3o.":"Sua empresa ainda n\u00E3o possui o selo de verifica\u00E7\u00E3o.");
if(btn){
btn.textContent=verificada?"Ver dados da verifica\u00E7\u00E3o":(pendente?"Acompanhar solicita\u00E7\u00E3o":"Solicitar verifica\u00E7\u00E3o");
btn.disabled=false;
}
}
