var url=location.href;
return {titulo:String(titulo).trim(),url:url,texto:"Confira esta oportunidade no EmpregaMais: "+String(titulo).trim()+" \u2014 "+url};
}
function compartilharVagaWhatsAppEM(){
var d=dadosCompartilhamentoVagaEM();
window.open("https://wa.me/?text="+encodeURIComponent(d.texto),"_blank","noopener");
}
function compartilharVagaEmailEM(){
