async function compartilharVagaInstagramEM(){
var d=dadosCompartilhamentoVagaEM();
try{
if(navigator.share){
await navigator.share({title:d.titulo,text:"Confira esta oportunidade no EmpregaMais",url:d.url});
return;
}
}catch(e){ if(e&&e.name==="AbortError")return; }
try{
await navigator.clipboard.writeText(d.url);
alert("Link da vaga copiado. Abra o Instagram e cole o link na mensagem ou no Story.");
}catch(e){
prompt("Copie o link da vaga para compartilhar no Instagram:",d.url);
}
}
function instalarCompartilhamentoVagaEM(){
var seletores=[
"#pagina-detalhes",
"#pagina-detalhes-vaga",
"#pagina-vaga-detalhes",
"#pagina-vaga",
"[id*='detalhe'][id*='vaga']",
"[class*='detalhe'][class*='vaga']"
];
var pagina=null;
for(var i=0;i<seletores.length;i++){
var candidatos=document.querySelectorAll(seletores[i]);
for(var j=0;j<candidatos.length;j++){
var c=candidatos[j];
var st=window.getComputedStyle(c);
if(st.display!=="none" && st.visibility!=="hidden"){
pagina=c;break;
}
}
if(pagina)break;
}
if(!pagina)return;
if(pagina.querySelector(".compartilhar-vaga-em"))return;
var alvo=
pagina.querySelector("[id*='vagaDetalhe']")||
pagina.querySelector("[id*='detalhesVaga']")||
pagina.querySelector(".vaga-detalhes")||
pagina.querySelector(".detalhes-vaga")||
pagina.querySelector(".vaga-conteudo")||
pagina.querySelector(".job-detail")||
pagina.querySelector(".painel-card")||
pagina.querySelector(".form-card")||
pagina.querySelector(".container")||
pagina;
var box=document.createElement("div");
box.className="compartilhar-vaga-em";
box.setAttribute("data-compartilhar-vaga-em","1");
box.innerHTML='<strong>Compartilhar esta vaga</strong><div class="compartilhar-vaga-botoes-em">'+
'<button type="button" onclick="compartilharVagaWhatsAppEM()"><span class="share-icone-em">\u25C9</span>WhatsApp</button>'+
'<button type="button" onclick="compartilharVagaEmailEM()"><span class="share-icone-em">\u2709</span>E-mail</button>'+
'<button type="button" onclick="compartilharVagaInstagramEM()"><span class="share-icone-em">\u25CE</span>Instagram</button></div>';
var candidatura=
pagina.querySelector("[id*='candidat']")||
pagina.querySelector("[class*='candidat']")||
pagina.querySelector(".vaga-detalhes-acoes")||
pagina.querySelector(".detalhes-acoes")||
pagina.querySelector(".vaga-acoes");
if(candidatura && candidatura.parentNode){
candidatura.insertAdjacentElement("afterend",box);
}else{
alvo.appendChild(box);
}
}
function agendarCompartilhamentoVagaEM(){
[80,250,600].forEach(function(ms){setTimeout(instalarCompartilhamentoVagaEM,ms);});
}
