(function(){
var nomes=["abrirDetalhesVaga","abrirVaga","verVaga","abrirDetalheVaga"];
nomes.forEach(function(nome){
if(typeof window[nome]==="function" && !window[nome].__shareEM){
var original=window[nome];
var wrapped=function(){
