lista[i].experienciaProfissional=val("perfilExperienciaEM");
lista[i].habilidadesProfissionais=val("perfilHabilidadesEM");
lista[i].modalidadePreferida=val("perfilModalidadeEM");
lista[i].cidadeProfissional=val("perfilCidadeProfissionalEM");
break;
}
}
salvarArray("candidatosEmpregaMais",lista);
atualizarStatusPerfilProfissionalEM();
}
function nivelEscolaridadeEM(v){
var s=normalizarAderenciaEM(v);
if(!s||s.indexOf("nao exig")>=0)return 0;
if(s.indexOf("fundamental")>=0)return 1;
if(s.indexOf("medio")>=0)return 2;
if(s.indexOf("tecnico")>=0)return 3;
if(s.indexOf("superior curs")>=0)return 4;
if(s.indexOf("superior")>=0)return 5;
if(s.indexOf("pos")>=0)return 6;
if(s.indexOf("mestrado")>=0)return 7;
if(s.indexOf("doutorado")>=0)return 8;
return 0;
}
function nivelExperienciaEM(v){
var s=normalizarAderenciaEM(v);
if(!s||s.indexOf("nao exig")>=0||s.indexOf("sem experiencia")>=0)return 0;
if(s.indexOf("6 meses")>=0 && s.indexOf("1 ano")<0)return 1;
if(s.indexOf("6 meses a 1")>=0||s.indexOf("1 ano")>=0)return 2;
if(s.indexOf("1 a 2")>=0)return 3;
if(s.indexOf("2 a 3")>=0)return 4;
if(s.indexOf("3 a 5")>=0)return 5;
if(s.indexOf("mais de 5")>=0)return 6;
var n=parseFloat((s.match(/\d+(?:[.,]\d+)?/)||["0"])[0].replace(",","."));
return n>=5?6:n>=3?5:n>=2?4:n>=1?3:0;
}
function palavrasRelevantesEM(v){
var stop={"de":1,"da":1,"do":1,"das":1,"dos":1,"e":1,"em":1,"com":1,"para":1,"por":1,"um":1,"uma":1,"ou":1,"a":1,"o":1,"as":1,"os":1,"no":1,"na":1,"nos":1,"nas":1,"ser":1,"ter":1,"conhecimento":1,"experiencia":1};
var arr=normalizarAderenciaEM(v).split(" ").filter(function(x){return x.length>=3&&!stop[x];});
return Array.from(new Set(arr));
}
function calcularAderenciaVagaEM(vaga,c){
var total=0, itens=[];
function add(nome,pontos,max){
total+=pontos;
itens.push({nome:nome,ok:pontos>=max*.6,pontos:pontos,max:max});
}
var areaC=normalizarAderenciaEM(c.areaProfissional);
var areaV=normalizarAderenciaEM(vaga.area);
var cargoC=normalizarAderenciaEM(c.cargoDesejado);
var cargoV=normalizarAderenciaEM(vaga.cargo);
var cargoPts=0;
if(areaC&&areaV&&(areaV.indexOf(areaC)>=0||areaC.indexOf(areaV)>=0))cargoPts+=10;
var pc=palavrasRelevantesEM(cargoC), pv=palavrasRelevantesEM(cargoV);
var inter=pc.filter(function(x){return pv.indexOf(x)>=0;}).length;
if(pc.length&&pv.length)cargoPts+=Math.round(20*Math.min(1,inter/Math.max(1,Math.min(pc.length,pv.length))));
add("\u00C1rea e cargo",Math.min(30,cargoPts),30);
var reqExp=nivelExperienciaEM(vaga.experiencia);
var candExp=nivelExperienciaEM(c.experienciaProfissional);
add("Experi\u00EAncia",reqExp===0?20:(candExp>=reqExp?20:Math.max(0,20-(reqExp-candExp)*6)),20);
var reqEsc=nivelEscolaridadeEM(vaga.escolaridade);
var candEsc=nivelEscolaridadeEM(c.escolaridadeProfissional);
add("Escolaridade",reqEsc===0?15:(candEsc>=reqEsc?15:Math.max(0,15-(reqEsc-candEsc)*5)),15);
var hab=palavrasRelevantesEM(c.habilidadesProfissionais);
var req=palavrasRelevantesEM((vaga.requisitos||"")+" "+(vaga.descricao||""));
var achadas=hab.filter(function(x){return req.indexOf(x)>=0;}).length;
var habPts=req.length&&hab.length?Math.round(20*Math.min(1,achadas/Math.min(5,hab.length))):10;
add("Habilidades",habPts,20);
var modC=normalizarAderenciaEM(c.modalidadePreferida);
var modV=normalizarAderenciaEM(vaga.modalidade);
add("Modalidade",!modC?10:(modC===modV?10:2),10);
var cidC=normalizarAderenciaEM(c.cidadeProfissional);
var cidV=normalizarAderenciaEM(vaga.cidade);
var remoto=modV.indexOf("remoto")>=0;
add("Localiza\u00E7\u00E3o",remoto||!cidC?5:(cidC===cidV?5:0),5);
return {percentual:Math.max(0,Math.min(100,Math.round(total))),itens:itens};
}
function renderizarAderenciaVagaEM(){
var box=document.getElementById("aderenciaVagaEM");
if(!box)return;
var papel=sessionStorage.getItem("empregaMaisPapel");
var c=candidatoPerfilProfissionalEM();
var pct=document.getElementById("aderenciaPercentualEM");
var barra=document.getElementById("aderenciaBarraEM");
var resumo=document.getElementById("aderenciaResumoEM");
var criterios=document.getElementById("aderenciaCriteriosEM");
var btn=document.getElementById("aderenciaPerfilBtnEM");
if(papel!=="candidato"||!c){
pct.textContent="--%";barra.style.width="0";criterios.innerHTML="";
resumo.textContent="Entre na sua conta de candidato e preencha o perfil profissional para calcular sua ader\u00EAncia.";
btn.style.display=papel==="candidato"?"inline-flex":"none";
return;
}
if(!perfilProfissionalPreenchidoEM(c)){
pct.textContent="--%";barra.style.width="0";criterios.innerHTML="";
resumo.textContent="Complete seu perfil profissional para liberar a compara\u00E7\u00E3o com esta vaga.";
btn.style.display="inline-flex";
return;
}
if(!vagaAtual)return;
var r=calcularAderenciaVagaEM(vagaAtual,c);
pct.textContent=r.percentual+"%";
barra.style.width=r.percentual+"%";
btn.style.display="none";
var faixa=r.percentual>=80?"Alta ader\u00EAncia":r.percentual>=60?"Boa ader\u00EAncia":r.percentual>=40?"Ader\u00EAncia moderada":"Baixa ader\u00EAncia";
resumo.textContent=faixa+". Veja abaixo os principais crit\u00E9rios comparados com a vaga.";
criterios.innerHTML="";
r.itens.forEach(function(it){
var div=document.createElement("div");
div.className="aderencia-criterio-em"+(it.ok?"":" nao");
div.innerHTML="<i>"+(it.ok?"\u2713":"\u2013")+"</i><span>"+it.nome+"</span>";
criterios.appendChild(div);
});
}
