function formatarKmCanonicoEM(km){
var n=parseFloat(String(km==null?"":km).replace(",","."));
if(!isFinite(n))return "";
if(n<0.1)n=0.1;
var casas=n<10?1:0;
return n.toLocaleString("pt-BR",{minimumFractionDigits:casas,maximumFractionDigits:casas});
}
function ufDaVagaEM(v){
return String(v.estado||v.uf||v.siglaEstado||"").trim().toUpperCase();
}
function textoLocalDistanciaCanonicoEM(v,km){
var cidade=String(v.cidade||v.localizacao||"").trim();
var uf=ufDaVagaEM(v);
var local=cidade+(uf?" - "+uf:"");
var d=formatarKmCanonicoEM(km);
return local+(d?", a "+d+" km de voc\u00EA":"");
}
function obterKmVagaEM(v){
var candidatos=[
v.distanciaKm,v.distancia,v.km,v.distanciaCandidato
];
for(var i=0;i<candidatos.length;i++){
var n=parseFloat(String(candidatos[i]==null?"":candidatos[i]).replace(",","."));
if(isFinite(n))return n;
}
var pagina=document.getElementById("pagina-vaga");
if(pagina){
var els=pagina.querySelectorAll("[id*='Distancia'],[id*='distancia'],[class*='distancia']");
for(var j=0;j<els.length;j++){
var m=String(els[j].textContent||"").match(/(\d+(?:[.,]\d+)?)\s*(?:km|m\b)/i);
if(m){
var val=parseFloat(m[1].replace(",","."));
if(/\bm\b/i.test(m[0])&&!/km/i.test(m[0]))val=val/1000;
if(isFinite(val))return val;
}
}
}
return null;
}
function aplicarDistanciaCanonicaDetalheEM(){
if(!window.vagaAtual)return;
var v=window.vagaAtual;
var km=obterKmVagaEM(v);
var texto=textoLocalDistanciaCanonicoEM(v,km);
if(!texto)return;
var local=document.getElementById("vagaLocal")||
document.getElementById("detalheLocal")||
document.querySelector("#pagina-vaga [data-campo='local']");
if(local){
local.textContent=texto;
local.classList.add("distancia-canonica-em");
}
var caixas=document.querySelectorAll("#pagina-vaga .vaga-info-item,#pagina-vaga .info-item,#pagina-vaga .detalhe-info");
Array.from(caixas).forEach(function(box){
var t=String(box.textContent||"").trim().toLowerCase();
if(t.indexOf("dist\u00E2ncia")===0||t.indexOf("distancia")===0)box.style.display="none";
});
}
function aplicarDistanciaCanonicaCardsEM(){
var vagas=[];
try{vagas=carregarVagasPortal()||[];}catch(e){}
document.querySelectorAll(".card-vaga,.card-destaque").forEach(function(card){
card.querySelectorAll(".local-distancia-card-em").forEach(function(x){x.remove();});
var id=String(card.getAttribute("data-id")||card.dataset.id||"");
var v=vagas.find(function(x){return String(x.id||"")===id;});
if(!v)return;
var km=obterKmVagaEM(v);
var texto=textoLocalDistanciaCanonicoEM(v,km);
if(!texto)return;
Array.from(card.querySelectorAll(".tag,.chip,.vaga-tag,[class*='distancia']")).forEach(function(el){
var t=String(el.textContent||"").toLowerCase();
if(t.indexOf("de voc\u00EA")>=0||t.indexOf("de voc\u00EA")>=0)el.style.display="none";
});
var tags=card.querySelector(".tags,.vaga-tags,.chips");
if(tags){
Array.from(tags.children).forEach(function(el){
var t=String(el.textContent||"").trim().toLowerCase();
var cidade=String(v.cidade||"").trim().toLowerCase();
if(cidade && t.indexOf(cidade)>=0)el.style.display="none";
});
var linha=document.createElement("span");
linha.className="local-distancia-card-em";
linha.textContent=texto;
tags.insertBefore(linha,tags.firstChild);
}
});
}
