function avaliacoesProcessoEmpresaEM(vaga){
var chaves=["avaliacoesProcessosEmpregaMais","avaliacoesEmpresasEmpregaMais"];
var lista=[];
chaves.forEach(function(k){
try{
var a=JSON.parse(localStorage.getItem(k)||"[]");
if(Array.isArray(a))lista=lista.concat(a);
}catch(e){}
});
var cnpj=String(vaga.cnpj||vaga.empresaCnpj||"").replace(/\D/g,"");
var nome=String(vaga.empresa||vaga.empresaNome||"").trim().toLowerCase();
var validas=lista.filter(function(a){
var ac=String(a.cnpj||a.empresaCnpj||"").replace(/\D/g,"");
var an=String(a.empresa||a.empresaNome||"").trim().toLowerCase();
var mesma=(cnpj&&ac===cnpj)||(!cnpj&&nome&&an===nome);
var participou=a.participouProcesso===true||a.candidaturaVerificada===true||a.verificada===true;
return mesma&&participou;
});
var notas=[];
validas.forEach(function(a){
var n=Number(a.notaGeral||a.nota||a.media);
if(!isFinite(n)||n<=0){
var ns=[a.comunicacao,a.clareza,a.organizacao,a.retorno].map(Number).filter(function(x){return isFinite(x)&&x>0;});
if(ns.length)n=ns.reduce(function(s,x){return s+x;},0)/ns.length;
}
if(isFinite(n)&&n>0)notas.push(Math.max(1,Math.min(5,n)));
});
if(!notas.length)return null;
return {media:notas.reduce(function(s,x){return s+x;},0)/notas.length,qtd:notas.length};
}
function empresaVagaVerificadaEM(vaga){
try{
var empresas=JSON.parse(localStorage.getItem("empresasEmpregaMais")||"[]");
var cnpj=String(vaga.cnpj||vaga.empresaCnpj||"").replace(/\D/g,"");
var nome=String(vaga.empresa||vaga.empresaNome||"").trim().toLowerCase();
var emp=empresas.find(function(e){
var ec=String(e.cnpj||"").replace(/\D/g,"");
var en=String(e.nomeFantasia||e.nome||e.razaoSocial||"").trim().toLowerCase();
return (cnpj&&ec===cnpj)||(nome&&en===nome);
});
if(!emp)return false;
var st=String(emp.verificacaoStatus||emp.statusVerificacao||"").toLowerCase();
return emp.verificada===true||st==="verificada"||st==="aprovada";
}catch(e){return false;}
}
