function empresasAdminPlanosEM(){
try{return JSON.parse(localStorage.getItem("empresasEmpregaMais")||"[]");}
catch(e){return [];}
}
function salvarEmpresasAdminPlanosEM(lista){
localStorage.setItem("empresasEmpregaMais",JSON.stringify(lista));
}
function preencherEmpresasPlanoAdminEM(){
var sel=document.getElementById("adminPlanoEmpresaBuscaEM");
if(!sel)return;
var atual=sel.value;
var lista=empresasAdminPlanosEM().slice().sort(function(a,b){
return String(a.nomeFantasia||a.nome||a.razaoSocial||"").localeCompare(String(b.nomeFantasia||b.nome||b.razaoSocial||""),"pt-BR");
});
sel.innerHTML="<option value=''>Selecione uma empresa</option>";
lista.forEach(function(e,i){
var nome=e.nomeFantasia||e.nome||e.razaoSocial||e.email||("Empresa "+(i+1));
var cnpj=String(e.cnpj||"").replace(/\D/g,"");
var op=document.createElement("option");
op.value=cnpj||String(e.email||"").toLowerCase();
op.textContent=nome+(cnpj?" \u2022 "+cnpj.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/,"$1.$2.$3/$4-$5"):"");
sel.appendChild(op);
});
if(Array.from(sel.options).some(function(o){return o.value===atual;}))sel.value=atual;
atualizarResumoPlanoAdminEM();
}
function localizarEmpresaPlanoAdminEM(){
var sel=document.getElementById("adminPlanoEmpresaBuscaEM");
if(!sel||!sel.value)return null;
var chave=sel.value;
return empresasAdminPlanosEM().find(function(e){
var c=String(e.cnpj||"").replace(/\D/g,"");
var email=String(e.email||"").toLowerCase();
return c===chave||email===chave;
})||null;
}
function nomePlanoAdminEM(p){
return {basico:"B\u00E1sico",trimestral:"Trimestral",semestral:"Semestral",anual:"Anual"}[String(p||"").toLowerCase()]||"B\u00E1sico";
}
function atualizarResumoPlanoAdminEM(){
var box=document.getElementById("adminPlanoResumoEM");
if(!box)return;
var e=localizarEmpresaPlanoAdminEM();
if(!e){box.textContent="Selecione uma empresa para visualizar o plano atual.";return;}
var plano=String(e.plano||"basico").toLowerCase();
var origem=e.planoLiberadoPeloAdmin===true?"Libera\u00E7\u00E3o administrativa":"Contrata\u00E7\u00E3o/cadastro";
var fim=e.planoValidoAte?new Date(e.planoValidoAte).toLocaleDateString("pt-BR"):"\u2014";
box.innerHTML="<strong>Plano atual:</strong> "+nomePlanoAdminEM(plano)+" &nbsp; \u2022 &nbsp; <strong>Origem:</strong> "+origem+" &nbsp; \u2022 &nbsp; <strong>V\u00E1lido at\u00E9:</strong> "+fim;
}
function liberarPlanoAdminEM(){
if(typeof adminEstaLogado==="function"&&!adminEstaLogado()){alert("Acesso administrativo necess\u00E1rio.");return;}
var sel=document.getElementById("adminPlanoEmpresaBuscaEM");
var planoEl=document.getElementById("adminPlanoEscolhidoEM");
if(!sel||!sel.value){alert("Selecione uma empresa.");return;}
var plano=String(planoEl&&planoEl.value||"").toLowerCase();
var dias={basico:30,trimestral:90,semestral:180,anual:365}[plano];
if(!dias){alert("Selecione um plano v\u00E1lido.");return;}
var lista=empresasAdminPlanosEM();
var chave=sel.value;
var e=lista.find(function(x){
return String(x.cnpj||"").replace(/\D/g,"")===chave||String(x.email||"").toLowerCase()===chave;
});
if(!e){alert("Empresa n\u00E3o encontrada.");return;}
var agora=new Date();
var fim=new Date(agora.getTime()+dias*86400000);
e.plano=plano;
e.planoId=plano;
e.planoNome=nomePlanoAdminEM(plano);
e.planoInicio=agora.toISOString();
e.planoValidoAte=fim.toISOString();
e.planoLiberadoPeloAdmin=true;
e.planoSemCobranca=true;
e.planoLiberadoEm=agora.toISOString();
salvarEmpresasAdminPlanosEM(lista);
atualizarResumoPlanoAdminEM();
alert("Plano "+nomePlanoAdminEM(plano)+" liberado gratuitamente para a empresa.");
}
function retornarPlanoBasicoAdminEM(){
if(typeof adminEstaLogado==="function"&&!adminEstaLogado()){alert("Acesso administrativo necess\u00E1rio.");return;}
var sel=document.getElementById("adminPlanoEmpresaBuscaEM");
if(!sel||!sel.value){alert("Selecione uma empresa.");return;}
if(!confirm("Deseja retornar esta empresa ao plano B\u00E1sico?"))return;
var lista=empresasAdminPlanosEM(),chave=sel.value;
var e=lista.find(function(x){
return String(x.cnpj||"").replace(/\D/g,"")===chave||String(x.email||"").toLowerCase()===chave;
});
if(!e)return;
e.plano="basico";e.planoId="basico";e.planoNome="B\u00E1sico";
e.planoLiberadoPeloAdmin=false;e.planoSemCobranca=false;
e.planoInicio=new Date().toISOString();
e.planoValidoAte=new Date(Date.now()+30*86400000).toISOString();
salvarEmpresasAdminPlanosEM(lista);
atualizarResumoPlanoAdminEM();
alert("Empresa retornada ao plano B\u00E1sico.");
}
