}
function vagasDaEmpresaPerfilEM(emp){
var todas=[];
try{todas=carregarVagasPortal()||[];}catch(e){}
var cnpj=String(emp.cnpj||"").replace(/\D/g,"");
var nome=String(emp.nomeFantasia||emp.nome||emp.razaoSocial||"").trim().toLowerCase();
return todas.filter(function(v){
var vc=String(v.cnpj||v.empresaCnpj||"").replace(/\D/g,"");
var vn=String(v.empresa||v.empresaNome||"").trim().toLowerCase();
return (cnpj&&vc===cnpj)||(!cnpj&&nome&&vn===nome);
});
}
function abrirMeuPerfilRecrutadorEM(){
var pagina=document.getElementById("pagina-painel-empresa");
if(!pagina)return;
var emp=empresaLogadaPainelEM();
var plano=planoAtualRecrutadorEM(emp);
var vagas=vagasDaEmpresaPerfilEM(emp);
var limite=limiteVagasPlanoPerfilEM(plano);
var usadas=vagas.filter(function(v){
return String(v.status||"").toLowerCase()!=="excluida";
}).length;
var destaques=vagas.filter(function(v){
return v.destaque===true||String(v.destaque).toLowerCase()==="true"||String(v.destaque)==="1";
});
var percentual=Math.min(100,Math.round((usadas/Math.max(1,limite))*100));
var existente=document.getElementById("recrutadorMeuPerfilEM");
if(existente)existente.remove();
var box=document.createElement("section");
box.id="recrutadorMeuPerfilEM";
box.className="recrutador-meu-perfil-em";
var listaDestaques="";
if(destaques.length){
listaDestaques=destaques.map(function(v){
return "<div class='recrutador-destaque-item-em'><strong>"+String(v.cargo||"Vaga sem t\u00EDtulo")+"</strong><span>\u2605 DESTAQUE</span></div>";
}).join("");
}else{
listaDestaques="<div class='recrutador-sem-destaques-em'>Nenhuma vaga est\u00E1 em destaque no momento.</div>";
}
box.innerHTML=
"<div class='recrutador-meu-perfil-cab-em'>"+
"<div><span>MEU PERFIL</span><h3>"+String(emp.nomeFantasia||emp.nome||emp.razaoSocial||"Minha empresa")+"</h3>"+
"<p>Acompanhe seu plano, utiliza\u00E7\u00E3o de vagas e oportunidades em destaque.</p></div>"+
"<div class='recrutador-perfil-plano-em'>Plano "+nomePlanoRecrutadorEM(plano)+"</div>"+
"</div>"+
"<div class='recrutador-perfil-metricas-em'>"+
"<div class='recrutador-perfil-metrica-em'><small>PLANO CONTRATADO</small><strong>"+nomePlanoRecrutadorEM(plano)+"</strong></div>"+
"<div class='recrutador-perfil-metrica-em'><small>VAGAS UTILIZADAS</small><strong>"+usadas+" de "+limite+"</strong>"+
"<div class='recrutador-uso-barra-em'><i style='width:"+percentual+"%'/></div></div>"+
"<div class='recrutador-perfil-metrica-em'><small>VAGAS EM DESTAQUE</small><strong>"+destaques.length+"</strong></div>"+
"</div>"+
"<div class='recrutador-destaques-lista-em'><h4>Vagas atualmente em destaque</h4>"+listaDestaques+"</div>";
var central=document.getElementById("recrutadorCentralEM");
if(central)central.insertAdjacentElement("afterend",box);
else{
var alvo=pagina.querySelector(".container,.painel-container,.conteudo")||pagina;
alvo.insertBefore(box,alvo.firstChild);
}
box.scrollIntoView({behavior:"smooth",block:"start"});
}
