function atualizarCentralAdminEM(){
var box=document.getElementById("adminCentralComandoEM");
if(!box)return;
var empresas=lerArrayAdminCentralEM("empresasEmpregaMais");
var candidatos=lerArrayAdminCentralEM("candidatosEmpregaMais");
var vagas=[];
try{vagas=carregarVagasPortal()||[];}catch(e){}
var verificadas=empresas.filter(function(e){
var s=String(e.verificacaoStatus||e.statusVerificacao||"").toLowerCase();
return e.verificada===true||s==="verificada"||s==="aprovada";
}).length;
var verificacoesPendentes=empresas.filter(function(e){
var s=String(e.verificacaoStatus||e.statusVerificacao||"").toLowerCase();
return s==="pendente"||s==="em analise"||s==="em an\u00E1lise"||s==="enviada";
}).length;
var vagasPendentes=vagas.filter(function(v){
return String(v.status||"").toLowerCase()!=="encerrada" &&
String(v.aprovacao||"").toLowerCase()==="pendente";
}).length;
var ativas=vagas.filter(function(v){
return String(v.status||"ativa").toLowerCase()==="ativa" &&
String(v.aprovacao||"aprovada").toLowerCase()!=="pendente";
}).length;
var destaques=vagas.filter(function(v){
return v.destaque===true||String(v.destaque).toLowerCase()==="true"||String(v.destaque)==="1";
}).length;
function set(id,n){var el=document.getElementById(id);if(el)el.textContent=n;}
set("admMetricaEmpresasEM",empresas.length);
set("admMetricaVerificadasEM",verificadas);
set("admMetricaVagasAtivasEM",ativas);
set("admMetricaPendentesEM",vagasPendentes);
set("admMetricaDestaquesEM",destaques);
set("admMetricaCandidatosEM",candidatos.length);
var lista=document.getElementById("adminPendenciasListaEM");
if(!lista)return;
var itens=[];
if(vagasPendentes)itens.push({icone:"!",texto:"Vagas aguardando aprova\u00E7\u00E3o",qtd:vagasPendentes});
if(verificacoesPendentes)itens.push({icone:"\u2713",texto:"Empresas aguardando verifica\u00E7\u00E3o",qtd:verificacoesPendentes});
if(!itens.length){
lista.innerHTML="<div class='admin-pendencias-vazio-em'>Nenhuma pend\u00EAncia administrativa identificada no momento.</div>";
}else{
lista.innerHTML=itens.map(function(x){
return "<div class='admin-pendencia-item-em'><div><i>"+x.icone+"</i>"+x.texto+"</div><strong>"+x.qtd+"</strong></div>";
}).join("");
}
}
