var cidadesPerfilCarregadasEM=false;
function carregarCidadesPerfilLimpoEM(){
if(cidadesPerfilCarregadasEM)return;
var lista=document.getElementById("listaCidadesPerfilEM");
if(!lista)return;
var cache=[];
try{cache=JSON.parse(localStorage.getItem("cidadesPerfilEmpregaMaisV2")||"[]");}catch(e){}
if(cache.length){
cache.forEach(function(nome){
if(!lista.querySelector('option[value="'+String(nome).replace(/"/g,'\\"')+'"]')){
var op=document.createElement("option");op.value=nome;lista.appendChild(op);
}
});
cidadesPerfilCarregadasEM=true;
return;
}
fetch("https://servicodados.ibge.gov.br/api/v1/localidades/municipios?orderBy=nome")
.then(function(r){if(!r.ok)throw new Error("IBGE");return r.json();})
.then(function(municipios){
var nomes=municipios.map(function(m){
var uf="";
try{uf=m.microrregiao.mesorregiao.UF.sigla||"";}catch(e){}
return m.nome+(uf?" - "+uf:"");
});
try{localStorage.setItem("cidadesPerfilEmpregaMaisV2",JSON.stringify(nomes));}catch(e){}
nomes.forEach(function(nome){
var op=document.createElement("option");op.value=nome;lista.appendChild(op);
});
cidadesPerfilCarregadasEM=true;
})
.catch(function(){ cidadesPerfilCarregadasEM=true; });
}
