function mesclarEmpresasRemotasEM(remotas){
var locais=empresasCadastradas(), mapa={};
locais.forEach(function(e){
var c=String(e.cnpj||"").replace(/\D/g,"");
if(c)mapa[c]=e;
});
(remotas||[]).forEach(function(rem){
var c=String(rem.cnpj||"").replace(/\D/g,"");
if(!c)return;
var local=mapa[c]||{}, senha=local.senha;
Object.keys(rem).forEach(function(k){local[k]=rem[k];});
if(senha)local.senha=senha;
mapa[c]=local;
});
var final=Object.keys(mapa).map(function(k){return mapa[k];});
salvarArray("empresasEmpregaMais",final);
return final;
}
