loginEmpresa=function(event){
event.preventDefault();
var cnpj=String(document.getElementById("loginEmpresaCnpj").value||"").replace(/\D/g,"");
var senha=String(document.getElementById("loginEmpresaSenha").value||"");
if(cnpj.length!==14||!senha){alert("Informe CNPJ e senha.");return;}
apiEmpregaMaisPost({acao:"loginEmpresa",cnpj:cnpj,senha:senha}).then(function(r){
if(!r||r.sucesso!==true||!r.empresa)throw new Error("login");
var lista=empresasCadastradas(), achou=false;
for(var i=0;i<lista.length;i++){
if(String(lista[i].cnpj||"").replace(/\D/g,"")===cnpj){
var senhaLocal=lista[i].senha;
Object.keys(r.empresa).forEach(function(k){lista[i][k]=r.empresa[k];});
if(senhaLocal)lista[i].senha=senhaLocal;
achou=true;break;
}
}
if(!achou)lista.push(r.empresa);
salvarArray("empresasEmpregaMais",lista);
entrarComoEmpresa(r.empresa);
irPara("painel-empresa");
setTimeout(sincronizarEmpresasGoogleSheetsEM,100);
}).catch(function(){
var lista=empresasCadastradas(), emp=null;
for(var i=0;i<lista.length;i++){
if(String(lista[i].cnpj||"").replace(/\D/g,"")===cnpj&&lista[i].senha===senha){emp=lista[i];break;}
}
if(!emp){alert("CNPJ ou senha incorretos.");return;}
entrarComoEmpresa(emp);
salvarEmpresaRemotaEM(emp).catch(function(){});
irPara("painel-empresa");
});
};
