function migrarEmpresaLocalParaServidorEM(){
var emp=null;
try{ emp=obterEmpresaAtual(); }catch(e){}
if(!emp){
try{
var lista=empresasCadastradas();
if(lista&&lista.length===1) emp=lista[0];
}catch(e){}
}
if(!emp || !emp.cnpj) return Promise.resolve(false);
emp=normalizarStatusVerificacaoServidorEM(emp);
var cnpj=String(emp.cnpj||"").replace(/\D/g,"");
return apiEmpregaMaisGet("empresa&cnpj="+encodeURIComponent(cnpj))
.catch(function(){return null;})
.then(function(resp){
return salvarEmpresaRemotaEM(emp);
})
.then(function(resp){
if(!resp || resp.sucesso!==true){
throw new Error((resp&&resp.erro)||"N\u00E3o foi poss\u00EDvel migrar a empresa.");
}
return sincronizarEmpresasGoogleSheetsEM();
})
.then(function(){
atualizarPaineisEmpresasIntegradasEM();
return true;
})
.catch(function(err){
console.warn("Migra\u00E7\u00E3o da empresa para o servidor:",err);
return false;
});
}
