function localizarEmpresaLogadaParaServidorEM(){
var lista=[];
try{ lista=empresasCadastradas()||[]; }catch(e){}
if(!Array.isArray(lista)) lista=[];
var candidatosChave=[];
[
sessionStorage.getItem("empresaCnpj"),
sessionStorage.getItem("cnpjEmpresa"),
sessionStorage.getItem("empresaLogadaCnpj"),
localStorage.getItem("empresaCnpj"),
localStorage.getItem("cnpjEmpresa")
].forEach(function(v){
var c=String(v||"").replace(/\D/g,"");
if(c.length===14)candidatosChave.push(c);
});
try{
var atual=obterEmpresaAtual();
if(atual&&atual.cnpj)return atual;
}catch(e){}
for(var i=0;i<lista.length;i++){
var c=String(lista[i].cnpj||"").replace(/\D/g,"");
if(c&&candidatosChave.indexOf(c)>=0)return lista[i];
}
if(lista.length===1&&lista[0]&&lista[0].cnpj)return lista[0];
var painel=document.getElementById("pagina-painel-empresa");
var texto=String(painel?painel.innerText:"").toLowerCase();
for(var j=0;j<lista.length;j++){
var nome=String(lista[j].nomeFantasia||lista[j].nome||lista[j].razaoSocial||"").trim();
if(nome&&texto.indexOf(nome.toLowerCase())>=0)return lista[j];
}
return null;
}
function prepararEmpresaParaServidorEM(emp){
if(!emp)return null;
var copia={};
Object.keys(emp).forEach(function(k){copia[k]=emp[k];});
var st=String(
copia.verificacaoStatus ||
copia.statusVerificacao ||
copia.verificacao ||
""
).toLowerCase().trim();
var painel=document.getElementById("pagina-painel-empresa");
var texto=String(painel?painel.innerText:"").toLowerCase();
if(
st==="em_analise" || st==="em analise" || st==="em an\u00E1lise" ||
st==="pendente" || copia.verificacaoPendente===true ||
copia.perfilEmAnalise===true || texto.indexOf("verifica\u00E7\u00E3o em an\u00E1lise")>=0 ||
texto.indexOf("verificacao em analise")>=0 ||
texto.indexOf("aguardando an\u00E1lise administrativa")>=0
){
copia.verificacaoStatus="em_analise";
copia.statusVerificacao="em_analise";
copia.verificacaoPendente=true;
copia.perfilEmAnalise=true;
copia.verificada=false;
if(!copia.verificacaoEnviadaEm)copia.verificacaoEnviadaEm=new Date().toISOString();
}
if(!copia.plano)copia.plano="basico";
if(!copia.planoId)copia.planoId=copia.plano;
return copia;
}
function enviarEmpresaLogadaServidorForcadoEM(){
var emp=localizarEmpresaLogadaParaServidorEM();
if(!emp||!emp.cnpj){
console.warn("EmpregaMais: empresa logada n\u00E3o localizada para envio.");
return Promise.resolve(false);
}
var envio=prepararEmpresaParaServidorEM(emp);
return apiEmpregaMaisPost({
acao:"salvarEmpresa",
empresa:envio
}).then(function(resp){
if(!resp||resp.sucesso!==true){
throw new Error((resp&&resp.erro)||"Servidor recusou o cadastro da empresa.");
}
console.log("EmpregaMais: empresa sincronizada no servidor.",resp.empresa||envio.cnpj);
return sincronizarEmpresasGoogleSheetsEM().then(function(){return true;});
}).catch(function(err){
console.error("EmpregaMais: falha ao enviar empresa ao servidor.",err);
return false;
});
}
