(function(){
var DB="EmpregaMaisMidiasV31", STORE="imagens";
function chave(){
return String(sessionStorage.getItem("empresaCnpj")||sessionStorage.getItem("empresaEmail")||"empresa")
.replace(/[^a-zA-Z0-9@._-]/g,"");
}
function db(){
return new Promise(function(ok,erro){
var r=indexedDB.open(DB,1);
r.onupgradeneeded=function(){if(!r.result.objectStoreNames.contains(STORE))r.result.createObjectStore(STORE);};
r.onsuccess=function(){ok(r.result);};r.onerror=function(){erro(r.error);};
});
}
function guardar(tipo,blob){
return db().then(function(d){return new Promise(function(ok,erro){
var tx=d.transaction(STORE,"readwrite");
tx.objectStore(STORE).put(blob,chave()+"_"+tipo);
tx.oncomplete=function(){d.close();ok();};tx.onerror=function(){d.close();erro(tx.error);};
});});
}
function buscar(tipo){
return db().then(function(d){return new Promise(function(ok){
var r=d.transaction(STORE,"readonly").objectStore(STORE).get(chave()+"_"+tipo);
r.onsuccess=function(){var v=r.result;d.close();ok(v||null);};
r.onerror=function(){d.close();ok(null);};
});}).catch(function(){return null;});
}
function url(b){return b?URL.createObjectURL(b):"";}
function validar(arq,tipo){
if(!arq)return "Selecione uma imagem.";
if(!/^image\/(png|jpeg|webp)$/i.test(arq.type))return "Use JPG, PNG ou WEBP.";
if(arq.size>3*1024*1024)return "A imagem deve ter no maximo 3 MB.";
return "";
}
function dimensoes(arq){
return new Promise(function(ok,erro){
var u=url(arq),i=new Image();
i.onload=function(){var x={w:i.naturalWidth,h:i.naturalHeight};URL.revokeObjectURL(u);ok(x);};
i.onerror=function(){URL.revokeObjectURL(u);erro();};i.src=u;
});
}
function status(tipo,txt,ok){
var e=document.getElementById(tipo==="logo"?"statusLogoV31":"statusCapaV31");
if(e){e.textContent=txt;e.classList.toggle("ok-v31",!!ok);}
}
async function escolher(input,tipo){
var arq=input.files&&input.files[0],er=validar(arq,tipo);
if(er){alert(er);input.value="";return;}
try{
var d=await dimensoes(arq);
if(tipo==="logo"&&(d.w<300||d.h<300)){alert("A logo precisa ter pelo menos 300 x 300 px.");input.value="";return;}
if(tipo==="capa"&&(d.w<1200||d.h<400)){alert("A capa precisa ter pelo menos 1200 x 400 px.");input.value="";return;}
status(tipo,"Salvando...",false);
await guardar(tipo,arq);
var campo=document.getElementById(tipo==="logo"?"perfilLogoEM":"perfilCapaEM");
if(campo)campo.value="midia-v31:"+tipo;
var prev=document.getElementById(tipo==="logo"?"previewLogoV31":"previewCapaV31");
if(prev){prev.src=url(arq);prev.style.display="block";}
status(tipo,"Imagem salva",true);
}catch(e){console.error(e);status(tipo,"Falha ao salvar",false);alert("N\u00E3o foi poss\u00EDvel salvar a imagem.");}
}
function card(tipo){
var c=document.createElement("div");
c.className="midia-card-v31";
c.innerHTML=
"<div class='midia-head-v31'><div><strong>"+(tipo==="logo"?"Logo da empresa":"Imagem de capa")+"</strong>"+
"<span>"+(tipo==="logo"?"Recomendado 500 x 500 px | minimo 300 x 300 px":"Recomendado 1600 x 500 px | minimo 1200 x 400 px")+"</span></div>"+
"<b>"+(tipo==="logo"?"QUADRADA":"HORIZONTAL")+"</b></div>"+
"<div class='midia-preview-v31 "+tipo+"'><img id='"+(tipo==="logo"?"previewLogoV31":"previewCapaV31")+"' alt='Previa'/><div><strong>"+(tipo==="logo"?"LOGO":"CAPA")+"</strong><small>Previa da imagem</small></div></div>"+
"<div class='midia-action-v31'><label>Selecionar imagem<input type='file' accept='image/png,image/jpeg,image/webp'/></label><span id='"+(tipo==="logo"?"statusLogoV31":"statusCapaV31")+"'>JPG, PNG ou WEBP | ate 3 MB</span></div>";
c.querySelector("input").addEventListener("change",function(){escolher(this,tipo);});
return c;
}
