function textoSelecionado(box){
var nomes=[];
box.querySelectorAll(".beneficio-v128 input:checked").forEach(function(inp){
nomes.push(inp.getAttribute("data-nome"));
});
var outro=box.querySelector("#beneficiosOutroV128");
if(outro&&outro.value.trim())nomes.push(outro.value.trim());
return nomes.join(", ");
}
function sincronizar(box){
var hidden=document.getElementById("beneficiosVaga");
var texto=textoSelecionado(box);
if(hidden)hidden.value=texto;
box.dataset.beneficios=texto;
var cont=box.querySelector(".beneficios-contador-v128");
var n=box.querySelectorAll(".beneficio-v128 input:checked").length;
if(cont)cont.textContent=n+(n===1?" benefício selecionado":" benefícios selecionados");
}
