if(!alvo)return;
var box=document.createElement("div");
box.id="beneficiosCardsV128";
box.className="beneficios-v128";
var html='<div class="beneficios-topo-v128"><span class="beneficios-icone-v128">♡</span><div><strong>Benefícios oferecidos</strong><p>Selecione tudo o que a empresa oferece para esta oportunidade.</p></div></div><div class="beneficios-grid-v128">';
