});
html+='</div><div class="beneficio-outro-v128"><input class="campo" id="beneficiosOutroV128" type="text" placeholder="Outro benefício (opcional)"/></div><div class="beneficios-contador-v128">0 benefícios selecionados</div>';
box.innerHTML=html;
alvo.insertAdjacentElement("afterend",box);
var hidden=document.getElementById("beneficiosVaga");
if(hidden){
var grupo=hidden.closest(".grupo");
if(grupo)grupo.style.display="none";
var antigos=String(hidden.value||"").split(",").map(function(x){return x.trim().toLowerCase()});
box.querySelectorAll(".beneficio-v128 input").forEach(function(inp){
if(antigos.indexOf(String(inp.value).toLowerCase())!==-1)inp.checked=true;
});
}else{
hidden=document.createElement("input");
hidden.type="hidden";hidden.id="beneficiosVaga";hidden.name="beneficios";
form.appendChild(hidden);
}
box.addEventListener("change",function(){sincronizar(box)});
box.querySelector("#beneficiosOutroV128").addEventListener("input",function(){sincronizar(box)});
sincronizar(box);
}
